INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a99c1676-7cc6-4ba2-aaec-9b7df92074e7', '和徐侍郎書叢篠韻', '和徐侍郎书叢篠韻', 'c11e9e2e-0f9b-4c48-ae97-ab1ada720fe6', '唐', '["中禁夕沈沈，幽篁別作林。","色連雞樹近，影落鳳池深。","爲重凌霜節，能虛應物心。","年年承雨露，長對紫庭陰。"]', '["中禁夕沈沈，幽篁別作林。","色連雞樹近，影落鳳池深。","爲重凌霜節，能虛應物心。","年年承雨露，长对紫庭陰。"]', '诗', 'shi', '', NULL, '和徐侍郎書叢篠韻 蔣渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee558237-de12-44dd-a03c-a49bb884e45a', '故太常卿贈禮部尚書李公及夫人輓歌二首 一', '故太常卿贈禮部尚书李公及夫人輓歌二首 一', 'c11e9e2e-0f9b-4c48-ae97-ab1ada720fe6', '唐', '["白簡嘗持憲，黃圖復尹京。","能標百郡則，威肅一朝清。","典秩崇三禮，臨戍振五兵。","更聞傳世業，才子有高名。"]', '["白簡嘗持憲，黄圖复尹京。","能標百郡則，威肅一朝清。","典秩崇三禮，臨戍振五兵。","更闻傳世業，才子有高名。"]', '诗', 'shi', '', NULL, '故太常卿贈禮部尚書李公及夫人輓歌二首 一 蔣渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96528a7-cbcd-4271-90c1-59fb9242eef4', '故太常卿贈禮部尚書李公及夫人輓歌二首 二', '故太常卿贈禮部尚书李公及夫人輓歌二首 二', 'c11e9e2e-0f9b-4c48-ae97-ab1ada720fe6', '唐', '["封樹遵同穴，生平此共歸。","鏡埋鸞已去，泉掩鳳何飛。","薤輓疑笳曲，松風思翟衣。","揚名將寵贈，泉路滿光輝。"]', '["封樹遵同穴，生平此共归。","镜埋鸾已去，泉掩鳳何飞。","薤輓疑笳曲，松风思翟衣。","揚名將寵贈，泉路满光輝。"]', '诗', 'shi', '', NULL, '故太常卿贈禮部尚書李公及夫人輓歌二首 二 蔣渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6a491e-d3b5-4a63-8b7e-49e073551a4f', '挽湧泉寺僧懷玉', '挽湧泉寺僧懷玉', '0aff3903-db33-4e08-b561-2a3351cf01e5', '唐', '["我師一念登初地，佛國笙歌兩度來。","唯有門前古槐樹，枝低只爲挂銀臺。"]', '["我師一念登初地，佛国笙歌兩度来。","唯有门前古槐樹，枝低只爲挂銀台。"]', '诗', 'shi', '', NULL, '挽湧泉寺僧懷玉 段懷然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df89fc3-7295-4b8b-b839-e19186eb453b', '辭房相公', '辞房相公', '25f572fb-3ead-4792-9d02-a0a7a2e313f3', '唐', '["秋風颯颯雨霏霏，愁殺恓遑一布衣。","辭君且作隨陽鳥，海內無家何處歸。"]', '["秋风颯颯雨霏霏，愁殺恓遑一布衣。","辞君且作隨陽鸟，海內無家何处归。"]', '诗', 'shi', '', NULL, '辭房相公 張偁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840561f4-66b7-4c22-9083-b5e727226c2a', '移耶溪舊居呈陳元初校書', '移耶溪旧居呈陳元初校书', '94a75a7e-e061-4d0c-ad51-4a63d6d129d6', '唐', '["雞犬漁舟裏，長謠任興行。","即令邀客醉，已被遠山迎。","書笈將非重，荷衣著甚輕。","謝安無個事，忽起爲蒼生。"]', '["雞犬漁舟裏，长謠任兴行。","即令邀客醉，已被远山迎。","书笈將非重，荷衣著甚轻。","謝安無個事，忽起爲蒼生。"]', '诗', 'shi', '', NULL, '移耶溪舊居呈陳元初校書 陳孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7347c32f-e075-48f9-8e30-ef07fcf12360', '西河郡太原守張夫人挽歌', '西河郡太原守張夫人挽歌', 'ead995b9-a321-40b5-8f10-f68e3056ced1', '唐', '["鵲印慶仍傳，魚軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龍是雙歸日，鸞非獨舞年。","哀榮今共盡，悽愴杜陵田。"]', '["鵲印慶仍傳，鱼軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龙是雙归日，鸾非独舞年。","哀榮今共尽，悽愴杜陵田。"]', '诗', 'shi', '', NULL, '西河郡太原守張夫人挽歌 李峯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc6d8301-56b5-401b-93c8-bd3085108143', '感懷弟妹', '感懷弟妹', '68253789-6afb-4231-ae1a-974b03eb68b0', '唐', '["今日春氣暖，東風杏花拆。","筋力久不如，却羨澗中石。","神仙杳難準，中壽稀滿百。","近世多夭傷，喜見鬢髮白。","杖藜竹樹間，宛宛舊行跡。","豈知林園主，却是林園客。","兄弟可存半，空爲亡者惜。","冥冥無再期，哀哀望松柏。","骨肉能幾人，年大自疎隔。","性情誰免此，與我不相易。","唯念得爾輩，時看慰朝夕。","平生茲已矣，此外盡非適。"]', '["今日春氣暖，东风杏花拆。","筋力久不如，却羨澗中石。","神仙杳难準，中壽稀满百。","近世多夭傷，喜见鬢髮白。","杖藜竹樹间，宛宛旧行跡。","豈知林园主，却是林园客。","兄弟可存半，空爲亡者惜。","冥冥無再期，哀哀望松柏。","骨肉能幾人，年大自疎隔。","性情誰免此，與我不相易。","唯念得爾輩，时看慰朝夕。","平生茲已矣，此外尽非適。"]', '诗', 'shi', '', NULL, '感懷弟妹 沈千運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2c31b1-5107-41c6-8ae6-723852061d89', '贈史脩文', '贈史脩文', '68253789-6afb-4231-ae1a-974b03eb68b0', '唐', '["故人阻千里，會面非別期。","握手於此地，當歡反成悲。","念離宛猶昨，俄已經數期。","疇昔皆少年，別來鬢如絲。","不道舊姓名，相逢知是誰。","曩遊盡騫翥，與君仍布衣。","豈曰無其才，命理應有時。","別路漸欲少，不覺生涕洟。"]', '["故人阻千里，會面非別期。","握手於此地，當歡反成悲。","念離宛猶昨，俄已經數期。","疇昔皆少年，別来鬢如絲。","不道旧姓名，相逢知是誰。","曩游尽騫翥，與君仍布衣。","豈曰無其才，命理應有时。","別路漸欲少，不覺生涕洟。"]', '诗', 'shi', '', NULL, '贈史脩文 沈千運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294f0816-30dd-4941-bb26-bb50378c91b0', '濮中言懷', '濮中言懷', '68253789-6afb-4231-ae1a-974b03eb68b0', '唐', '["聖朝優賢良，草澤無遺匿。","人生各有命，在余胡不淑。","一生但區區，五十無寸祿。","衰退當棄捐，貧賤招毀讟。","栖栖去人世，屯躓日窮迫。","不如守田園，歲晏望豐熟。","壯年失宜盡，老大無筋力。","始覺前計非，將貽後生福。","童兒新學稼，少女未能織。","顧此煩知己，終日求衣食。"]', '["聖朝優賢良，草澤無遺匿。","人生各有命，在余胡不淑。","一生但區區，五十無寸祿。","衰退當棄捐，貧賤招毀讟。","栖栖去人世，屯躓日窮迫。","不如守田园，歲晏望豐熟。","壯年失宜尽，老大無筋力。","始覺前計非，將貽後生福。","童兒新学稼，少女未能织。","顧此煩知己，終日求衣食。"]', '诗', 'shi', '', NULL, '濮中言懷 沈千運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6752672-3fd9-441d-a73b-3693a777f9bd', '山中作', '山中作', '68253789-6afb-4231-ae1a-974b03eb68b0', '唐', '["栖隱非別事，所願離風塵。","不辭城邑遊，禮樂拘束人。","邇來歸山林，庶事皆吾身。","何者爲形骸，誰是智與仁。","寂寞了閑事，而後知天真。","咳唾矜崇華，迂俯相屈伸。","如何巢與由，天子不知臣。"]', '["栖隐非別事，所願離风塵。","不辞城邑游，禮乐拘束人。","邇来归山林，庶事皆吾身。","何者爲形骸，誰是智與仁。","寂寞了闲事，而後知天真。","咳唾矜崇华，迂俯相屈伸。","如何巢與由，天子不知臣。"]', '诗', 'shi', '', NULL, '山中作 沈千運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56981f4f-ed7a-47b4-9d7f-6d1438bc43e5', '古歌', '古歌', '68253789-6afb-4231-ae1a-974b03eb68b0', '唐', '["北邙不種田，但種松與柏。","松柏未生處，留待市朝客。"]', '["北邙不種田，但種松與柏。","松柏未生处，留待市朝客。"]', '诗', 'shi', '', NULL, '古歌 沈千運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf23d3c-28d0-4c68-af69-96cd4bb1d5ce', '別李季友', '別李季友', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["栖鳥不戀枝，喈喈在同聲。","行子馳出戶，依依主人情。","昔時霜臺鏡，醜婦羞爾形。","閉匣二十年，皎潔常獨明。","今日照離別，前途白髮生。"]', '["栖鸟不戀枝，喈喈在同声。","行子驰出戶，依依主人情。","昔时霜台镜，醜婦羞爾形。","閉匣二十年，皎潔常独明。","今日照離別，前途白髮生。"]', '诗', 'shi', '', NULL, '別李季友 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d48727-36b3-4570-99e0-3bc5c83a9e55', '寄韋子春', '寄韋子春', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["出山秋雲曙，山木已再春。","食我山中藥，不憶山中人。","山中誰余密，白髮日相親。","雀鼠畫夜無，知我廚廩貧。","依依北舍松，不厭吾南隣。","有情盡棄捐，土石爲同身。","夫子質千尋，天澤枝葉新。","余以不材壽，非智免斧斤。"]', '["出山秋云曙，山木已再春。","食我山中藥，不憶山中人。","山中誰余密，白髮日相親。","雀鼠畫夜無，知我廚廩貧。","依依北舍松，不厭吾南隣。","有情尽棄捐，土石爲同身。","夫子質千尋，天澤枝葉新。","余以不材壽，非智免斧斤。"]', '诗', 'shi', '', NULL, '寄韋子春 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e384335e-1903-46b3-88c7-701ea37ec87c', '雜詩', '杂诗', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["采山仍采隱，在山不在深。","持斧事遠遊，固非匠者心。","翳翳青桐枝，樵爨日所侵。","斧聲出巖壑，四聽無知音。","豈爲鼎下薪，當復堂上琴。","鳳鳥久不栖，且與枳棘林。"]', '["采山仍采隐，在山不在深。","持斧事远游，固非匠者心。","翳翳青桐枝，樵爨日所侵。","斧声出巖壑，四听無知音。","豈爲鼎下薪，當复堂上琴。","鳳鸟久不栖，且與枳棘林。"]', '诗', 'shi', '', NULL, '雜詩 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fc0c960-e128-4947-abd5-8f7d3b3027a5', '滑中贈崔高士瑾', '滑中贈崔高士瑾', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["夫子保藥命，外身得無咎。","日月不能老，化腸爲筯否。","十年前見君，甲子過我壽。","于何今相逢，華髮在我後。","近而知其遠，少見今白首。","遙信蓬萊宮，不死世世有。","玄石采盈擔，神方秘其肘。","問家惟指雲，愛氣常言酒。","攝生固如此，履道當不朽。","未能太玄同，願亦天地久。","實腹以芝朮，賤形乃芻狗。","自勉將勉余，良藥在苦口。"]', '["夫子保藥命，外身得無咎。","日月不能老，化腸爲筯否。","十年前见君，甲子過我壽。","于何今相逢，华髮在我後。","近而知其远，少见今白首。","遙信蓬萊宮，不死世世有。","玄石采盈擔，神方秘其肘。","问家惟指云，愛氣常言酒。","攝生固如此，履道當不朽。","未能太玄同，願亦天地久。","實腹以芝朮，賤形乃芻狗。","自勉將勉余，良藥在苦口。"]', '诗', 'shi', '', NULL, '滑中贈崔高士瑾 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafe58c9-1ace-4b59-a16a-e0a88c395d46', '還山留別長安知己', '還山留別长安知己', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["出山不見家，還山見家在。","山門是門前，此去長樵采。","青溪誰招隱，白髮自相待。","惟餘澗底松，依依色不改。"]', '["出山不见家，還山见家在。","山门是门前，此去长樵采。","青溪誰招隐，白髮自相待。","惟餘澗底松，依依色不改。"]', '诗', 'shi', '', NULL, '還山留別長安知己 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d34b6e-d2f9-4c75-9a36-c20740e4cd2e', '代賀若令譽贈沈千運', '代賀若令譽贈沈千運', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["相逢問姓名亦存，別時無子今有孫。","山上雙松長不改，百家唯有三家村。","村南村西車馬道，一宿通舟水浩浩。","澗中磊磊十里石，河上淤泥種桑麥。","平坡冢墓皆我親，滿田主人是舊客。","舉聲酸鼻問同年，十人六七歸下泉。","分手如何更此地，回頭不語淚潸然。"]', '["相逢问姓名亦存，別时無子今有孫。","山上雙松长不改，百家唯有三家村。","村南村西车马道，一宿通舟水浩浩。","澗中磊磊十里石，河上淤泥種桑麦。","平坡冢墓皆我親，满田主人是旧客。","舉声酸鼻问同年，十人六七归下泉。","分手如何更此地，回头不語泪潸然。"]', '诗', 'shi', '', NULL, '代賀若令譽贈沈千運 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5677dd61-8afe-41a2-8f49-8e5e6f032c6a', '酬李十六岐', '酬李十六岐', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["鍊丹文武火未成，賣藥販履俱逃名。","出谷迷行洛陽道，乘流醉臥滑臺城。","城下故人久離怨，一歡適我兩家願。","朝飲杖懸沽酒錢，暮餐囊有松花飯。","于何車馬日憧憧，李膺門館爭登龍。","千賓揖對若流水，五經發難如叩鐘。","下筆新詩行滿壁，立談古人坐在席。","問我草堂有臥雲，知我山儲無儋石。","自耕自刈食爲天，如鹿如麋飲野泉。","亦知世上公卿貴，且養丘中草木年。"]', '["鍊丹文武火未成，賣藥販履俱逃名。","出谷迷行洛陽道，乘流醉臥滑台城。","城下故人久離怨，一歡適我兩家願。","朝饮杖懸沽酒錢，暮餐囊有松花飯。","于何车马日憧憧，李膺门館爭登龙。","千賓揖对若流水，五經發难如叩鐘。","下笔新诗行满壁，立談古人坐在席。","问我草堂有臥云，知我山儲無儋石。","自耕自刈食爲天，如鹿如麋饮野泉。","亦知世上公卿貴，且養丘中草木年。"]', '诗', 'shi', '', NULL, '酬李十六岐 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d398524-cb92-4ff5-ba2b-99a75e2920b9', '宿東溪李十五山亭', '宿东溪李十五山亭', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["上山下山入山谷，溪中落日留我宿。","松石依依當主人，主人不在意亦足。","名花出地兩重階，絕頂平天一小齋。","本意由來是山水，何用相逢語舊懷。"]', '["上山下山入山谷，溪中落日留我宿。","松石依依當主人，主人不在意亦足。","名花出地兩重階，絕頂平天一小斋。","本意由来是山水，何用相逢語旧懷。"]', '诗', 'shi', '', NULL, '宿東溪李十五山亭 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485c7865-21ae-4cbb-b924-c0ace8600acc', '觀于舍人壁畫山水', '观于舍人壁畫山水', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["野人宿在人家少，朝見此山謂山曉。","半壁仍棲嶺上雲，開簾欲放湖中鳥。","獨坐長松是阿誰，再三招手起來遲。","于公大笑向予說，小弟丹青能爾爲。"]', '["野人宿在人家少，朝见此山謂山晓。","半壁仍棲嶺上云，开簾欲放湖中鸟。","独坐长松是阿誰，再三招手起来遲。","于公大笑向予说，小弟丹青能爾爲。"]', '诗', 'shi', '', NULL, '觀于舍人壁畫山水 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972d6ce8-67dd-4433-b92d-7df7315d7772', '玉壺冰', '玉壺冰', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["玉壺知素結，止水復中澄。","堅白能虛受，清寒得自凝。","分形同曉鏡，照物掩宵燈。","壁映圓光入，人驚爽氣凌。","金罍何足貴，瑤席幾回升。","正值求珪瓚，提攜共飲冰。"]', '["玉壺知素結，止水复中澄。","堅白能虛受，清寒得自凝。","分形同晓镜，照物掩宵灯。","壁映圓光入，人驚爽氣凌。","金罍何足貴，瑤席幾回升。","正值求珪瓚，提携共饮冰。"]', '诗', 'shi', '', NULL, '玉壺冰 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffdb69e2-6a36-460f-8aa0-24114e19045f', '古塞曲', '古塞曲', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["進軍飛狐北，窮寇勢將變。","日落沙塵昏，背河更一戰。","騂馬黃金勒，雕弓白羽箭。","射殺左賢王，歸奏未央殿。","欲言塞下事，天子不召見。","東出咸陽門，哀哀淚如霰。"]', '["進軍飞狐北，窮寇勢將变。","日落沙塵昏，背河更一戰。","騂马黄金勒，雕弓白羽箭。","射殺左賢王，归奏未央殿。","欲言塞下事，天子不召见。","东出咸陽门，哀哀泪如霰。"]', '诗', 'shi', '', NULL, '古塞曲 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c99c2a8-57c9-4e5c-8198-34bee272ad8b', '野外行', '野外行', '6a48cd73-641b-478a-be56-50d2b8a89eef', '唐', '["老病無樂事，歲秋悲更長。","窮郊日蕭索，生意已蒼黃。","小弟髮亦白，兩男俱不強。","有才且未達，況我非賢良。","幸以朽鈍姿，野外老風霜。","寒鴉噪晚景，喬木思故鄉。","魏人宅蓬池，結網佇鱣魴。","水清魚不來，歲暮空徬徨。"]', '["老病無乐事，歲秋悲更长。","窮郊日蕭索，生意已蒼黄。","小弟髮亦白，兩男俱不強。","有才且未達，況我非賢良。","幸以朽鈍姿，野外老风霜。","寒鴉噪晚景，喬木思故乡。","魏人宅蓬池，結網佇鱣魴。","水清鱼不来，歲暮空徬徨。"]', '诗', 'shi', '', NULL, '野外行 于逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c200f68d-d184-4895-b9dd-bbc56d384e6c', '憶舍弟', '憶舍弟', '6a48cd73-641b-478a-be56-50d2b8a89eef', '唐', '["衰門少兄弟，兄弟唯兩人。","飢寒各流浪，感念傷我神。","夏期秋未來，安知無他因。","不怨別天長，但願見爾身。","茫茫天地間，萬類各有親。","安知汝與我，乖隔同胡秦。","何時對形影，憤懣當共陳。"]', '["衰门少兄弟，兄弟唯兩人。","飢寒各流浪，感念傷我神。","夏期秋未来，安知無他因。","不怨別天长，但願见爾身。","茫茫天地间，万類各有親。","安知汝與我，乖隔同胡秦。","何时对形影，憤懣當共陳。"]', '诗', 'shi', '', NULL, '憶舍弟 于逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37672f9c-0684-489c-bbf4-8f3dee9e5d35', '雜詩', '杂诗', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["富貴多勝事，貪賤無良圖。","上德兼濟心，中才不如愚。","商者多巧智，農者爭膏腴。","儒生未遇時，衣食不自如。","久與故交別，他榮我窮居。","到門懶入門，何況千里餘。","君子有褊性，矧乃尋常徒。","行行任天地，無爲強親疎。"]', '["富貴多勝事，貪賤無良圖。","上德兼濟心，中才不如愚。","商者多巧智，農者爭膏腴。","儒生未遇时，衣食不自如。","久與故交別，他榮我窮居。","到门懶入门，何況千里餘。","君子有褊性，矧乃尋常徒。","行行任天地，無爲強親疎。"]', '诗', 'shi', '', NULL, '雜詩 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fa8b90-7f88-42a1-a20d-12dc34fba35a', '神仙', '神仙', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["神仙可學無，百歲名大約。","天地何蒼茫，人間半哀樂。","浮生亮多惑，善事翻爲惡。","爭先等馳驅，中路苦瘦弱。","長老思養壽，後生笑寂寞。","五穀非長年，四氣乃靈藥。","列子何必待，吾心滿寥廓。"]', '["神仙可学無，百歲名大約。","天地何蒼茫，人间半哀乐。","浮生亮多惑，善事翻爲惡。","爭先等驰驱，中路苦瘦弱。","长老思養壽，後生笑寂寞。","五穀非长年，四氣乃靈藥。","列子何必待，吾心满寥廓。"]', '诗', 'shi', '', NULL, '神仙 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e42b61d-d0b4-4876-bfbd-269008daa0f8', '北遊還酬孟雲卿', '北游還酬孟云卿', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["忽忽忘前事，志願能相乖。","衣馬久羸弊，誰信文與才。","善道居貧賤，潔服蒙塵埃。","行行無定心，壈坎難歸來。","慈母憂疾疹，至家念栖哀。","與君宿姻親，深見中外懷。","俟余惜時節，倀望臨高臺。"]', '["忽忽忘前事，志願能相乖。","衣马久羸弊，誰信文與才。","善道居貧賤，潔服蒙塵埃。","行行無定心，壈坎难归来。","慈母憂疾疹，至家念栖哀。","與君宿姻親，深见中外懷。","俟余惜时節，倀望臨高台。"]', '诗', 'shi', '', NULL, '北遊還酬孟雲卿 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c1b634-3358-4815-a597-27f077f8701b', '古別離', '古別離', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["別離無遠近，事歡情亦悲。","不聞車輪聲，後會將何時。","去日忘寄書，來日乖前期。","縱知明當返，一息千萬思。"]', '["別離無远近，事歡情亦悲。","不闻车輪声，後會將何时。","去日忘寄书，来日乖前期。","縱知明當返，一息千万思。"]', '诗', 'shi', '', NULL, '古別離 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d301b0-9e4a-4fce-931c-d10b86c5a0ff', '回軍跛者', '回軍跛者', '66067c05-bb2a-4ff4-9806-aa330ffa067e', '唐', '["既老又不全，始得離邊城。","一枝假枯木，步步向南行。","去時日一百，來時月一程。","常恐道路旁，掩棄狐兔塋。","所願死鄉里，到日不願生。","聞此哀怨詞，念念不忍聽。","惜無異人術，倏忽具爾形。"]', '["既老又不全，始得離邊城。","一枝假枯木，步步向南行。","去时日一百，来时月一程。","常恐道路旁，掩棄狐兔塋。","所願死乡里，到日不願生。","闻此哀怨词，念念不忍听。","惜無異人術，倏忽具爾形。"]', '诗', 'shi', '', NULL, '回軍跛者 趙徵明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9f40f86-1b30-4bbf-9a09-8402a7a296c6', '挽歌詞', '挽歌词', '66067c05-bb2a-4ff4-9806-aa330ffa067e', '唐', '["寒日蒿上明，淒淒郭東路。","素車誰家子，丹旐引將去。","原下荆棘叢，叢邊有新墓。","人間痛傷別，此是長別處。","曠野多蕭條，青松白楊樹。"]', '["寒日蒿上明，淒淒郭东路。","素车誰家子，丹旐引將去。","原下荆棘叢，叢邊有新墓。","人间痛傷別，此是长別处。","曠野多蕭條，青松白楊樹。"]', '诗', 'shi', '', NULL, '挽歌詞 趙徵明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d96f863-72d7-409e-9c94-39f2d68eb802', '思歸', '思归', '66067c05-bb2a-4ff4-9806-aa330ffa067e', '唐', '["爲別未幾日，去日如三秋。","猶疑望可見，日日上高樓。","惟見分手處，白蘋滿芳洲。","寸心寧死別，不忍生離憂。"]', '["爲別未幾日，去日如三秋。","猶疑望可见，日日上高楼。","惟见分手处，白蘋满芳洲。","寸心寧死別，不忍生離憂。"]', '诗', 'shi', '', NULL, '思歸 趙徵明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917ed94c-096c-4143-b5c3-45ca56355320', '泉上雨後作', '泉上雨後作', '2fe6735f-02c9-4ada-be0f-1c1512c225c4', '唐', '["風雨蕩繁暑，雷息佳霽初。","衆峰帶雲雨，清氣入我廬。","颯颯涼飆來，臨窺愜所圖。","綠蘿長新蔓，褭褭垂坐隅。","流水復簷下，丹砂發清渠。","養葛爲我衣，種芋爲我蔬。","誰是畹與畦，瀰漫連野蕪。"]', '["风雨蕩繁暑，雷息佳霽初。","衆峰带云雨，清氣入我廬。","颯颯涼飆来，臨窺愜所圖。","綠蘿长新蔓，褭褭垂坐隅。","流水复簷下，丹砂發清渠。","養葛爲我衣，種芋爲我蔬。","誰是畹與畦，瀰漫連野蕪。"]', '诗', 'shi', '', NULL, '泉上雨後作 元季川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('265752d4-4e7d-4bc4-b759-5b18e61f2530', '登雲中', '登云中', '2fe6735f-02c9-4ada-be0f-1c1512c225c4', '唐', '["灌田東山下，取樂在爾休。","清興相引行，日日三四周。","白鷗與我心，不厭此中遊。","窮覽頗有適，不極趣無幽。","憀然歌采薇，曲盡心悠悠。"]', '["灌田东山下，取乐在爾休。","清兴相引行，日日三四周。","白鷗與我心，不厭此中游。","窮覽頗有適，不極趣無幽。","憀然歌采薇，曲尽心悠悠。"]', '诗', 'shi', '', NULL, '登雲中 元季川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('993ee31a-499f-4ef2-be04-a78790652ee5', '山中曉興', '山中晓兴', '2fe6735f-02c9-4ada-be0f-1c1512c225c4', '唐', '["河漢降玄霜，昨來節物殊。","媿無神仙姿，豈有陰陽俱。","靈鳥望不見，慨然悲高梧。","華葉隨風揚，珍條雜榛蕪。","爲君寒谷吟，歎息知何如。"]', '["河漢降玄霜，昨来節物殊。","媿無神仙姿，豈有陰陽俱。","靈鸟望不见，慨然悲高梧。","华葉隨风揚，珍條杂榛蕪。","爲君寒谷吟，歎息知何如。"]', '诗', 'shi', '', NULL, '山中曉興 元季川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e37219-3f22-4219-af25-ae4e543e6c01', '古遠行', '古远行', '2fe6735f-02c9-4ada-be0f-1c1512c225c4', '唐', '["悠悠遠行者，羈獨當時思。","道與日月長，人無茅舍期。","出門萬里心，誰不傷別離。","縱遠當白髮，歲月悲今時。","何況異形容，安須與爾悲。"]', '["悠悠远行者，羈独當时思。","道與日月长，人無茅舍期。","出门万里心，誰不傷別離。","縱远當白髮，歲月悲今时。","何況異形容，安須與爾悲。"]', '诗', 'shi', '', NULL, '古遠行 元季川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba64715-231e-46b2-9208-b835894c19c1', '晚秋拾遺朱放訪山居', '晚秋拾遺朱放訪山居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["不逐時人後，終年獨閉關。","家中貧自樂，石上臥常閑。","墜栗添新味，寒花帶老顏。","侍臣當獻納，那得到空山。"]', '["不逐时人後，終年独閉关。","家中貧自乐，石上臥常闲。","墜栗添新味，寒花带老顏。","侍臣當獻納，那得到空山。"]', '诗', 'shi', '', NULL, '晚秋拾遺朱放訪山居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95611e85-f502-401b-8e88-d32127303464', '題女道士居', '題女道士居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["不餌住雲溪，休丹罷藥畦。","杏花虛結子，石髓任成泥。","掃地青牛臥，栽松白鶴棲。","共知仙女麗，莫是阮郎妻。"]', '["不餌住云溪，休丹罷藥畦。","杏花虛結子，石髓任成泥。","掃地青牛臥，栽松白鹤棲。","共知仙女丽，莫是阮郎妻。"]', '诗', 'shi', '', NULL, '題女道士居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62170895-9024-4f30-b962-d1bd01eb00aa', '山中枉張宙員外書期訪衡門', '山中枉張宙員外书期訪衡门', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["常恨相知晚，朝來枉數行。","臥雲驚聖代，拂石候仙郎。","時果連枝熟，春醪滿甕香。","貧家仍有趣，山色滿湖光。"]', '["常恨相知晚，朝来枉數行。","臥云驚聖代，拂石候仙郎。","时果連枝熟，春醪满甕香。","貧家仍有趣，山色满湖光。"]', '诗', 'shi', '', NULL, '山中枉張宙員外書期訪衡門 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a26e3fb-8954-4a1a-a5f6-53e920d22c26', '山中贈張正則評事', '山中贈張正則評事', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["終年常避喧，師事五千言。","流水閑過院，春風與閉門。","山茶邀上客，桂實落前軒。","莫強敎余起，微官不足論。"]', '["終年常避喧，師事五千言。","流水闲過院，春风與閉门。","山茶邀上客，桂實落前軒。","莫強敎余起，微官不足論。"]', '诗', 'shi', '', NULL, '山中贈張正則評事 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb27dc15-8614-429a-8a34-eac8d5e1541b', '題鏡湖野老所居', '題镜湖野老所居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["湖裏尋君去，樵風往返吹。","樹喧巢鳥出，路細葑田移。","漚苧成魚網，枯根是酒巵。","老年唯自適，生事任羣兒。"]', '["湖裏尋君去，樵风往返吹。","樹喧巢鸟出，路細葑田移。","漚苧成鱼網，枯根是酒巵。","老年唯自適，生事任羣兒。"]', '诗', 'shi', '', NULL, '題鏡湖野老所居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e975792f-061f-4132-9523-f87eb07ea3e8', '早秋宿崔業居處', '早秋宿崔業居处', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["從來席不暖，爲爾便淹流。","雞黍今相會，雲山昔共遊。","上簾宜晚景，臥簟覺新秋。","身事何須問，余心正四愁。"]', '["從来席不暖，爲爾便淹流。","雞黍今相會，云山昔共游。","上簾宜晚景，臥簟覺新秋。","身事何須问，余心正四愁。"]', '诗', 'shi', '', NULL, '早秋宿崔業居處 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea158529-b9fd-4a7f-bc24-669b1cecee33', '贈烏程楊苹明府', '贈烏程楊苹明府', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["策杖政成時，清溪弄釣絲。","當年潘子貌，避病沈侯詩。","漉酒迎賓急，看花署字遲。","楊梅今熟未，與我兩三枝。"]', '["策杖政成时，清溪弄釣絲。","當年潘子貌，避病沈侯诗。","漉酒迎賓急，看花署字遲。","楊梅今熟未，與我兩三枝。"]', '诗', 'shi', '', NULL, '贈烏程楊苹明府 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84b9b4c-b32a-41a9-b21c-4875eb6672e5', '徐侍郎素未相識時攜酒命饌兼命諸詩客同訪會稽山居', '徐侍郎素未相識时携酒命饌兼命諸诗客同訪會稽山居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["忽道仙翁至，幽人學拜迎。","華簪窺甕牖，珍味代藜羹。","洗硯魚仍戲，移樽鳥不驚。","蘭亭攀敘却，會此越中營。"]', '["忽道仙翁至，幽人学拜迎。","华簪窺甕牖，珍味代藜羹。","洗硯鱼仍戲，移樽鸟不驚。","蘭亭攀敘却，會此越中營。"]', '诗', 'shi', '', NULL, '徐侍郎素未相識時攜酒命饌兼命諸詩客同訪會稽山居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b28dca6-a10e-4666-9bdc-6f938af982ae', '春日閑居三首 一', '春日闲居三首 一', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["一似桃源隱，將令過客迷。","礙冠門柳長，驚夢院鶯啼。","澆藥泉流細，圍碁日影低。","舉家無外事，共愛草萋萋。"]', '["一似桃源隐，將令過客迷。","礙冠门柳长，驚梦院鶯啼。","澆藥泉流細，圍碁日影低。","舉家無外事，共愛草萋萋。"]', '诗', 'shi', '', NULL, '春日閑居三首 一 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a723b6-b697-4787-bc6f-8b87492fcecb', '春日閑居三首 二', '春日闲居三首 二', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["長謠朝復暝，幽獨幾人知。","老鶴兼雛弄，叢篁帶笋移。","白雲將袖拂，青鏡出簷窺。","邀取漁家叟，花間把酒巵。"]', '["长謠朝复暝，幽独幾人知。","老鹤兼雛弄，叢篁带笋移。","白云將袖拂，青镜出簷窺。","邀取漁家叟，花间把酒巵。"]', '诗', 'shi', '', NULL, '春日閑居三首 二 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8bbbce-2906-43d8-b1f8-072fa6a3feed', '春日閑居三首 三', '春日闲居三首 三', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["寂寂池亭裏，軒窗間綠苔。","游魚牽荇沒，戲鳥踏花摧。","小徑僧尋去，高峯鹿下來。","中年曾屢辟，多病復遲迴。"]', '["寂寂池亭裏，軒窗间綠苔。","游鱼牽荇沒，戲鸟踏花摧。","小徑僧尋去，高峯鹿下来。","中年曾屢辟，多病复遲迴。"]', '诗', 'shi', '', NULL, '春日閑居三首 三 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fa1a26-801e-4852-822a-668dffde2523', '題石室山王宁所居', '題石室山王宁所居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["白雲知所好，柏葉幸加餐。","石鏡妻將照，仙書我借看。","鳥來翻藥椀，猿飲怕魚竿。","借問簷前樹，何枝曾挂冠。"]', '["白云知所好，柏葉幸加餐。","石镜妻將照，仙书我借看。","鸟来翻藥椀，猿饮怕鱼竿。","借问簷前樹，何枝曾挂冠。"]', '诗', 'shi', '', NULL, '題石室山王宁所居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87065899-8186-4213-bacc-ea979b255ce2', '送王道士', '送王道士', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["真人俄整舃，雙鶴屢飛翔。","恐入壺中住，須傳肘後方。","霓裳雲氣潤，石徑朮苗香。","一去何時見，仙家日月長。"]', '["真人俄整舃，雙鹤屢飞翔。","恐入壺中住，須傳肘後方。","霓裳云氣潤，石徑朮苗香。","一去何时见，仙家日月长。"]', '诗', 'shi', '', NULL, '送王道士 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967b7b73-9ea6-4478-96e1-75e024831ca4', '將移耶溪舊居留贈嚴維秘書', '將移耶溪旧居留贈嚴維秘书', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["雞犬漁舟裏，長謠任興行。","那邀落日醉，已被遠山迎。","書篋將非重，荷衣著甚輕。","謝安無箇事，忽起爲蒼生。"]', '["雞犬漁舟裏，长謠任兴行。","那邀落日醉，已被远山迎。","书篋將非重，荷衣著甚轻。","謝安無箇事，忽起爲蒼生。"]', '诗', 'shi', '', NULL, '將移耶溪舊居留贈嚴維秘書 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee5ea8e7-5117-4311-a315-e99cb54af115', '秋日過僧惟則故院', '秋日過僧惟則故院', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["衰草經行處，微燈舊道場。","門人失譚柄，野鳥上禪牀。","科斗書空古，栴檀缽自香。","今朝數行淚，却灑約公房。"]', '["衰草經行处，微灯旧道場。","门人失譚柄，野鸟上禪牀。","科斗书空古，栴檀缽自香。","今朝數行泪，却灑約公房。"]', '诗', 'shi', '', NULL, '秋日過僧惟則故院 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144012f1-7a20-4c32-8f61-b4726c8aa2e7', '山中奉寄錢起員外兼簡苗發員外', '山中奉寄錢起員外兼簡苗發員外', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["空山歲計是胡麻，窮海無梁泛一槎。","稚子唯能覓梨栗，逸妻相共老烟霞。","高吟麗句驚巢鶴，閑閉春風看落花。","借問省中何水部，今人幾箇屬詩家。"]', '["空山歲計是胡麻，窮海無梁泛一槎。","稚子唯能覓梨栗，逸妻相共老烟霞。","高吟丽句驚巢鹤，闲閉春风看落花。","借问省中何水部，今人幾箇屬诗家。"]', '诗', 'shi', '', NULL, '山中奉寄錢起員外兼簡苗發員外 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a13a6a-2e20-4db8-96a7-fb26093689d0', '獻薛僕射', '獻薛僕射', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["由來那敢議輕肥，散髮行歌自採薇。","逋客未能忘野興，辟書翻遣脫荷衣。","家中匹婦空相笑，池上羣鷗盡欲飛。","更乞大賢容小隱，益看愚谷有光輝。"]', '["由来那敢議轻肥，散髮行歌自採薇。","逋客未能忘野兴，辟书翻遣脫荷衣。","家中匹婦空相笑，池上羣鷗尽欲飞。","更乞大賢容小隐，益看愚谷有光輝。"]', '诗', 'shi', '', NULL, '獻薛僕射 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64896cb9-3383-45d7-b031-489bcd1ae6a2', '鮑防員外見尋因書情呈贈', '鲍防員外见尋因书情呈贈', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["少小爲儒不自強，如今嬾復見侯王。","覽鏡已知身漸老，買山將作計偏長。","荒涼鳥獸同三逕，撩亂琴書共一牀。","猶有郎官來問疾，時人莫道我佯狂。"]', '["少小爲儒不自強，如今嬾复见侯王。","覽镜已知身漸老，買山將作計偏长。","荒涼鸟獸同三逕，撩亂琴书共一牀。","猶有郎官来问疾，时人莫道我佯狂。"]', '诗', 'shi', '', NULL, '鮑防員外見尋因書情呈贈 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c538370-b0e4-4898-99a4-a4bad2df42d1', '寄浙東皇甫中丞', '寄浙东皇甫中丞', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["閑閑麋鹿或相隨，一兩年來鬢欲衰。","琴硯共依春酒甕，雲霞覆著破柴籬。","注書不向時流說，種藥空令道者知。","久帶紗巾仍藉草，山中那得見朝儀。"]', '["闲闲麋鹿或相隨，一兩年来鬢欲衰。","琴硯共依春酒甕，云霞覆著破柴籬。","注书不向时流说，種藥空令道者知。","久带紗巾仍藉草，山中那得见朝儀。"]', '诗', 'shi', '', NULL, '寄浙東皇甫中丞 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('439515ac-9aad-456b-986c-e63161f13a9d', '題章野人山居', '題章野人山居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["帶郭茅亭詩興饒，回看一曲倚危橋。","門前山色能深淺，壁上湖光自動搖。","閑花散落填書帙，戲鳥低飛礙柳條。","向此隱來經幾載，如今已是漢家朝。"]', '["带郭茅亭诗兴饒，回看一曲倚危橋。","门前山色能深淺，壁上湖光自动搖。","闲花散落填书帙，戲鸟低飞礙柳條。","向此隐来經幾載，如今已是漢家朝。"]', '诗', 'shi', '', NULL, '題章野人山居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce932726-f3d6-4aec-8642-76290d52ad85', '山中枉皇甫溫大夫見招書', '山中枉皇甫溫大夫见招书', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["十年木屐步苔痕，石上松間水自喧。","三辟草堂仍被褐，數行書札忽臨門。","臥多共息嵇康病，才劣虛同郭隗尊。","亞相已能憐潦倒，山花笑處莫啼猿。"]', '["十年木屐步苔痕，石上松间水自喧。","三辟草堂仍被褐，數行书札忽臨门。","臥多共息嵇康病，才劣虛同郭隗尊。","亞相已能怜潦倒，山花笑处莫啼猿。"]', '诗', 'shi', '', NULL, '山中枉皇甫溫大夫見招書 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41eb942c-0f5d-4834-a8e9-dd270e1ea195', '題茅山李尊師山居', '題茅山李尊師山居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["天師百歲少如童，不到山中竟不逢。","洗藥每臨新瀑水，步虛時上最高峰。","籬間五月留殘雪，座右千年廕老松。","此去人寰今遠近，回看雲壑一重重。"]', '["天師百歲少如童，不到山中竟不逢。","洗藥每臨新瀑水，步虛时上最高峰。","籬间五月留殘雪，座右千年廕老松。","此去人寰今远近，回看云壑一重重。"]', '诗', 'shi', '', NULL, '題茅山李尊師山居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a50f8db-5778-4953-b345-c433613544fa', '耶溪書懷寄劉長卿員外', '耶溪书懷寄劉长卿員外', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["時人多笑樂幽棲，晚起閑行獨杖藜。","雲色卷舒前後嶺，藥苗新舊兩三畦。","偶逢野果將呼子，屢折荆釵亦爲妻。","擬共釣竿長往復，巖陵灘上勝耶溪。"]', '["时人多笑乐幽棲，晚起闲行独杖藜。","云色卷舒前後嶺，藥苗新旧兩三畦。","偶逢野果將呼子，屢折荆釵亦爲妻。","擬共釣竿长往复，巖陵灘上勝耶溪。"]', '诗', 'shi', '', NULL, '耶溪書懷寄劉長卿員外 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3bf54b-d657-43d8-8999-dca60322355d', '山中崔大夫有書相問', '山中崔大夫有书相问', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["客在煙霞裏，閑閑逐狎鷗。","終年常裸足，連日半蓬頭。","帶月乘漁艇，迎寒綻鹿裘。","已于人事少，多被挂冠留。","素業堆千卷，清風至一丘。","蒼黃倒藜杖，傴僂覩銀鉤。","跡愧巢由隱，才非管樂儔。","從來自多病，不是傲王侯。"]', '["客在煙霞裏，闲闲逐狎鷗。","終年常裸足，連日半蓬头。","带月乘漁艇，迎寒綻鹿裘。","已于人事少，多被挂冠留。","素業堆千卷，清风至一丘。","蒼黄倒藜杖，傴僂覩銀鉤。","跡愧巢由隐，才非管乐儔。","從来自多病，不是傲王侯。"]', '诗', 'shi', '', NULL, '山中崔大夫有書相問 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8edd120-3495-418e-8df9-3b36d4bcd328', '張建封大夫奏系爲校書郎因寄此作', '張建封大夫奏系爲校书郎因寄此作', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["久是煙霞客，潭深釣得魚。","不知芸閣上，遺校幾多書。"]', '["久是煙霞客，潭深釣得鱼。","不知芸閣上，遺校幾多书。"]', '诗', 'shi', '', NULL, '張建封大夫奏系爲校書郎因寄此作 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8804255a-ff41-4156-8da9-4a77a0a01c0e', '會稽山居寄薛播侍郎袁高給事高參舍人', '會稽山居寄薛播侍郎袁高給事高參舍人', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["稷卨今爲相，明君復是堯。","寧知買臣困，猶負會稽樵。"]', '["稷卨今爲相，明君复是堯。","寧知買臣困，猶負會稽樵。"]', '诗', 'shi', '', NULL, '會稽山居寄薛播侍郎袁高給事高參舍人 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9a2f77-7edd-40c8-a227-1c5d6dac6804', '閑居覽史', '闲居覽史', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["長策胸中不復論，荷衣藍縷閉柴門。","當時漢祖無三傑，爭得咸陽與子孫。"]', '["长策胸中不复論，荷衣藍縷閉柴门。","當时漢祖無三傑，爭得咸陽與子孫。"]', '诗', 'shi', '', NULL, '閑居覽史 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7980a789-53da-4d4c-afab-0bbe97dd46bd', '山中贈耿拾遺湋兼兩省故人', '山中贈耿拾遺湋兼兩省故人', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["數片荷衣不蔽身，青山白鳥豈知貧。","如今非是秦時世，更隱桃花亦笑人。"]', '["數片荷衣不蔽身，青山白鸟豈知貧。","如今非是秦时世，更隐桃花亦笑人。"]', '诗', 'shi', '', NULL, '山中贈耿拾遺湋兼兩省故人 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4227169-1e61-4208-aaeb-ebea6439eec0', '秋日送僧志幽歸山寺', '秋日送僧志幽归山寺', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["禪室繩牀在翠微，松間荷笠一僧歸。","磬聲寂歷宜秋夜，手冷燈前自衲衣。"]', '["禪室繩牀在翠微，松间荷笠一僧归。","磬声寂歷宜秋夜，手冷灯前自衲衣。"]', '诗', 'shi', '', NULL, '秋日送僧志幽歸山寺 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4679fdef-381f-44be-9291-8f0181c8c856', '題僧明惠房', '題僧明惠房', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["簷前朝暮雨添花，八十真僧飯一麻。","入定幾時將出定，不知巢燕污袈裟。"]', '["簷前朝暮雨添花，八十真僧飯一麻。","入定幾时將出定，不知巢燕污袈裟。"]', '诗', 'shi', '', NULL, '題僧明惠房 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0179a6b0-a00c-495e-91ec-e0a4f0bfdf69', '答泉州薛播使君重陽日贈酒', '答泉州薛播使君重陽日贈酒', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["欲強登高無力也，籬邊黃菊爲誰開。","共知不是潯陽郡，那得王弘送酒來。"]', '["欲強登高無力也，籬邊黄菊爲誰开。","共知不是潯陽郡，那得王弘送酒来。"]', '诗', 'shi', '', NULL, '答泉州薛播使君重陽日贈酒 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ceb4f66-5d2e-4b52-b611-dc308516edea', '題洪道士山院', '題洪道士山院', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["霞外主人門不扃，數株桃樹藥囊青。","閑行池畔隨孤鶴，若問多應道姓丁。"]', '["霞外主人门不扃，數株桃樹藥囊青。","闲行池畔隨孤鹤，若问多應道姓丁。"]', '诗', 'shi', '', NULL, '題洪道士山院 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ced665f5-91f8-4f91-bef6-73ba963cafd2', '期王鍊師不至', '期王鍊師不至', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["黃精蒸罷洗瓊杯，林下從留石上苔。","昨日圍棋未終局，多乘白鶴下山來。"]', '["黄精蒸罷洗瓊杯，林下從留石上苔。","昨日圍棋未終局，多乘白鹤下山来。"]', '诗', 'shi', '', NULL, '期王鍊師不至 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5032b6-cd8e-4c5e-bbf7-e0f95a18e6a1', '題贈張道士山居', '題贈張道士山居', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["盤石垂蘿即是家，回頭猶看五枝花。","松間寂寂無煙火，應服朝來一片霞。"]', '["盤石垂蘿即是家，回头猶看五枝花。","松间寂寂無煙火，應服朝来一片霞。"]', '诗', 'shi', '', NULL, '題贈張道士山居 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de25a81-af75-465c-9354-ca3a2d23c13b', '山中書懷寄張建封大夫', '山中书懷寄張建封大夫', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["昨日年催白髮新，身如麋鹿不知貧。","時時亦被羣兒笑，賴有南山四老人。"]', '["昨日年催白髮新，身如麋鹿不知貧。","时时亦被羣兒笑，賴有南山四老人。"]', '诗', 'shi', '', NULL, '山中書懷寄張建封大夫 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a896fb-d8d1-4d99-98d1-eec0e08dba3e', '山中贈諸暨丹丘明府', '山中贈諸暨丹丘明府', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["荷衣半破帶莓苔，笑向陶潛酒甕開。","縱醉遠須上山去，白雲那肯下山來。"]', '["荷衣半破带莓苔，笑向陶潛酒甕开。","縱醉远須上山去，白云那肯下山来。"]', '诗', 'shi', '', NULL, '山中贈諸暨丹丘明府 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ada1e5-a398-4e50-883c-e50e7bafa9ce', '奉寄晝公', '奉寄晝公', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["蓑笠雙童傍酒船，湖山相引到房前。","團蕉何事敎人見，暫借空牀守坐禪。"]', '["蓑笠雙童傍酒船，湖山相引到房前。","團蕉何事敎人见，暫借空牀守坐禪。"]', '诗', 'shi', '', NULL, '奉寄晝公 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8bcabd-0823-4dea-bf90-a3a59aec3f22', '宿雲門上方', '宿云门上方', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["禪室遙看峰頂頭，白雲東去水長流。","松間儻許幽人住，不更將錢買沃州。"]', '["禪室遙看峰頂头，白云东去水长流。","松间儻許幽人住，不更將錢買沃州。"]', '诗', 'shi', '', NULL, '宿雲門上方 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2938d405-ac85-4e4a-9261-d4b983e0f068', '即事奉呈郎中韋使君', '即事奉呈郎中韋使君', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["久臥雲間已息機，青袍忽著狎鷗飛。","詩興到來無一事，郡中今有謝玄暉。"]', '["久臥云间已息機，青袍忽著狎鷗飞。","诗兴到来無一事，郡中今有謝玄暉。"]', '诗', 'shi', '', NULL, '即事奉呈郎中韋使君 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89090db5-934b-4d15-9808-18ceb9d735e9', '曉雞', '晓雞', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["黯黯嚴城罷鼓鼙，數聲相續出寒棲。","不嫌驚破紗窗夢，却恐爲妖半夜啼。"]', '["黯黯嚴城罷鼓鼙，數声相續出寒棲。","不嫌驚破紗窗梦，却恐爲妖半夜啼。"]', '诗', 'shi', '', NULL, '曉雞 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c012d2aa-e678-491c-aa1d-d201ed7d6e2a', '寄李白', '寄李白', '2618e872-5fe6-41c9-9a77-82bfee7d3297', '唐', '["古來文章有能奔逸氣，聳高格。","清人心神，驚人魂魄。","我聞當今有李白，大獵賦，鴻猷文，嗤長卿，笑子雲。","班張所作瑣細不入耳，未知卿雲得在嗤笑限。","登廬山，觀瀑布，海風吹不斷，江月照還空。","余愛此兩句：登天台，望渤海雲垂大鵬飛，山壓巨鰲背，斯言亦好在。","至於他作多不拘常律，振擺超騰，既俊且逸。","或醉中操紙，或興來走筆。","手下忽然片雲飛，眼前劃見孤峰出。","而我有時白日忽欲睡，睡覺歘然起攘臂。","任生知有君，君也知有任生未。","中間聞道在長安，及余戾止。","君已江東訪元丹，邂逅不得見君面。","每常把酒，向東望良久。","見說往年在翰林，胸中矛戟何森森。","新詩傳在宮人口，佳句不離明主心。","身騎天馬多意氣，目送飛鴻對豪貴。","承恩召入凡幾迴，待詔歸來仍半醉。","權臣妬盛名，羣犬多吠聲。","有勅放君却歸隱淪處，高歌大笑出關去。","且向東山爲外臣，諸侯交迓馳朱輪。","白璧一雙買交者，黃金百鎰相知人。","平生傲岸其志不可測，數十年爲客，未嘗一日低顏色。","八詠樓中坦腹眠，五侯門下無心憶。","繁花越臺上，細柳吳宮側。","綠水青山知有君，白雲明月偏相識。","養高兼養閑，可望不可攀。","莊周萬物外，范蠡五湖間。","人傳訪道滄海上，丁令王喬每往還。","蓬萊徑是曾到來，方丈豈唯方一丈。","伊余每欲乘興往相尋，江湖擁隔勞寸心。","今朝忽遇東飛翼，寄此一章表胸臆。","儻能報我一片言，但訪任華有人識。"]', '["古来文章有能奔逸氣，聳高格。","清人心神，驚人魂魄。","我闻當今有李白，大獵賦，鴻猷文，嗤长卿，笑子云。","班張所作瑣細不入耳，未知卿云得在嗤笑限。","登廬山，观瀑布，海风吹不斷，江月照還空。","余愛此兩句：登天台，望渤海云垂大鵬飞，山壓巨鰲背，斯言亦好在。","至於他作多不拘常律，振擺超腾，既俊且逸。","或醉中操紙，或兴来走笔。","手下忽然片云飞，眼前劃见孤峰出。","而我有时白日忽欲睡，睡覺歘然起攘臂。","任生知有君，君也知有任生未。","中间闻道在长安，及余戾止。","君已江东訪元丹，邂逅不得见君面。","每常把酒，向东望良久。","见说往年在翰林，胸中矛戟何森森。","新诗傳在宮人口，佳句不離明主心。","身騎天马多意氣，目送飞鴻对豪貴。","承恩召入凡幾迴，待詔归来仍半醉。","權臣妬盛名，羣犬多吠声。","有勅放君却归隐淪处，高歌大笑出关去。","且向东山爲外臣，諸侯交迓驰朱輪。","白璧一雙買交者，黄金百鎰相知人。","平生傲岸其志不可測，數十年爲客，未嘗一日低顏色。","八詠楼中坦腹眠，五侯门下無心憶。","繁花越台上，細柳吳宮側。","綠水青山知有君，白云明月偏相識。","養高兼養闲，可望不可攀。","莊周万物外，范蠡五湖间。","人傳訪道滄海上，丁令王喬每往還。","蓬萊徑是曾到来，方丈豈唯方一丈。","伊余每欲乘兴往相尋，江湖擁隔勞寸心。","今朝忽遇东飞翼，寄此一章表胸臆。","儻能報我一片言，但訪任华有人識。"]', '诗', 'shi', '', NULL, '寄李白 任華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24f9678-6279-4a85-be09-d3ebfe919190', '寄杜拾遺', '寄杜拾遺', '2618e872-5fe6-41c9-9a77-82bfee7d3297', '唐', '["杜拾遺，名甫第二才甚奇。","任生與君別，別來已多時，何嘗一日不相思。","杜拾遺，知不知，昨日有人誦得數篇黃絹詞。","吾怪異奇特借問，果然稱是杜二之所爲。","勢攫虎豹，氣騰蛟螭。","滄海無風似鼓蕩，華嶽平地欲奔馳。","曹劉俯仰慚大敵，沈謝逡巡稱小兒。","昔在帝城中，盛名君一個。","諸人見所作，無不心膽破。","郎官叢裏作狂歌，丞相閣中常醉臥。","前年皇帝歸長安，承恩闊步青雲端。","積翠扈游花匼匝，披香寓直月團欒。","英才特達承天睠，公卿無不相欽慕。","只緣汲黯好直言，遂使安仁却爲掾。","如今避地錦城隅，幕下英僚每日相隨提玉壺。","半醉起舞捋髭鬚，乍低乍昂傍若無。","古人制禮但爲防俗士，豈得爲君設之乎。","而我不飛不鳴亦可以，只待朝廷有知己。","已曾讀却無限書，拙詩一句兩句在人耳。","如今看之總無益，又不能崎嶇傍朝市。","且當事耕稼，豈得便徒爾。","南陽葛亮爲友朋，東山謝安作鄰里。","閑常把琴弄，悶即攜樽起。","鶯啼二月三月時，花發千山萬山裏。","此時幽曠無人知，火急將書憑驛使，爲報杜拾遺。"]', '["杜拾遺，名甫第二才甚奇。","任生與君別，別来已多时，何嘗一日不相思。","杜拾遺，知不知，昨日有人誦得數篇黄絹词。","吾怪異奇特借问，果然稱是杜二之所爲。","勢攫虎豹，氣腾蛟螭。","滄海無风似鼓蕩，华嶽平地欲奔驰。","曹劉俯仰慚大敵，沈謝逡巡稱小兒。","昔在帝城中，盛名君一個。","諸人见所作，無不心膽破。","郎官叢裏作狂歌，丞相閣中常醉臥。","前年皇帝归长安，承恩闊步青云端。","積翠扈游花匼匝，披香寓直月團欒。","英才特達承天睠，公卿無不相欽慕。","只緣汲黯好直言，遂使安仁却爲掾。","如今避地錦城隅，幕下英僚每日相隨提玉壺。","半醉起舞捋髭鬚，乍低乍昂傍若無。","古人制禮但爲防俗士，豈得爲君設之乎。","而我不飞不鳴亦可以，只待朝廷有知己。","已曾读却無限书，拙诗一句兩句在人耳。","如今看之總無益，又不能崎嶇傍朝市。","且當事耕稼，豈得便徒爾。","南陽葛亮爲友朋，东山謝安作鄰里。","闲常把琴弄，悶即携樽起。","鶯啼二月三月时，花發千山万山裏。","此时幽曠無人知，火急將书憑驛使，爲報杜拾遺。"]', '诗', 'shi', '', NULL, '寄杜拾遺 任華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a29f32-5c21-41d8-8119-b87073f59218', '懷素上人草書歌', '懷素上人草书歌', '2618e872-5fe6-41c9-9a77-82bfee7d3297', '唐', '["吾嘗好奇，古來草聖無不知，豈不知右軍與獻之。","雖有壯麗之骨，恨無狂逸之姿。","中間張長史，獨放蕩而不羈，以顛爲名傾蕩於當時。","張老顛，殊不顛於懷素。","懷素顛，乃是顛。","人謂爾從江南來，我謂爾從天上來。","負顛狂之墨妙，有墨狂之逸才。","狂僧前日動京華，朝騎王公大人馬，暮宿王公大人家。","誰不造素屏，誰不塗粉壁。","粉壁搖晴光，素屏凝曉霜，待君揮灑兮不可彌忘。","駿馬迎來坐堂中，金盆盛酒竹葉香。","十桮五桮不解意，百桮已後始顛狂。","一顛一狂多意氣，大呌一聲起攘臂。","揮毫倏忽千萬字，有時一字兩字長丈二。","翕若長鯨潑剌動海島，歘若長蛇戌律透深草。","回環繚繞相拘連，千變萬化在眼前。","飄風驟雨相擊射，速祿颯拉動簷隙。","擲華山巨石以爲點，掣衡山陣雲以爲畫。","興不盡，勢轉雄。","恐天低而地窄，更有何處最可憐，褭褭枯藤萬丈懸。","萬丈懸，拂秋水，映秋天。","或如絲，或如髮，風吹欲絕又不絕，鋒芒利如歐冶劒。","勁直渾是幷州鐵，時復枯燥何䙰褷。","忽覺陰山突兀橫翠微，中有枯松錯落一萬丈。","倒挂絕壁蹙枯枝，千魑魅兮萬魍魎，欲出不可何閃屍。","又如翰海日暮愁陰濃，忽然躍出千黑龍。","夭矯偃蹇，入乎蒼穹。","飛沙走石滿窮塞，萬里颼颼西北風。","狂僧有絕藝，非數仞高牆不足以逞其筆勢。","或逢花箋與絹素，凝神執筆守恆度。","別來筋骨多情趣，霏霏微微點長露。","三秋月照丹鳳樓，二月花開上林樹。","終恐絆騏驥之足，不得展千里之步。","狂僧狂僧，爾雖有絕藝。","猶當假良媒，不因禮部張公將爾來，如何得聲名一旦諠九垓。"]', '["吾嘗好奇，古来草聖無不知，豈不知右軍與獻之。","雖有壯丽之骨，恨無狂逸之姿。","中间張长史，独放蕩而不羈，以顛爲名傾蕩於當时。","張老顛，殊不顛於懷素。","懷素顛，乃是顛。","人謂爾從江南来，我謂爾從天上来。","負顛狂之墨妙，有墨狂之逸才。","狂僧前日动京华，朝騎王公大人马，暮宿王公大人家。","誰不造素屏，誰不塗粉壁。","粉壁搖晴光，素屏凝晓霜，待君揮灑兮不可彌忘。","駿马迎来坐堂中，金盆盛酒竹葉香。","十桮五桮不解意，百桮已後始顛狂。","一顛一狂多意氣，大呌一声起攘臂。","揮毫倏忽千万字，有时一字兩字长丈二。","翕若长鯨潑剌动海島，歘若长蛇戌律透深草。","回环繚繞相拘連，千变万化在眼前。","飄风驟雨相擊射，速祿颯拉动簷隙。","擲华山巨石以爲点，掣衡山陣云以爲畫。","兴不尽，勢轉雄。","恐天低而地窄，更有何处最可怜，褭褭枯藤万丈懸。","万丈懸，拂秋水，映秋天。","或如絲，或如髮，风吹欲絕又不絕，鋒芒利如歐冶劒。","勁直渾是幷州鐵，时复枯燥何䙰褷。","忽覺陰山突兀橫翠微，中有枯松錯落一万丈。","倒挂絕壁蹙枯枝，千魑魅兮万魍魎，欲出不可何閃屍。","又如翰海日暮愁陰濃，忽然躍出千黑龙。","夭矯偃蹇，入乎蒼穹。","飞沙走石满窮塞，万里颼颼西北风。","狂僧有絕藝，非數仞高牆不足以逞其笔勢。","或逢花箋與絹素，凝神執笔守恆度。","別来筋骨多情趣，霏霏微微点长露。","三秋月照丹鳳楼，二月花开上林樹。","終恐絆騏驥之足，不得展千里之步。","狂僧狂僧，爾雖有絕藝。","猶當假良媒，不因禮部張公將爾来，如何得声名一旦諠九垓。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 任華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958d2363-c071-403a-bc1e-b1883381977d', '金陵酧李翰林謫仙子', '金陵酧李翰林謫仙子', 'fd4c1894-07fe-47db-a45a-242ba6bcd14c', '唐', '["君抱碧海珠，我懷藍田玉。","各稱希代寶，萬里遙相燭。","長卿慕藺久，子猷意已深。","平生風雲人，暗合江海心。","去秋忽乘興，命駕來東土。","謫仙遊梁園，愛子在鄒魯。","二處一不見，拂衣向江東。","五兩挂海月，扁舟隨長風。","南遊吳越徧，高揖二千石。","雪上天台山，春逢翰林伯。","宣父敬項橐，林宗重黃生。","一長復一少，相看如弟兄。","惕然意不盡，更逐西南去。","同舟入秦淮，建業龍盤處。","楚歌對吳酒，借問承恩初。","宮買長門賦，天迎駟馬車。","才高世難容，道廢可推命。","安石重攜妓，子房空謝病。","金陵百萬戶，六代帝王都。","虎石據西江，鍾山臨北湖。","二山信爲美，王屋人相待。","應爲岐路多，不知歲寒在。","君游早晚還，勿久風塵間。","此別未遠別，秋期到仙山。"]', '["君抱碧海珠，我懷藍田玉。","各稱希代寶，万里遙相燭。","长卿慕藺久，子猷意已深。","平生风云人，暗合江海心。","去秋忽乘兴，命駕来东土。","謫仙游梁园，愛子在鄒魯。","二处一不见，拂衣向江东。","五兩挂海月，扁舟隨长风。","南游吳越徧，高揖二千石。","雪上天台山，春逢翰林伯。","宣父敬項橐，林宗重黄生。","一长复一少，相看如弟兄。","惕然意不尽，更逐西南去。","同舟入秦淮，建業龙盤处。","楚歌对吳酒，借问承恩初。","宮買长门賦，天迎駟马车。","才高世难容，道廢可推命。","安石重携妓，子房空謝病。","金陵百万戶，六代帝王都。","虎石據西江，鍾山臨北湖。","二山信爲美，王屋人相待。","應爲岐路多，不知歲寒在。","君游早晚還，勿久风塵间。","此別未远別，秋期到仙山。"]', '诗', 'shi', '', NULL, '金陵酧李翰林謫仙子 魏萬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6d0130-6df9-45d7-882e-3398fdd4897a', '贈李十二白', '贈李十二白', 'caaa3add-7ac7-4603-83cc-4cfb1b35e044', '唐', '["涼風八九月，白露滿空庭。","耿耿意不暢，捎捎風葉聲。","思見雄俊士，共話今古情。","李侯忽來儀，把袂苦不早。","清論既抵掌，玄談又絕倒。","分明楚漢事，歷歷王霸道。","擔囊無俗物，訪古千里餘。","袖有匕首劒，懷中茂陵書。","雙眸光照人，詞賦凌子虛。","酌酒弦素秦，霜氣正凝潔。","平生心中事，今日爲君說。","我家有別業，寄在嵩之陽。","明月出高岑，清谿澄素光。","雲散窗戶靜，風吹松桂香。","子若同斯遊千載不相忘。"]', '["涼风八九月，白露满空庭。","耿耿意不暢，捎捎风葉声。","思见雄俊士，共話今古情。","李侯忽来儀，把袂苦不早。","清論既抵掌，玄談又絕倒。","分明楚漢事，歷歷王霸道。","擔囊無俗物，訪古千里餘。","袖有匕首劒，懷中茂陵书。","雙眸光照人，词賦凌子虛。","酌酒弦素秦，霜氣正凝潔。","平生心中事，今日爲君说。","我家有別業，寄在嵩之陽。","明月出高岑，清谿澄素光。","云散窗戶静，风吹松桂香。","子若同斯游千載不相忘。"]', '诗', 'shi', '', NULL, '贈李十二白 崔宗之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed73061-c161-4c93-bf32-d8c409e5ac06', '贈李十二白', '贈李十二白', '842d77a3-a582-4236-9e32-a7fbd627629f', '唐', '["我是瀟湘放逐臣，君辭明主漢江濱。","天外常求太白老，金陵捉得酒仙人。"]', '["我是瀟湘放逐臣，君辞明主漢江濱。","天外常求太白老，金陵捉得酒仙人。"]', '诗', 'shi', '', NULL, '贈李十二白 崔成甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d1e0476-7d14-40a4-8a31-eafa1bc29f95', '寄題杜拾遺錦江野亭', '寄題杜拾遺錦江野亭', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["漫向江頭把釣竿，懶眠沙草愛風湍。","莫倚善題鸚鵡賦，何須不著鵕鸃冠。","腹中書籍幽時曬，肘後醫方靜處看。","興發會能馳駿馬，應須直到使君灘。"]', '["漫向江头把釣竿，懶眠沙草愛风湍。","莫倚善題鸚鵡賦，何須不著鵕鸃冠。","腹中书籍幽时曬，肘後醫方静处看。","兴發會能驰駿马，應須直到使君灘。"]', '诗', 'shi', '', NULL, '寄題杜拾遺錦江野亭 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569ed2c5-a458-4fd4-ab8c-756a7f9f3e78', '酬別杜二', '酬別杜二', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["獨逢堯典日，再覩漢官時。","未効風霜勁，空慚雨露私。","夜鐘清萬戶，曙漏拂千旗。","並向殊庭謁，俱承別館追。","斗城憐舊路，渦水惜歸期。","峰樹還相伴，江雲更對垂。","試迴滄海櫂，莫妬敬亭詩。","秪是書應寄，無忘酒共持。","但令心事在，未肯鬢毛衰。","最悵巴山裏，清猨醒夢思。"]', '["独逢堯典日，再覩漢官时。","未効风霜勁，空慚雨露私。","夜鐘清万戶，曙漏拂千旗。","並向殊庭謁，俱承別館追。","斗城怜旧路，渦水惜归期。","峰樹還相伴，江云更对垂。","試迴滄海櫂，莫妬敬亭诗。","秪是书應寄，無忘酒共持。","但令心事在，未肯鬢毛衰。","最悵巴山裏，清猨醒梦思。"]', '诗', 'shi', '', NULL, '酬別杜二 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42a6899-25df-4c90-8aa1-3707929f20ac', '題巴州光福寺楠木', '題巴州光福寺楠木', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["楚江長流對楚寺，楠木幽生赤崖背。","臨谿插石盤老根，苔色青蒼山雨痕。","高枝鬧葉鳥不度，半掩白雲朝與暮。","香殿蕭條轉密陰，花龕滴瀝垂清露。","聞道偏多越水頭，煙生霽歛使人愁。","月明忽憶湘川夜，猨呌還思鄂渚秋。","看君幽靄幾千丈，寂寞窮山今遇賞。","亦知鐘梵報黃昏，猶臥禪牀戀奇響。"]', '["楚江长流对楚寺，楠木幽生赤崖背。","臨谿插石盤老根，苔色青蒼山雨痕。","高枝鬧葉鸟不度，半掩白云朝與暮。","香殿蕭條轉密陰，花龕滴瀝垂清露。","闻道偏多越水头，煙生霽歛使人愁。","月明忽憶湘川夜，猨呌還思鄂渚秋。","看君幽靄幾千丈，寂寞窮山今遇賞。","亦知鐘梵報黄昏，猶臥禪牀戀奇响。"]', '诗', 'shi', '', NULL, '題巴州光福寺楠木 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f600be4a-fb4c-4656-a203-9eab3847d449', '班婕妤', '班婕妤', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["賤妾如桃李，君王若歲時。","秋風一已勁，搖落不勝悲。","寂寂蒼苔滿，沈沈綠草滋。","繁華非此日，指輦競何辭。"]', '["賤妾如桃李，君王若歲时。","秋风一已勁，搖落不勝悲。","寂寂蒼苔满，沈沈綠草滋。","繁华非此日，指輦競何辞。"]', '诗', 'shi', '', NULL, '班婕妤 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d438c27b-a04b-4d22-8d1a-856edf0153d5', '巴嶺荅杜二見憶', '巴嶺荅杜二见憶', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["臥向巴山落月時，兩鄉千里夢相思。","可但步兵偏愛酒，也知光祿最能詩。","江頭赤葉楓愁客，籬外黃花菊對誰。","跂馬望君非一度，冷猨秋鴈不勝悲。"]', '["臥向巴山落月时，兩乡千里梦相思。","可但步兵偏愛酒，也知光祿最能诗。","江头赤葉楓愁客，籬外黄花菊对誰。","跂马望君非一度，冷猨秋鴈不勝悲。"]', '诗', 'shi', '', NULL, '巴嶺荅杜二見憶 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e07861d-a4bc-436e-a8bc-256e865edaa8', '軍城早秋', '軍城早秋', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["昨夜秋風入漢關，朔雲邊月滿西山。","更催飛將追驕虜，莫遣沙場匹馬遠。"]', '["昨夜秋风入漢关，朔云邊月满西山。","更催飞將追驕虜，莫遣沙場匹马远。"]', '诗', 'shi', '', NULL, '軍城早秋 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01610841-4c30-48d5-9891-1ef8abe037c2', '潭州留別杜員外院長', '潭州留別杜員外院长', 'c0316794-b70b-4496-bdcf-ea2323d9a070', '唐', '["江畔長沙驛，相逢纜客船。","大名詩獨步，小郡海西偏。","地濕愁飛鵩，天炎畏跕鳶。","去留俱失意，把臂共潸然。"]', '["江畔长沙驛，相逢纜客船。","大名诗独步，小郡海西偏。","地濕愁飞鵩，天炎畏跕鳶。","去留俱失意，把臂共潸然。"]', '诗', 'shi', '', NULL, '潭州留別杜員外院長 韋迢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcec503b-6166-446d-97b8-e97367465b22', '早發湘潭寄杜員外院長', '早發湘潭寄杜員外院长', 'c0316794-b70b-4496-bdcf-ea2323d9a070', '唐', '["北風昨夜雨，江上早來涼。","楚岫千峰翠，湘潭一葉黃。","故人湖外客，白首尚爲郎。","相憶無南鴈，何時有報章。"]', '["北风昨夜雨，江上早来涼。","楚岫千峰翠，湘潭一葉黄。","故人湖外客，白首尚爲郎。","相憶無南鴈，何时有報章。"]', '诗', 'shi', '', NULL, '早發湘潭寄杜員外院長 韋迢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7a8a88-9357-4aaf-a776-8dda768111da', '寄杜員外', '寄杜員外', '8a2636db-e577-48c7-8196-6010bb2cb7b4', '唐', '["新詩海內流傳久，舊德朝中屬望勞。","郡邑地卑饒霧雨，江湖天闊足風濤。","松花酒熟傍看醉，蓮葉舟輕自學操。","春興不知凡幾首，衡陽紙價頓能高。"]', '["新诗海內流傳久，旧德朝中屬望勞。","郡邑地卑饒霧雨，江湖天闊足风濤。","松花酒熟傍看醉，蓮葉舟轻自学操。","春兴不知凡幾首，衡陽紙價頓能高。"]', '诗', 'shi', '', NULL, '寄杜員外 郭受 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31922b75-1ce3-436e-bfde-6dc7fe8ef613', '晦日呈諸判官', '晦日呈諸判官', '99df2fff-254f-450a-af49-6675d131ee01', '唐', '["晦日新晴春色嬌，萬家攀折渡長橋。","年年老向江城寺，不覺春風換柳條。"]', '["晦日新晴春色嬌，万家攀折渡长橋。","年年老向江城寺，不覺春风換柳條。"]', '诗', 'shi', '', NULL, '晦日呈諸判官 韓滉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732b5f5f-c66b-418a-8edf-207a527926a8', '聽樂悵然自述', '听乐悵然自述', '99df2fff-254f-450a-af49-6675d131ee01', '唐', '["萬事傷心對管弦，一身含淚向春煙。","黃金用盡敎歌舞，留與他人樂少年。"]', '["万事傷心对管弦，一身含泪向春煙。","黄金用尽敎歌舞，留與他人乐少年。"]', '诗', 'shi', '', NULL, '聽樂悵然自述 韓滉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2758d03-e48e-406e-a461-2a47c99126d4', '題弟臮述書賦後', '題弟臮述书賦後', 'cc3d9c70-8bb3-4e65-95db-b5b017212f20', '唐', '["受命別家鄉，思歸每斷腸。","季江留被在，子敬與琴亡。","吾弟當平昔，才名荷寵光。","作詩通小雅，獻賦掩長楊。","流轉三千里，悲啼百萬行。","庭前紫荆樹，何日再芬芳。"]', '["受命別家乡，思归每斷腸。","季江留被在，子敬與琴亡。","吾弟當平昔，才名荷寵光。","作诗通小雅，獻賦掩长楊。","流轉三千里，悲啼百万行。","庭前紫荆樹，何日再芬芳。"]', '诗', 'shi', '', NULL, '題弟臮述書賦後 竇蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8203cd-e850-43d3-8fbd-b9d521b5e421', '迎春東郊', '迎春东郊', '7b44f9a1-a385-4bbc-af8d-ffb9b8be01b0', '唐', '["顓頊時初謝，句芒令復陳。","飛灰將應節，賓日已知春。","考曆明三統，迎祥受萬人。","衣冠宵執玉，壇墠曉清塵。","肅穆來東道，回環拱北辰。","仗前花待發，旂處柳疑新。","雲斂黃山際，冰開素滻濱。","聖朝多慶賞，希爲薦沈淪。"]', '["顓頊时初謝，句芒令复陳。","飞灰將應節，賓日已知春。","考曆明三統，迎祥受万人。","衣冠宵執玉，壇墠晓清塵。","肅穆来东道，回环拱北辰。","仗前花待發，旂处柳疑新。","云斂黄山際，冰开素滻濱。","聖朝多慶賞，希爲薦沈淪。"]', '诗', 'shi', '', NULL, '迎春東郊 張濯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad4658d-483c-4540-ad7a-ee5e7de8041d', '題舜廟', '題舜廟', '7b44f9a1-a385-4bbc-af8d-ffb9b8be01b0', '唐', '["古都遺廟出河濆，萬代千秋仰聖君。","蒲坂城邊長逝水，蒼梧野外不歸雲。","寥寥象設魂應在，寂寂虞篇德已聞。","向晚風吹庭下栢，猶疑琴曲韻南薰。"]', '["古都遺廟出河濆，万代千秋仰聖君。","蒲坂城邊长逝水，蒼梧野外不归云。","寥寥象設魂應在，寂寂虞篇德已闻。","向晚风吹庭下栢，猶疑琴曲韻南薰。"]', '诗', 'shi', '', NULL, '題舜廟 張濯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecfdb48f-8b75-45de-a82e-aa5da56a024c', '迎春東郊', '迎春东郊', '3b46fb31-d3e0-4a53-8b70-102b56add690', '唐', '["玉管潛移律，東郊始報春。","鑾輿應寶運，天仗出佳辰。","睿澤光時輩，恩輝及物新。","虬螭動旌斾，煙景入城闉。","御柳初含色，龍池漸啟津。","誰憐在陰者，得與蟄蟲伸。"]', '["玉管潛移律，东郊始報春。","鑾輿應寶運，天仗出佳辰。","睿澤光时輩，恩輝及物新。","虬螭动旌斾，煙景入城闉。","御柳初含色，龙池漸啟津。","誰怜在陰者，得與蟄蟲伸。"]', '诗', 'shi', '', NULL, '迎春東郊 王綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580be45a-7004-4b26-b5b5-85a6786c8031', '邯鄲少年行', '邯鄲少年行', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["霞鞍金口騮，豹袖紫貂裘。","家住叢臺近，門前漳水流。","喚人呈楚舞，借客試吳鉤。","見說秦兵至，甘心赴國讐。"]', '["霞鞍金口騮，豹袖紫貂裘。","家住叢台近，门前漳水流。","喚人呈楚舞，借客試吳鉤。","见说秦兵至，甘心赴国讐。"]', '诗', 'shi', '', NULL, '邯鄲少年行 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f2f234-2d7e-428d-80a8-0aa6c775c198', '隴頭別', '隴头別', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["秋盡初移幕，霑裳一送君。","據鞍窺古堠，開竈爇寒雲。","登隴人迴首，臨關馬顧羣。","從來斷腸處，皆向此中分。"]', '["秋尽初移幕，霑裳一送君。","據鞍窺古堠，开竈爇寒云。","登隴人迴首，臨关马顧羣。","從来斷腸处，皆向此中分。"]', '诗', 'shi', '', NULL, '隴頭別 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f6ce71-4ed1-4642-a150-bd3386966687', '度關山', '度关山', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["象弭插文犀，魚腸瑩鸊鵜。","水聲分隴咽，馬色度關迷。","曉幕胡沙慘，危烽漢月低。","仍聞數騎將，更欲出遼西。"]', '["象弭插文犀，鱼腸瑩鸊鵜。","水声分隴咽，马色度关迷。","晓幕胡沙慘，危烽漢月低。","仍闻數騎將，更欲出遼西。"]', '诗', 'shi', '', NULL, '度關山 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49030cc-3a5e-496a-8cf0-563b2e45bd7a', '出塞', '出塞', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["關山落葉秋，掩淚望營州。","遼海雲沙暮，幽燕旌斾愁。","戰餘能送陣，身老未封侯。","去國三千里，歸心紅粉樓。"]', '["关山落葉秋，掩泪望營州。","遼海云沙暮，幽燕旌斾愁。","戰餘能送陣，身老未封侯。","去国三千里，归心紅粉楼。"]', '诗', 'shi', '', NULL, '出塞 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f1f1a3-02d8-492e-b705-619b52b3c453', '玉階怨', '玉階怨', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["長門寒水流，高殿曉風秋。","昨夜鴛鴦夢，還陪豹尾游。","前魚不解泣，共輦豈關羞。","那及輕身燕，雙飛上玉樓。"]', '["长门寒水流，高殿晓风秋。","昨夜鴛鴦梦，還陪豹尾游。","前鱼不解泣，共輦豈关羞。","那及轻身燕，雙飞上玉楼。"]', '诗', 'shi', '', NULL, '玉階怨 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b45785-981e-4b6c-815f-8c96bf89fe24', '千里思', '千里思', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["渭水通胡苑，輪臺望漢關。","帛書秋海斷，錦字夜機閑。","旅夢蟲催曉，邊心雁帶還。","惟餘兩鄉思，一夕度關山。"]', '["渭水通胡苑，輪台望漢关。","帛书秋海斷，錦字夜機闲。","旅梦蟲催晓，邊心雁带還。","惟餘兩乡思，一夕度关山。"]', '诗', 'shi', '', NULL, '千里思 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a656f34a-7eaa-4396-94aa-198921d5610d', '襄陽樂', '襄陽乐', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["春生峴首東，先煖習池風。","拂水初含綠，驚林未吐紅。","渚邊游漢女，桑下問龐公。","磨滅懷中刺，曾將示孔融。"]', '["春生峴首东，先煖習池风。","拂水初含綠，驚林未吐紅。","渚邊游漢女，桑下问龐公。","磨滅懷中刺，曾將示孔融。"]', '诗', 'shi', '', NULL, '襄陽樂 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c15bdc-51ad-4102-b71e-a136afafbd95', '送客之江西', '送客之江西', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["乘軺奉紫泥，澤國渺天涯。","九派春潮滿，孤帆暮雨低。","草深鶯斷續，花落水東西。","更有高唐處，知君路不迷。"]', '["乘軺奉紫泥，澤国渺天涯。","九派春潮满，孤帆暮雨低。","草深鶯斷續，花落水东西。","更有高唐处，知君路不迷。"]', '诗', 'shi', '', NULL, '送客之江西 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30baa31d-a7ae-4e3a-bd63-bd0bb2d9602b', '望月', '望月', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["高堂新月明，虛殿夕風清。","素影紗窗霽，浮涼羽扇輕。","稍隨微露滴，漸逐曉參橫。","遙憶雲中詠，蕭條空復情。"]', '["高堂新月明，虛殿夕风清。","素影紗窗霽，浮涼羽扇轻。","稍隨微露滴，漸逐晓參橫。","遙憶云中詠，蕭條空复情。"]', '诗', 'shi', '', NULL, '望月 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8bb182-515f-4f05-826e-455f0bb635aa', '出塞曲', '出塞曲', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["校尉徵兵出塞西，別營分騎過龍溪。","沙平虜跡風吹盡，霧失烽煙道易迷。","玉靶半開鴻已落，金河欲渡馬連嘶。","會當繫取天驕入，不使軍書夜刺閨。"]', '["校尉徵兵出塞西，別營分騎過龙溪。","沙平虜跡风吹尽，霧失烽煙道易迷。","玉靶半开鴻已落，金河欲渡马連嘶。","會當繫取天驕入，不使軍书夜刺閨。"]', '诗', 'shi', '', NULL, '出塞曲 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c557ea-2e73-4d65-87a2-0f19744db796', '秦人謠', '秦人謠', '6efd3ad9-e7c9-4df4-82d5-9c175419eb06', '唐', '["微生祖龍代，却思堯舜道。","何人仕帝庭，拔殺指佞草。","姦臣弄民柄，天子恣衷抱。","上下一相蒙，馬鹿遂顛倒。","中國既板蕩，骨肉安可保。","人生貴年壽，吾恨死不早。"]', '["微生祖龙代，却思堯舜道。","何人仕帝庭，拔殺指佞草。","姦臣弄民柄，天子恣衷抱。","上下一相蒙，马鹿遂顛倒。","中国既板蕩，骨肉安可保。","人生貴年壽，吾恨死不早。"]', '诗', 'shi', '', NULL, '秦人謠 古之奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00734d59-0333-4186-aa31-5a036d2315f0', '阮客舊居', '阮客旧居', '801247f7-1cb0-4edc-b616-90182d829172', '唐', '["阮客身何在，仙雲洞口橫。","人間不到處，今日此中行。"]', '["阮客身何在，仙云洞口橫。","人间不到处，今日此中行。"]', '诗', 'shi', '', NULL, '阮客舊居 李陽冰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac5c9c8-bdb3-4b45-8902-8ad630c32ca0', '酬耿拾遺題贈', '酬耿拾遺題贈', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["掩扉常自靜，驛吏忽傳呼。","水巷驚馴鳥，藜牀起病軀。","顧身悲欲老，戒子力爲儒。","明日公西去，煙霞復作徒。"]', '["掩扉常自静，驛吏忽傳呼。","水巷驚馴鸟，藜牀起病軀。","顧身悲欲老，戒子力爲儒。","明日公西去，煙霞复作徒。"]', '诗', 'shi', '', NULL, '酬耿拾遺題贈 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62bc9c98-db76-48ad-810d-6cfb2541d2da', '酬王侍御西陵渡見寄', '酬王侍御西陵渡见寄', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["前年萬里別，昨日一封書。","郢曲西陵渡，秦官使者車。","柳塘薰晝日，花水溢春渠。","若不嫌雞黍，先令掃弊廬。"]', '["前年万里別，昨日一封书。","郢曲西陵渡，秦官使者车。","柳塘薰晝日，花水溢春渠。","若不嫌雞黍，先令掃弊廬。"]', '诗', 'shi', '', NULL, '酬王侍御西陵渡見寄 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4b371df-388a-4eac-9f57-1e11c451ffed', '酬劉員外見寄', '酬劉員外见寄', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["蘇耽佐郡時，近出白雲司。","藥補清羸疾，窗吟絕妙詞。","柳塘春水慢，花塢夕陽遲。","欲識懷君意，明朝訪檝師。"]', '["蘇耽佐郡时，近出白云司。","藥補清羸疾，窗吟絕妙词。","柳塘春水慢，花塢夕陽遲。","欲識懷君意，明朝訪檝師。"]', '诗', 'shi', '', NULL, '酬劉員外見寄 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e87f174-5f75-4b2c-9a6a-3858ead274d4', '同韓員外宿雲門寺', '同韓員外宿云门寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["小嶺路難近，仙郎此夕過。","潭空觀月定，澗靜見雲多。","竹翠煙深鎖，松聲雨點和。","萬緣俱不有，對境自垂蘿。"]', '["小嶺路难近，仙郎此夕過。","潭空观月定，澗静见云多。","竹翠煙深鎖，松声雨点和。","万緣俱不有，对境自垂蘿。"]', '诗', 'shi', '', NULL, '同韓員外宿雲門寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d413c37-f370-4d3e-ab48-0b6137b83ba8', '酬諸公宿鏡水宅', '酬諸公宿镜水宅', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["幸免低頭向府中，貴將藜藿與君同。","陽雁呌霜來枕上，寒山映月在湖中。","詩書何德名夫子，草木推年長數公。","聞道漢家偏尚少，此身那此訪芝翁。"]', '["幸免低头向府中，貴將藜藿與君同。","陽雁呌霜来枕上，寒山映月在湖中。","诗书何德名夫子，草木推年长數公。","闻道漢家偏尚少，此身那此訪芝翁。"]', '诗', 'shi', '', NULL, '酬諸公宿鏡水宅 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a465599-72af-42d1-a4b6-5d242a2d4ab4', '送薛尚書入蜀', '送薛尚书入蜀', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["卑情不敢論，拜首入轅門。","列郡諸侯長，登朝八座尊。","凝笳臨水發，行斾向風飜。","幾許遺黎泣，同懷父母恩。"]', '["卑情不敢論，拜首入轅门。","列郡諸侯长，登朝八座尊。","凝笳臨水發，行斾向风飜。","幾許遺黎泣，同懷父母恩。"]', '诗', 'shi', '', NULL, '送薛尚書入蜀 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d0f08cd-47d0-455a-a70d-3754d57320d6', '送李祕書往儋州', '送李祕书往儋州', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["魑魅曾爲伍，蓬萊近拜郎。","臣心瞻北闕，家事在南荒。","莎草山城小，毛洲海驛長。","玄成知必大，寧是泛滄浪。"]', '["魑魅曾爲伍，蓬萊近拜郎。","臣心瞻北闕，家事在南荒。","莎草山城小，毛洲海驛长。","玄成知必大，寧是泛滄浪。"]', '诗', 'shi', '', NULL, '送李祕書往儋州 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd0dbb6-40fa-4424-bea1-8650f7513987', '送人入金華', '送人入金华', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["明月雙溪水，清風八詠樓。","昔年爲客處，今日送君遊。"]', '["明月雙溪水，清风八詠楼。","昔年爲客处，今日送君游。"]', '诗', 'shi', '', NULL, '送人入金華 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96977d5f-eb6e-4e4c-bcb9-0dc78604119c', '送崔峒使往睦州兼寄薛司戶', '送崔峒使往睦州兼寄薛司戶', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["如今相府用英髦，獨往南州肯告勞。","冰水近開漁浦出，雪雲初卷定山高。","木奴花映桐廬縣，青雀舟隨白露濤。","使者應須訪廉吏，府中惟有范功曹。"]', '["如今相府用英髦，独往南州肯告勞。","冰水近开漁浦出，雪云初卷定山高。","木奴花映桐廬縣，青雀舟隨白露濤。","使者應須訪廉吏，府中惟有范功曹。"]', '诗', 'shi', '', NULL, '送崔峒使往睦州兼寄薛司戶 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9d6696-ea76-4268-a241-99cd7cd1820f', '送房元直赴北京', '送房元直赴北京', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["猶道樓蘭十萬師，書生匹馬去何之。","臨歧未斷歸家目，望月空吟出塞詩。","常欲激昂論上策，不應憔悴老明時。","遙知到日逢寒食，彩筆長裾會晉祠。"]', '["猶道楼蘭十万師，书生匹马去何之。","臨歧未斷归家目，望月空吟出塞诗。","常欲激昂論上策，不應憔悴老明时。","遙知到日逢寒食，彩笔长裾會晉祠。"]', '诗', 'shi', '', NULL, '送房元直赴北京 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('567c5382-3b53-4cc8-8b8a-d87f8c7ddaee', '荆溪館呈丘義興', '荆溪館呈丘義兴', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["失路荆溪上，依人忽暝投。","長橋今夜月，陽羨古時州。","野燒明山郭，寒更出縣樓。","先生能館我，無事五湖遊。"]', '["失路荆溪上，依人忽暝投。","长橋今夜月，陽羨古时州。","野燒明山郭，寒更出縣楼。","先生能館我，無事五湖游。"]', '诗', 'shi', '', NULL, '荆溪館呈丘義興 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8d93ea-6e17-4694-ab77-6d7bd98c0037', '一公新泉', '一公新泉', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["山下新泉出，泠泠北去源。","落池纔有響，噴石未成痕。","獨映孤松色，殊分衆鳥喧。","唯當清夜月，觀此啓禪門。"]', '["山下新泉出，泠泠北去源。","落池纔有响，噴石未成痕。","独映孤松色，殊分衆鸟喧。","唯當清夜月，观此啓禪门。"]', '诗', 'shi', '', NULL, '一公新泉 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff54523a-a05e-4c51-bbe4-bd848346b2c1', '奉試水精環', '奉試水精环', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["王室符長慶，環中得水精。","任圓循不極，見素質仍貞。","信是天然瑞，非因樸斲成。","無瑕勝玉美，至潔過冰清。","未肯齊珉價，寧同雜佩聲。","能銜任黃雀，亦欲應時明。"]', '["王室符长慶，环中得水精。","任圓循不極，见素質仍貞。","信是天然瑞，非因樸斲成。","無瑕勝玉美，至潔過冰清。","未肯齊珉價，寧同杂佩声。","能銜任黄雀，亦欲應时明。"]', '诗', 'shi', '', NULL, '奉試水精環 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c5e7185-6ddb-443f-81ed-e7d2d9d59460', '自雲陽歸晚泊陸澧宅', '自云陽归晚泊陸澧宅', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["天陰行易晚，前路故人居。","孤棹所思久，寒林相見初。","閑燈忘夜水，清漏任更疎。","明發還須去，離家幾歲除。"]', '["天陰行易晚，前路故人居。","孤棹所思久，寒林相见初。","闲灯忘夜水，清漏任更疎。","明發還須去，離家幾歲除。"]', '诗', 'shi', '', NULL, '自雲陽歸晚泊陸澧宅 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec1004b-ebea-4636-9fb6-9bd05737c70e', '九日陪崔郎中北山讌', '九日陪崔郎中北山讌', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["上客南臺至，重陽此會文。","菊芳寒露洗，杯翠夕陽曛。","務簡人同醉，溪閑鳥自羣。","府中官最小，唯有孟參軍。"]', '["上客南台至，重陽此會文。","菊芳寒露洗，杯翠夕陽曛。","務簡人同醉，溪闲鸟自羣。","府中官最小，唯有孟參軍。"]', '诗', 'shi', '', NULL, '九日陪崔郎中北山讌 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82e2190-3a65-468e-a56c-623ee94fe2aa', '留別鄒紹劉長卿', '留別鄒紹劉长卿', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["中年從一尉，自笑此身非。","道在甘微祿，時難耻息機。","晨趨本郡府，書掩故山扉。","待見干戈畢，何妨更採薇。"]', '["中年從一尉，自笑此身非。","道在甘微祿，时难耻息機。","晨趨本郡府，书掩故山扉。","待见干戈畢，何妨更採薇。"]', '诗', 'shi', '', NULL, '留別鄒紹劉長卿 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118a0230-50a2-4ff3-9c3f-c4f33f4969f1', '書情獻相公', '书情獻相公', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["年來白髮欲星星，誤却生涯是一經。","魏闕望中何日見，商歌奏罷復誰聽。","孤根獨棄慙山木，弱質無成狀水萍。","今日更須詢哲匠，不應休去老巖扃。"]', '["年来白髮欲星星，誤却生涯是一經。","魏闕望中何日见，商歌奏罷复誰听。","孤根独棄慙山木，弱質無成狀水萍。","今日更須詢哲匠，不應休去老巖扃。"]', '诗', 'shi', '', NULL, '書情獻相公 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c178fad8-195b-4069-b641-c529af5dcc72', '贈送朱放', '贈送朱放', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["昔年居漢水，日醉習家池。","道勝迹常在，名高身不知。","欲依天目住，新自始寧移。","生事曾無長，惟將白接䍦。"]', '["昔年居漢水，日醉習家池。","道勝迹常在，名高身不知。","欲依天目住，新自始寧移。","生事曾無长，惟將白接䍦。"]', '诗', 'shi', '', NULL, '贈送朱放 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab59e81-b943-4b03-b08a-a34e4cefeee8', '剡中贈張卿侍御', '剡中贈張卿侍御', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["辟疆年正少，公子貴初還。","早列月卿位，新參柱史班。","千夫馳驛道，駟馬入家山。","深巷烏衣盛，高門畫戟閑。","逶迤天樂下，照耀剡溪間。","自賤遊章句，空爲衰草顏。"]', '["辟疆年正少，公子貴初還。","早列月卿位，新參柱史班。","千夫驰驛道，駟马入家山。","深巷烏衣盛，高门畫戟闲。","逶迤天乐下，照耀剡溪间。","自賤游章句，空爲衰草顏。"]', '诗', 'shi', '', NULL, '剡中贈張卿侍御 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f733ca9-4c37-4c5b-9e25-e39166c1cf16', '贈萬經', '贈万經', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["萬公長慢世，昨日又隳官。","縱酒真彭澤，論詩得建安。","家山伯禹穴，別墅小長干。","輙有時人至，窗前白眼看。"]', '["万公长慢世，昨日又隳官。","縱酒真彭澤，論诗得建安。","家山伯禹穴，別墅小长干。","輙有时人至，窗前白眼看。"]', '诗', 'shi', '', NULL, '贈萬經 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdfafd13-b5b9-4f27-abd2-c74089c71259', '書情上李蘇州', '书情上李蘇州', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["東土苗人尚有殘，皇皇亞相出朝端。","手持國憲羣僚畏，口喻天慈百姓安。","禮數自憐今日絕，風流空計往年歡。","誤著青袍將十載，忍令漁浦却垂竿。"]', '["东土苗人尚有殘，皇皇亞相出朝端。","手持国憲羣僚畏，口喻天慈百姓安。","禮數自怜今日絕，风流空計往年歡。","誤著青袍將十載，忍令漁浦却垂竿。"]', '诗', 'shi', '', NULL, '書情上李蘇州 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd23434-81a1-4c36-8196-e262f883e289', '餘姚祗役奉簡鮑參軍', '餘姚祗役奉簡鲍參軍', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["童年獻賦在皇州，方寸思量君與侯。","萬事無成新白首，兩春虛擲對滄流。","歌詩盛賦文星動，簫管新亭晦日遊。","知己欲依何水部，鄉人今正賤東丘。"]', '["童年獻賦在皇州，方寸思量君與侯。","万事無成新白首，兩春虛擲对滄流。","歌诗盛賦文星动，簫管新亭晦日游。","知己欲依何水部，乡人今正賤东丘。"]', '诗', 'shi', '', NULL, '餘姚祗役奉簡鮑參軍 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1143c442-058a-462d-b5cc-63b9947e4823', '奉和獨孤中丞遊雲門寺', '奉和独孤中丞游云门寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["絕壑開花界，耶溪極上源。","光輝三獨坐，登陟五雲門。","深木鳴騶馭，晴山曜武賁。","亂泉觀坐臥，疎磬發朝昏。","蒼翠新秋色，莓苔積雨痕。","上方看度鳥，後夜聽吟猿。","異跡焚香對，新詩酌茗論。","歸來還撫俗，諸老莫攀轅。"]', '["絕壑开花界，耶溪極上源。","光輝三独坐，登陟五云门。","深木鳴騶馭，晴山曜武賁。","亂泉观坐臥，疎磬發朝昏。","蒼翠新秋色，莓苔積雨痕。","上方看度鸟，後夜听吟猿。","異跡焚香对，新诗酌茗論。","归来還撫俗，諸老莫攀轅。"]', '诗', 'shi', '', NULL, '奉和獨孤中丞遊雲門寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffed3e70-8753-466c-ac59-0fdb5894adfd', '奉和皇甫大夫夏日遊花嚴寺', '奉和皇甫大夫夏日游花嚴寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["初第華嚴會，王家少長行。","到宮龍節駐，禮塔雁行成。","蓮界千峰靜，梅天一雨清。","禪庭未可戀，聖主寄蒼生。"]', '["初第华嚴會，王家少长行。","到宮龙節駐，禮塔雁行成。","蓮界千峰静，梅天一雨清。","禪庭未可戀，聖主寄蒼生。"]', '诗', 'shi', '', NULL, '奉和皇甫大夫夏日遊花嚴寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07aef71c-f716-4736-b80e-7425ea8f00ba', '宿法華寺', '宿法华寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["一夕雨沈沈，哀猨萬木陰。","天龍來護法，長老密看心。","魚梵空山靜，紗燈古殿深。","無生久已學，白髮浪相侵。"]', '["一夕雨沈沈，哀猨万木陰。","天龙来護法，长老密看心。","鱼梵空山静，紗灯古殿深。","無生久已学，白髮浪相侵。"]', '诗', 'shi', '', NULL, '宿法華寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f03841c-5cf1-43e3-9d96-d1768981de42', '題茅山李尊師所居', '題茅山李尊師所居', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["天師百歲少如童，不到山中更不逢。","洗藥每臨新瀑水，步虛時遶最高峰。","籬根五月留殘雪，座右千年蔭古松。","此去人寰知近遠，迴看路隔一重重。"]', '["天師百歲少如童，不到山中更不逢。","洗藥每臨新瀑水，步虛时遶最高峰。","籬根五月留殘雪，座右千年蔭古松。","此去人寰知近远，迴看路隔一重重。"]', '诗', 'shi', '', NULL, '題茅山李尊師所居 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f033648-d76a-4de4-ba1d-8c0298fa5c3d', '送薛居士和州讀書', '送薛居士和州读书', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["孤雲獨鶴共悠悠，萬卷經書一葉舟。","楚地巢城民舍少，煙村社樹鷺湖秋。","蒿萊織妾晨炊黍，隅落耕童夕放牛。","年少不應辭苦節，諸生若遇亦封侯。"]', '["孤云独鹤共悠悠，万卷經书一葉舟。","楚地巢城民舍少，煙村社樹鷺湖秋。","蒿萊织妾晨炊黍，隅落耕童夕放牛。","年少不應辞苦節，諸生若遇亦封侯。"]', '诗', 'shi', '', NULL, '送薛居士和州讀書 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c18ea1-db49-44b5-8b21-6176e4a86416', '送李端', '送李端', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["故關衰草遍，離別正堪悲。","路出寒雲外，人歸暮雪時。","少孤爲客早，多難識君遲。","揜泣空相向，風塵何所期。"]', '["故关衰草遍，離別正堪悲。","路出寒云外，人归暮雪时。","少孤爲客早，多难識君遲。","揜泣空相向，风塵何所期。"]', '诗', 'shi', '', NULL, '送李端 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5112ca49-faea-4dcc-8589-6d0327799bc8', '宿天竺寺', '宿天竺寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["方外主人名道林，怕將水月淨身心。","居然對我說無我，寂歷山深將夜深。"]', '["方外主人名道林，怕將水月淨身心。","居然对我说無我，寂歷山深將夜深。"]', '诗', 'shi', '', NULL, '宿天竺寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f9d60e5-bd15-4f2f-89e2-b6dcf8d26064', '丹陽送韋參軍', '丹陽送韋參軍', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["丹陽郭裏送行舟，一別心知兩地秋。","日晚江南望江北，寒鴉飛盡水悠悠。"]', '["丹陽郭裏送行舟，一別心知兩地秋。","日晚江南望江北，寒鴉飞尽水悠悠。"]', '诗', 'shi', '', NULL, '丹陽送韋參軍 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d724eb7-febd-4169-aa23-a3917fda6ca7', '入唐溪', '入唐溪', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["嘯終萬籟起，吹去當溪雲。","環嶼或明昧，遠峯尚氛氳。","雨新翠葉發，夜早玄象分。","金澗流不盡，入山深更聞。"]', '["嘯終万籟起，吹去當溪云。","环嶼或明昧，远峯尚氛氳。","雨新翠葉發，夜早玄象分。","金澗流不尽，入山深更闻。"]', '诗', 'shi', '', NULL, '入唐溪 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c724c20d-b1a6-4044-af22-5cb1b6aba150', '送桃巖成上人歸本寺', '送桃巖成上人归本寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["長老歸緣起，桃花憶舊巖。","清晨雲抱石，深夜月籠杉。","道具門人捧，齋粮谷鳥銜。","餘生願依止，文字欲三緘。"]', '["长老归緣起，桃花憶旧巖。","清晨云抱石，深夜月籠杉。","道具门人捧，斋粮谷鸟銜。","餘生願依止，文字欲三緘。"]', '诗', 'shi', '', NULL, '送桃巖成上人歸本寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2049c49c-8641-4e79-9342-992de31f2a5e', '酬普選二上人期相會見寄', '酬普選二上人期相會见寄', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["本意宿東林，因聽子賤琴。","遙知大小朗，已斷去來心。","夜靜溪聲近，庭寒月色深。","寧知塵外意，定後便成吟。"]', '["本意宿东林，因听子賤琴。","遙知大小朗，已斷去来心。","夜静溪声近，庭寒月色深。","寧知塵外意，定後便成吟。"]', '诗', 'shi', '', NULL, '酬普選二上人期相會見寄 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4fe62aa-8fa5-48ee-a40f-bedac42c701d', '相里使君宅聽澄上人吹小管', '相里使君宅听澄上人吹小管', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["秦僧吹竹閉秋城，早在梨園稱主情。","今夕襄陽山太守，座中流淚聽商聲。"]', '["秦僧吹竹閉秋城，早在梨园稱主情。","今夕襄陽山太守，座中流泪听商声。"]', '诗', 'shi', '', NULL, '相里使君宅聽澄上人吹小管 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d23b6d-1e99-4088-aa84-fb9f684d4f1c', '贈別至弘上人', '贈別至弘上人', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["最稱弘偃少，早歲草茆居。","年老從僧律，生知解佛書。","衲衣求壞帛，野飯拾春蔬。","章句無求斷，時中學有餘。"]', '["最稱弘偃少，早歲草茆居。","年老從僧律，生知解佛书。","衲衣求壞帛，野飯拾春蔬。","章句無求斷，时中学有餘。"]', '诗', 'shi', '', NULL, '贈別至弘上人 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa3f5aa-d3a0-4650-afb2-6f9a79d01204', '奉和劉祭酒傷白馬', '奉和劉祭酒傷白马', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["沛艾如龍馬，來從上苑中。","棣華恩見賜，伯舅禮仍崇。","鏡點黃金眼，花開白雪騣。","性柔君子德，足逸大王風。","色照鳴珂靜，聲連噴玉雄。","食場恩未盡，過隟命旋終。","練影依雲沒，銀鞍向月空。","仍聞樂府唱，猶念代勞功。"]', '["沛艾如龙马，来從上苑中。","棣华恩见賜，伯舅禮仍崇。","镜点黄金眼，花开白雪騣。","性柔君子德，足逸大王风。","色照鳴珂静，声連噴玉雄。","食場恩未尽，過隟命旋終。","練影依云沒，銀鞍向月空。","仍闻乐府唱，猶念代勞功。"]', '诗', 'shi', '', NULL, '奉和劉祭酒傷白馬 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c480b6c-f2a8-4726-8cdd-1e4c8c54f2d7', '哭靈一上人', '哭靈一上人', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["一公何不住，空有遠公名。","共說岑山路，今時不可行。","舊房松更老，新塔草初生。","經論傳緇侶，文章遍墨卿。","禪林枝幹折，法宇棟梁傾。","誰復修僧史，應知傳已成。"]', '["一公何不住，空有远公名。","共说岑山路，今时不可行。","旧房松更老，新塔草初生。","經論傳緇侶，文章遍墨卿。","禪林枝幹折，法宇棟梁傾。","誰复修僧史，應知傳已成。"]', '诗', 'shi', '', NULL, '哭靈一上人 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f86ad791-a68e-43bf-903a-e9ee6dec7ee7', '題鮑行軍小閣', '題鲍行軍小閣', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["宇下無留事，經營意獨新。","文房已得地，相閣是推輪。","席上招賢急，山陰對雪頻。","虛明先旦暮，啓閉異冬春。","談笑兵家法，逢迎幕府賓。","還將負暄處，時借在陰人。"]', '["宇下無留事，經營意独新。","文房已得地，相閣是推輪。","席上招賢急，山陰对雪頻。","虛明先旦暮，啓閉異冬春。","談笑兵家法，逢迎幕府賓。","還將負暄处，时借在陰人。"]', '诗', 'shi', '', NULL, '題鮑行軍小閣 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82c0c1d-2a56-453c-b97a-93ecb879035a', '陪皇甫大夫謁禹廟', '陪皇甫大夫謁禹廟', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["竹使羞殷薦，松龕拜夏祠。","爲魚歌德後，舞羽降神時。","文衛瞻如在，精靈信有期。","夕陽陪醉止，塘上鳥咸遲。"]', '["竹使羞殷薦，松龕拜夏祠。","爲鱼歌德後，舞羽降神时。","文衛瞻如在，精靈信有期。","夕陽陪醉止，塘上鸟咸遲。"]', '诗', 'shi', '', NULL, '陪皇甫大夫謁禹廟 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a08a51-e2b8-4ccc-8148-874714a1ade3', '同王徴君湘中有懷', '同王徴君湘中有懷', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["八月洞庭秋，瀟湘水北流。","還家萬里夢，爲客五更愁。","不用看書帙，偏宜上酒樓。","故人京洛滿，何日復同遊。"]', '["八月洞庭秋，瀟湘水北流。","還家万里梦，爲客五更愁。","不用看书帙，偏宜上酒楼。","故人京洛满，何日复同游。"]', '诗', 'shi', '', NULL, '同王徴君湘中有懷 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c4138c-584d-499f-b012-86d13061cbf8', '奉和皇甫大夫祈雨應時雨降', '奉和皇甫大夫祈雨應时雨降', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["致和知必感，歲旱未書災。","伯禹明靈降，元戎禱請來。","九成陳夏樂，三獻奉殷罍。","掣曳旗交電，鏗鏘鼓應雷。","行雲依蓋轉，飛雨逐車回。","欲識皇天意，爲霖貺在哉。"]', '["致和知必感，歲旱未书災。","伯禹明靈降，元戎禱請来。","九成陳夏乐，三獻奉殷罍。","掣曳旗交電，鏗鏘鼓應雷。","行云依蓋轉，飞雨逐车回。","欲識皇天意，爲霖貺在哉。"]', '诗', 'shi', '', NULL, '奉和皇甫大夫祈雨應時雨降 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fcb41d0-91d9-412c-aec6-bc4ff3a07ff8', '贈別劉長卿時赴河南嚴中丞幕府', '贈別劉长卿时赴河南嚴中丞幕府', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["早見登郎署，同時跡下僚。","幾年江路永，今去國門遙。","文變騷人體，官移漢帝朝。","望山吟度日，接枕話通宵。","萬里趨公府，孤帆恨信潮。","匡時知已老，聖代耻逃堯。"]', '["早见登郎署，同时跡下僚。","幾年江路永，今去国门遙。","文变騷人體，官移漢帝朝。","望山吟度日，接枕話通宵。","万里趨公府，孤帆恨信潮。","匡时知已老，聖代耻逃堯。"]', '诗', 'shi', '', NULL, '贈別劉長卿時赴河南嚴中丞幕府 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8089b494-c996-4702-86de-1edbbb136e75', '晦日宴遊', '晦日宴游', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["晦日湔裾俗，春樓致酒時。","出山還已醉，謝客舊能詩。","溪柳薰晴淺，巖花待閏遲。","爲邦久無事，比屋自熙熙。"]', '["晦日湔裾俗，春楼致酒时。","出山還已醉，謝客旧能诗。","溪柳薰晴淺，巖花待閏遲。","爲邦久無事，比屋自熙熙。"]', '诗', 'shi', '', NULL, '晦日宴遊 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bd542a-0f04-4df6-9698-9890ca8068af', '夏日納涼', '夏日納涼', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["山陰過野客，鏡裏接仙郎。","盥漱臨寒水，褰闈入夏堂。","杉松交日影，枕簟上湖光。","衮衮承嘉話，清風納晚涼。"]', '["山陰過野客，镜裏接仙郎。","盥漱臨寒水，褰闈入夏堂。","杉松交日影，枕簟上湖光。","衮衮承嘉話，清风納晚涼。"]', '诗', 'shi', '', NULL, '夏日納涼 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7fc002-346c-4195-9624-74780a383faa', '僧房避暑', '僧房避暑', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["支公好閑寂，庭宇愛林篁。","幽曠無煩暑，恬和不可量。","蕙風清水殿，荷氣雜天香。","明月談空坐，怡然道術忘。"]', '["支公好闲寂，庭宇愛林篁。","幽曠無煩暑，恬和不可量。","蕙风清水殿，荷氣杂天香。","明月談空坐，怡然道術忘。"]', '诗', 'shi', '', NULL, '僧房避暑 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048f51d2-fa75-4b76-96ec-d03a315e058b', '九日登高', '九日登高', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["詩家九日憐芳菊，遲客高齋瞰浙江。","漢浦浪花搖素壁，西陵樹色入秋窗。","木奴向熟懸金實，桑落新開瀉玉缸。","四子醉時爭講德，笑論黃霸屈爲邦。"]', '["诗家九日怜芳菊，遲客高斋瞰浙江。","漢浦浪花搖素壁，西陵樹色入秋窗。","木奴向熟懸金實，桑落新开瀉玉缸。","四子醉时爭講德，笑論黄霸屈爲邦。"]', '诗', 'shi', '', NULL, '九日登高 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4df8fb5-828a-4fab-aad5-ffdb1f663a32', '九月十日即事', '九月十日即事', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["家貧惟種竹，時幸故人看。","菊度重陽少，林經閏月寒。","宿酲猶落帽，華髮強扶冠。","美景良難得，今朝更盡歡。"]', '["家貧惟種竹，时幸故人看。","菊度重陽少，林經閏月寒。","宿酲猶落帽，华髮強扶冠。","美景良难得，今朝更尽歡。"]', '诗', 'shi', '', NULL, '九月十日即事 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7c7f60-f630-476e-9032-62caad68a0fc', '送丘爲下第歸蘇州', '送丘爲下第归蘇州', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["滄江一身客，獻賦空十年。","明主豈能好，今人誰舉賢。","國門稅征駕，旅食謀歸旋。","皦日媚春水，綠蘋香客船。","無媒既不達，余亦思歸田。"]', '["滄江一身客，獻賦空十年。","明主豈能好，今人誰舉賢。","国门稅征駕，旅食謀归旋。","皦日媚春水，綠蘋香客船。","無媒既不達，余亦思归田。"]', '诗', 'shi', '', NULL, '送丘爲下第歸蘇州 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0334bf67-5fb4-45a2-ab4a-ef7e2b24af02', '送少微上人東南遊', '送少微上人东南游', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["舊遊多不見，師在翟公門。","瘴海空山熱，雷州白日昏。","片心應爲法，萬里獨無言。","人盡酬恩去，平生未感恩。"]', '["旧游多不见，師在翟公门。","瘴海空山熱，雷州白日昏。","片心應爲法，万里独無言。","人尽酬恩去，平生未感恩。"]', '诗', 'shi', '', NULL, '送少微上人東南遊 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e1db88-76e9-4bd6-bd20-53d8181703d8', '贈送崔子向', '贈送崔子向', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["旅食來江上，求名赴洛陽。","新詩蹤謝守，內學似支郎。","行怯秦爲客，心依越是鄉。","何人作知己，送爾淚浪浪。"]', '["旅食来江上，求名赴洛陽。","新诗蹤謝守，內学似支郎。","行怯秦爲客，心依越是乡。","何人作知己，送爾泪浪浪。"]', '诗', 'shi', '', NULL, '贈送崔子向 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf81149-2dbe-4a75-9c7d-baeccd05e8fb', '答劉長卿七里瀨重送', '答劉长卿七里瀨重送', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["新安非欲枉帆過，海內如君有幾何。","醉裏別時秋水色，老人南望一狂歌。"]', '["新安非欲枉帆過，海內如君有幾何。","醉裏別时秋水色，老人南望一狂歌。"]', '诗', 'shi', '', NULL, '答劉長卿七里瀨重送 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10696671-649a-4453-a481-3b8682af5262', '歲初喜皇甫侍御至', '歲初喜皇甫侍御至', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["湖上新正逢故人，情深應不笑家貧。","明朝別後門還掩，修竹千竿一老身。"]', '["湖上新正逢故人，情深應不笑家貧。","明朝別後门還掩，修竹千竿一老身。"]', '诗', 'shi', '', NULL, '歲初喜皇甫侍御至 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d31482-f505-4dd5-9a47-cba85261a917', '送舍弟', '送舍弟', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["疎懶吾成性，才華爾自彊。","早稱眉最白，何事綬仍黃。","時暑嗟于邁，家貧念聚糧。","秪應宵夢裏，詩興屬池塘。"]', '["疎懶吾成性，才华爾自彊。","早稱眉最白，何事綬仍黄。","时暑嗟于邁，家貧念聚糧。","秪應宵梦裏，诗兴屬池塘。"]', '诗', 'shi', '', NULL, '送舍弟 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ed0a84-8d36-421f-b6fa-3b9478cbb9a0', '示外生', '示外生', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["牽役非吾好，寬情爾在傍。","經過悲井邑，起坐倦舟航。","相宅生應貴，逢時學可強。","無輕吾未用，世事有行藏。"]', '["牽役非吾好，寬情爾在傍。","經過悲井邑，起坐倦舟航。","相宅生應貴，逢时学可強。","無轻吾未用，世事有行藏。"]', '诗', 'shi', '', NULL, '示外生 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0849cb37-6920-4dc6-9471-22a4e11b750c', '詠孩子', '詠孩子', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["嘉客會初筵，宜時魄再圓。","衆皆含笑戲，誰不點頤憐。","繡被花堪摘，羅繃色欲妍。","將雛有舊曲，還入武城弦。"]', '["嘉客會初筵，宜时魄再圓。","衆皆含笑戲，誰不点頤怜。","繡被花堪摘，羅繃色欲妍。","將雛有旧曲，還入武城弦。"]', '诗', 'shi', '', NULL, '詠孩子 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b28f85a-4497-40f0-b1c5-ed939c384dc2', '酬謝侍御喜王宇及第見賀不遇之作', '酬謝侍御喜王宇及第见賀不遇之作', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["寂寞柴門掩，經過柱史榮。","老夫寧有力，半子自成名。","柳映三橋發，花連上道明。","緘書到別墅，郢曲果先成。"]', '["寂寞柴门掩，經過柱史榮。","老夫寧有力，半子自成名。","柳映三橋發，花連上道明。","緘书到別墅，郢曲果先成。"]', '诗', 'shi', '', NULL, '酬謝侍御喜王宇及第見賀不遇之作 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcdeac12-ba53-435d-9137-cab33483451b', '秋日與諸公文會天寺', '秋日與諸公文會天寺', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["相訪從吾道，因緣會爾時。","龍盤餘帝宅，花界古人祠。","明月虛空色，青林大小枝。","還將經濟學，來問道安師。"]', '["相訪從吾道，因緣會爾时。","龙盤餘帝宅，花界古人祠。","明月虛空色，青林大小枝。","還將經濟学，来问道安師。"]', '诗', 'shi', '', NULL, '秋日與諸公文會天寺 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d58e30-fe22-4b4d-85ca-69ed4df16837', '荅劉長卿蛇浦橋月下重送', '荅劉长卿蛇浦橋月下重送', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["月色今宵最明，庭閑夜久天清。","寂寞多年老宦，殷懃遠別深情。","溪臨修竹煙色，風落高梧雨聲。","耿耿相看不寐，遙聞曉柝山城。"]', '["月色今宵最明，庭闲夜久天清。","寂寞多年老宦，殷懃远別深情。","溪臨修竹煙色，风落高梧雨声。","耿耿相看不寐，遙闻晓柝山城。"]', '诗', 'shi', '', NULL, '荅劉長卿蛇浦橋月下重送 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f92cbe-8ae5-4323-b91d-0c9c52139fea', '發桐廬寄劉員外', '發桐廬寄劉員外', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["處處雲山無盡時，桐廬南望轉參差。","舟人莫道新安近，欲上潺湲行自遲。"]', '["处处云山無尽时，桐廬南望轉參差。","舟人莫道新安近，欲上潺湲行自遲。"]', '诗', 'shi', '', NULL, '發桐廬寄劉員外 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea7ca63-1262-4d0f-b8a3-5118cf831f28', '秋夜船行', '秋夜船行', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["扁舟時屬暝，月上有餘輝。","海燕秋還去，漁人夜不歸。","中流何寂寂，孤棹也依依。","一點前村火，誰家未掩扉。"]', '["扁舟时屬暝，月上有餘輝。","海燕秋還去，漁人夜不归。","中流何寂寂，孤棹也依依。","一点前村火，誰家未掩扉。"]', '诗', 'shi', '', NULL, '秋夜船行 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec7404c-2d83-4bea-ba67-d44ba4cfad06', '遊灞陵山', '游灞陵山', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["入山未盡意，勝跡聊獨尋。","方士去在昔，藥堂留至今。","四隅白雲閑，一路清溪深。","芳秀愜春目，高閑宜遠心。","潭分化丹水，路遶昇仙林。","此道人不悟，坐鳴松下琴。"]', '["入山未尽意，勝跡聊独尋。","方士去在昔，藥堂留至今。","四隅白云闲，一路清溪深。","芳秀愜春目，高闲宜远心。","潭分化丹水，路遶昇仙林。","此道人不悟，坐鳴松下琴。"]', '诗', 'shi', '', NULL, '遊灞陵山 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612c20bd-d582-4948-8258-314e3e0a04b1', '重送新安劉員外', '重送新安劉員外', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["秋江渺渺水空波，越客孤舟欲榜歌。","手折衰楊悲老大，故人零落已無多。"]', '["秋江渺渺水空波，越客孤舟欲榜歌。","手折衰楊悲老大，故人零落已無多。"]', '诗', 'shi', '', NULL, '重送新安劉員外 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e06f0aa-507d-45c1-869f-85399284ef49', '憶長安 五月', '憶长安 五月', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["憶長安，五月時，君王避暑華池。","進膳甘瓜朱李，續命芳蘭綵絲。","競處高明臺榭，槐陰柳色通逵。"]', '["憶长安，五月时，君王避暑华池。","進膳甘瓜朱李，續命芳蘭綵絲。","競处高明台榭，槐陰柳色通逵。"]', '诗', 'shi', '', NULL, '憶長安 五月 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa6c414-ec2a-4b89-b082-051414b719dc', '狀江南 季春', '狀江南 季春', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["江南季春天，蓴葉細如弦。","池邊草作逕，湖上葉如船。"]', '["江南季春天，蓴葉細如弦。","池邊草作逕，湖上葉如船。"]', '诗', 'shi', '', NULL, '狀江南 季春 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5856859c-215a-4d5c-87f2-e6cd19e2f699', '句', '句', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["五色驚綵鳳，千里象驄威。","三伏軒車動，堯心急諫官。","名通內籍貴，立近御牀寒。","波從少海息，雲自大風開。"]', '["五色驚綵鳳，千里象驄威。","三伏軒车动，堯心急諫官。","名通內籍貴，立近御牀寒。","波從少海息，云自大风开。"]', '诗', 'shi', '', NULL, '句 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ed153d-6ed7-4f28-abbc-4bbe8eb5d0e7', '琴歌', '琴歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["琴調秋些，胡風遶雪。","峽泉聲咽，佳人愁些。"]', '["琴調秋些，胡风遶雪。","峽泉声咽，佳人愁些。"]', '诗', 'shi', '', NULL, '琴歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('647c2191-13dc-4fde-9001-b5f9e53ff337', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["遐哉上古，生棄與柱。","句龍是生，乃有甫田。","惟彼甫田，有萬斯年。","開利之源，無乃塞源。","一廛亦官，百廛亦官。","嗇夫孔艱，浸兮暵兮，申有螽兮。","惟馨祀是患，豈止餒與寒。","嗇夫咨咨，䅎盛苗衰。","耕之耰之，襏襫鋤犂。","手胼足胝，水之蛭螾。","吮喋我肌，我姑自思。","胡不奮飛，東人利百。","西人利百，有匪我心。","胡爲不易，河水活活。","萬人逐末，俾爾之愉悅兮。"]', '["遐哉上古，生棄與柱。","句龙是生，乃有甫田。","惟彼甫田，有万斯年。","开利之源，無乃塞源。","一廛亦官，百廛亦官。","嗇夫孔艱，浸兮暵兮，申有螽兮。","惟馨祀是患，豈止餒與寒。","嗇夫咨咨，䅎盛苗衰。","耕之耰之，襏襫鋤犂。","手胼足胝，水之蛭螾。","吮喋我肌，我姑自思。","胡不奮飞，东人利百。","西人利百，有匪我心。","胡爲不易，河水活活。","万人逐末，俾爾之愉悅兮。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e62729-dddd-41b4-ad1f-47736c4468d5', '上古之什補亡訓傳十三章  一', '上古之什補亡訓傳十三章  一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["左車有慶，萬人猶病。","曷可去之，于黨孔盛。","敏爾之生，胡爲波迸。"]', '["左车有慶，万人猶病。","曷可去之，于黨孔盛。","敏爾之生，胡爲波迸。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章  一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28c99da-a74a-4707-b44d-0e6090c9ca81', '上古之什補亡訓傳十三章  二', '上古之什補亡訓傳十三章  二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["左車有赫，萬人毒螫。","曷可去之，于黨孔碩。","敏爾之生，胡爲草戚。"]', '["左车有赫，万人毒螫。","曷可去之，于黨孔碩。","敏爾之生，胡爲草戚。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章  二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84ef815-694d-4b41-beb8-0fb0f95b704c', '上古之什補亡訓傳十三章  一', '上古之什補亡訓傳十三章  一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["築城登登，于以作固。","咨爾寺兮，發郊外冢墓。","死而無知，猶或不可。","若其有知，惟上帝是愬。"]', '["築城登登，于以作固。","咨爾寺兮，發郊外冢墓。","死而無知，猶或不可。","若其有知，惟上帝是愬。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章  一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb009d9-0f2c-4d87-85ea-37c411abb9f8', '上古之什補亡訓傳十三章  二', '上古之什補亡訓傳十三章  二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["築城奕奕，于以固敵。","咨爾寺兮，發郊外冢甓。","死而無知，猶或不可。","若其有知，惟上帝是謫。"]', '["築城奕奕，于以固敵。","咨爾寺兮，發郊外冢甓。","死而無知，猶或不可。","若其有知，惟上帝是謫。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章  二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a79599-09f4-4c4e-b098-b3094974890c', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["持斧持斧，無翦我松柏兮。"]', '["持斧持斧，無翦我松柏兮。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f889d018-d34f-4ccb-bcb8-25a8bfd1e95f', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["十月之郊，羣木肇生。","陽潛地中，舒達句萌。","曀其蔚兮，不可以遊息。","乃熂蒺藜，乃夷荆棘。","乃繇彼曲直，匠氏度思。","登斧以時，澤梁蓁蓁。","無或夭枝，有巨根蔕。","生混茫際，呼吸羣籟。","萬人揮斤，坎坎有厲。","陸遷水濟，百力殫弊。","審方面勢，姑博其製。","作爲公室，公室既成。","禦燥濕風日，棟之斯厚。","榱之斯密，如翼于飛。","如鱗櫛比，繚以周墉。","墄以崇階，俯而望之。","矗與雲齊，嘯砆碔砆。","藻井旋題，丹素之燝兮。","椒挂之馥兮，高閣高閣。","珠綴結絡，金鋪爛若。","不集于鳥雀，繪事告畢。","賓筵秩秩，乃命旨酒琴瑟。","琴瑟在堂，莫不靜謐。","周環掩闢，仰不漏日。","冬日嚴凝，言納其陽。","和風載昇，夏日鬱蒸。","言用于陰，涼封颯興。","有匪君子，自賢不已。","乃夢乘舟，乃夢乘車。","夢人占之，更爽其居。","炎炎則移，皎皎則虧。","木實之繁兮，明年息枝。","爰處若思，胡寧不爾思。"]', '["十月之郊，羣木肇生。","陽潛地中，舒達句萌。","曀其蔚兮，不可以游息。","乃熂蒺藜，乃夷荆棘。","乃繇彼曲直，匠氏度思。","登斧以时，澤梁蓁蓁。","無或夭枝，有巨根蔕。","生混茫際，呼吸羣籟。","万人揮斤，坎坎有厲。","陸遷水濟，百力殫弊。","審方面勢，姑博其製。","作爲公室，公室既成。","禦燥濕风日，棟之斯厚。","榱之斯密，如翼于飞。","如鱗櫛比，繚以周墉。","墄以崇階，俯而望之。","矗與云齊，嘯砆碔砆。","藻井旋題，丹素之燝兮。","椒挂之馥兮，高閣高閣。","珠綴結絡，金鋪爛若。","不集于鸟雀，繪事告畢。","賓筵秩秩，乃命旨酒琴瑟。","琴瑟在堂，莫不静謐。","周环掩闢，仰不漏日。","冬日嚴凝，言納其陽。","和风載昇，夏日鬱蒸。","言用于陰，涼封颯兴。","有匪君子，自賢不已。","乃梦乘舟，乃梦乘车。","梦人占之，更爽其居。","炎炎則移，皎皎則虧。","木實之繁兮，明年息枝。","爰处若思，胡寧不爾思。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31774c1e-3701-4961-9566-af53d6b8264f', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["燕燕于巢，綴葺維戊。","甲兮乙兮，不宜有謬。","飛龍在天，雲掩于斗。","曷日于雨，乃曰庚午。","彼日之差，亦孔斯醜。","昔在羲和，湎淫不修。","我筮我龜，莫我告繇。","胤廼征之，彝倫九疇。","君子授律，是禡是禷。","三五不備，罔克攸遂。","惠此蒸人，毋廢爾事。","爾莫我從，維來者是冀。"]', '["燕燕于巢，綴葺維戊。","甲兮乙兮，不宜有謬。","飞龙在天，云掩于斗。","曷日于雨，乃曰庚午。","彼日之差，亦孔斯醜。","昔在羲和，湎淫不修。","我筮我龟，莫我告繇。","胤廼征之，彝倫九疇。","君子授律，是禡是禷。","三五不備，罔克攸遂。","惠此蒸人，毋廢爾事。","爾莫我從，維来者是冀。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28078456-ebd0-44cb-845f-6a78150becc3', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["蘇方之赤，在胡之舶。","其利乃博，我土曠兮。","我居闐兮，我衣不白兮。","朱紫爛兮，傳瑞曄兮，相唐虞之維百兮。"]', '["蘇方之赤，在胡之舶。","其利乃博，我土曠兮。","我居闐兮，我衣不白兮。","朱紫爛兮，傳瑞曄兮，相唐虞之維百兮。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3a559e-a1aa-4867-b628-20cba5767840', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["陵霜之華，我心憂嗟。","陰之勝矣，而陽不加。","坱軋陶鈞，乃帝乃神。","乃舒乃屯，烈烈嚴秋。","熙熙陽春，職生有倫。","今華發非其辰，辰屬東方之仁。","遐想三五，黃帝登雲。","堯年百餘，二儀分位。","六氣不渝，二景如璧，五星如珠。"]', '["陵霜之华，我心憂嗟。","陰之勝矣，而陽不加。","坱軋陶鈞，乃帝乃神。","乃舒乃屯，烈烈嚴秋。","熙熙陽春，職生有倫。","今华發非其辰，辰屬东方之仁。","遐想三五，黄帝登云。","堯年百餘，二儀分位。","六氣不渝，二景如璧，五星如珠。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c029b7a-1423-4dd5-9c4d-8ed194e455b5', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["囝生閩方，閩吏得之。","乃絕其陽，爲臧爲獲。","致金滿屋，爲髠爲鉗。","如視草木，天道無知。","我罹其毒，神道無知。","彼受其福，郎罷別囝。","吾悔生汝，及汝既生。","人勸不舉，不從人言。","果獲是苦，囝別郎罷。","心催血下，隔地絕天。","及至黃泉，不得在郎罷前。"]', '["囝生閩方，閩吏得之。","乃絕其陽，爲臧爲獲。","致金满屋，爲髠爲鉗。","如視草木，天道無知。","我罹其毒，神道無知。","彼受其福，郎罷別囝。","吾悔生汝，及汝既生。","人勸不舉，不從人言。","果獲是苦，囝別郎罷。","心催血下，隔地絕天。","及至黄泉，不得在郎罷前。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330852e0-cfb5-4d43-90d6-1ee236720b54', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["我行自東，山海其空。","旅棘有叢，我行自西。","壘與雲齊，雨雪淒淒。","我行自南，烈火滿林。","日中無禽，霧雨淫淫。","我行自北，燭龍寡色。"]', '["我行自东，山海其空。","旅棘有叢，我行自西。","壘與云齊，雨雪淒淒。","我行自南，烈火满林。","日中無禽，霧雨淫淫。","我行自北，燭龙寡色。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420ff7c9-d7da-47ea-bef9-131988809cc1', '上古之什補亡訓傳十三章', '上古之什補亡訓傳十三章', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["採採者蠟，于泉谷兮。","煌煌中堂，烈華燭兮。","新歌善舞，弦柱促兮。","荒巖之人，自取其毒兮。"]', '["採採者蠟，于泉谷兮。","煌煌中堂，烈华燭兮。","新歌善舞，弦柱促兮。","荒巖之人，自取其毒兮。"]', '诗', 'shi', '', NULL, '上古之什補亡訓傳十三章 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b544d20a-db4e-4f36-8f67-99edb5cab027', '棄婦詞', '棄婦词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["古人雖棄婦，棄婦有歸處。","今日妾辭君，辭君欲何去。","本家零落盡，慟哭來時路。","憶昔未嫁君，聞君甚周旋。","及與同結髮，值君適幽燕。","孤魂託飛鳥，兩眼如流泉。","流泉咽不燥，萬里關山道。","及至見君歸，君歸妾已老。","物情棄衰歇，新寵方妍好。","拭淚出故房，傷心劇秋草。","妾以憔悴捐，羞將舊物遠。","餘生欲有寄，誰肯相留連。","空牀對虛牖，不覺塵埃厚。","寒水芙蓉花，秋風墮楊柳。","記得初嫁君，小姑始扶牀。","今日君棄妾，小姑如妾長。","回頭語小姑，莫嫁如兄夫。"]', '["古人雖棄婦，棄婦有归处。","今日妾辞君，辞君欲何去。","本家零落尽，慟哭来时路。","憶昔未嫁君，闻君甚周旋。","及與同結髮，值君適幽燕。","孤魂託飞鸟，兩眼如流泉。","流泉咽不燥，万里关山道。","及至见君归，君归妾已老。","物情棄衰歇，新寵方妍好。","拭泪出故房，傷心劇秋草。","妾以憔悴捐，羞將旧物远。","餘生欲有寄，誰肯相留連。","空牀对虛牖，不覺塵埃厚。","寒水芙蓉花，秋风墮楊柳。","記得初嫁君，小姑始扶牀。","今日君棄妾，小姑如妾长。","回头語小姑，莫嫁如兄夫。"]', '诗', 'shi', '', NULL, '棄婦詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87589e47-69eb-4b30-8204-5678cb0c8636', '遊子吟', '游子吟', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故櫪思疲馬，故窠思迷禽。","浮雲蔽我鄉，躑躅遊子吟。","遊子悲久滯，浮雲鬱東岑。","客堂無絲桐，落葉如秋霖。","艱哉遠遊子，所以悲滯淫。","一爲浮雲詞，憤塞誰能禁。","馳歸百年內，唯願展所欽。","胡爲不歸歟，坐使年病侵。","未老霜遶鬢，非狂火燒心。","太行何難哉，北斗不可斟。","夜靜星河出，耿耿辰與參。","佳人敻青天，尺素重於金。","泬寥羣動異，眇默諸境森。","苔衣上閑階，蟋蟋催寒碪。","立身計幾悞，道險無容針。","三年不還家，萬里遺錦衾。","夢魂無重阻，離憂罔古今。","胡爲不歸歟，辜負匣中琴。","腰下是何物，牽纏曠登尋。","朝與名山期，夕宿楚水陰。","楚水殊演漾，名山窅嶇嶔。","客從洞庭來，婉孌瀟湘深。","橘柚在南國，鴻雁遺秋音。","下有碧草洲，上有青橘林。","引燭窺洞穴，凌波睥天琛。","蒲荷影參差，鳧鶴雛淋涔。","浩歌惜芳杜，散髮輕華簪。","胡爲不歸歟，淚下沾衣襟。","鳶飛戾宵漢，螻蟻制鱣鱏。","赫赫大聖朝，日月光照臨。","聖主雖啓迪，奇人分湮沈。","層城登雲韶，王府鏘球琳。","鹿鳴志豐草，況復虞人箴。"]', '["故櫪思疲马，故窠思迷禽。","浮云蔽我乡，躑躅游子吟。","游子悲久滯，浮云鬱东岑。","客堂無絲桐，落葉如秋霖。","艱哉远游子，所以悲滯淫。","一爲浮云词，憤塞誰能禁。","驰归百年內，唯願展所欽。","胡爲不归歟，坐使年病侵。","未老霜遶鬢，非狂火燒心。","太行何难哉，北斗不可斟。","夜静星河出，耿耿辰與參。","佳人敻青天，尺素重於金。","泬寥羣动異，眇默諸境森。","苔衣上闲階，蟋蟋催寒碪。","立身計幾悞，道險無容針。","三年不還家，万里遺錦衾。","梦魂無重阻，離憂罔古今。","胡爲不归歟，辜負匣中琴。","腰下是何物，牽纏曠登尋。","朝與名山期，夕宿楚水陰。","楚水殊演漾，名山窅嶇嶔。","客從洞庭来，婉孌瀟湘深。","橘柚在南国，鴻雁遺秋音。","下有碧草洲，上有青橘林。","引燭窺洞穴，凌波睥天琛。","蒲荷影參差，鳧鹤雛淋涔。","浩歌惜芳杜，散髮轻华簪。","胡爲不归歟，泪下沾衣襟。","鳶飞戾宵漢，螻蟻制鱣鱏。","赫赫大聖朝，日月光照臨。","聖主雖啓迪，奇人分湮沈。","層城登云韶，王府鏘球琳。","鹿鳴志豐草，況复虞人箴。"]', '诗', 'shi', '', NULL, '遊子吟 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ffcb2d-3218-40d2-b123-c56fc0da3a6f', '擬古三首 一', '擬古三首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["龍劍昔藏影，送雄留其雌。","人生阻歡會，神物亦別離。","碧樹感秋落，佳人無還期。","夜琴爲君咽，浮雲爲君滋。","愛而傷不見，星漢徒參差。"]', '["龙劍昔藏影，送雄留其雌。","人生阻歡會，神物亦別離。","碧樹感秋落，佳人無還期。","夜琴爲君咽，浮云爲君滋。","愛而傷不见，星漢徒參差。"]', '诗', 'shi', '', NULL, '擬古三首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3585a5ca-2533-4780-aa25-d7a7484f4d49', '擬古三首 二', '擬古三首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["幽居盼天造，胡息運行機。","春葩妍既榮，秋葉瘁以飛。","滔滔川之逝，日沒月光輝。","所貴法乾健，于道悟入微。","任彼聲勢徒，得志方誇毗。"]', '["幽居盼天造，胡息運行機。","春葩妍既榮，秋葉瘁以飞。","滔滔川之逝，日沒月光輝。","所貴法乾健，于道悟入微。","任彼声勢徒，得志方誇毗。"]', '诗', 'shi', '', NULL, '擬古三首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3255894f-5d4c-4452-8408-b183d6e48ed5', '擬古三首 三', '擬古三首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["浮生果何慕，老去羨介推。","陶令何足錄，彭澤歸已遲。","空負漉酒巾，乞食形諸詩。","吾惟抱貞素，悠悠白雲期。"]', '["浮生果何慕，老去羨介推。","陶令何足錄，彭澤归已遲。","空負漉酒巾，乞食形諸诗。","吾惟抱貞素，悠悠白云期。"]', '诗', 'shi', '', NULL, '擬古三首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d14ca80-d4d1-4aa7-8275-975cd901be7e', '傷子', '傷子', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["老夫哭愛子，日暮千行血。","聲逐斷猿悲，跡隨飛鳥滅。","老夫已七十，不作多時別。"]', '["老夫哭愛子，日暮千行血。","声逐斷猿悲，跡隨飞鸟滅。","老夫已七十，不作多时別。"]', '诗', 'shi', '', NULL, '傷子 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144809ea-be89-4148-aa51-1cf4b44b1895', '春遊曲 一', '春游曲 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["遊童蘇合帶，倡女蒲葵扇。","初日映城時，相思忽相見。","褰裳踏露草，理鬢回花面。","薄暮不同歸，留情此芳甸。"]', '["游童蘇合带，倡女蒲葵扇。","初日映城时，相思忽相见。","褰裳踏露草，理鬢回花面。","薄暮不同归，留情此芳甸。"]', '诗', 'shi', '', NULL, '春遊曲 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17872b06-a000-40e2-b592-e635ffe04c59', '春遊曲 二', '春游曲 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["柘彈連錢馬，銀鉤妥墮鬟。","採桑春陌上，踏草夕陽間。","意合詞先露，心誠貌却閑。","明朝若相憶，雲雨出巫山。"]', '["柘彈連錢马，銀鉤妥墮鬟。","採桑春陌上，踏草夕陽间。","意合词先露，心誠貌却闲。","明朝若相憶，云雨出巫山。"]', '诗', 'shi', '', NULL, '春遊曲 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d752bcd-9001-440a-8cfe-8e681b2c4cd0', '從軍行二首 一', '從軍行二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["弭節結徒侶，速征赴龍城。","單于近突圍，烽燧屢夜驚。","長弓挽滿月，劍華霜雪明。","遠道百草殞，峭覺寒風生。","風寒欲砭肌，爭奈裘襖輕。","回首家不見，候雁空中鳴。","笳奏遝以哀，肅肅趣嚴程。","寄語塞外胡，擁騎休橫行。"]', '["弭節結徒侶，速征赴龙城。","單于近突圍，烽燧屢夜驚。","长弓挽满月，劍华霜雪明。","远道百草殞，峭覺寒风生。","风寒欲砭肌，爭奈裘襖轻。","回首家不见，候雁空中鳴。","笳奏遝以哀，肅肅趣嚴程。","寄語塞外胡，擁騎休橫行。"]', '诗', 'shi', '', NULL, '從軍行二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0387e52b-4a91-4bfb-b7b8-5f81e6c73d20', '從軍行二首 二', '從軍行二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["少年膽氣麁，好勇萬人敵。","仗劍出門去，三邊正艱厄。","怒目時一呼，萬騎皆辟易。","殺人蓬麻輕，走馬汗血滴。","醜虜何足清，天山坐寧謐。","不有封侯相，徒負幽幷客。"]', '["少年膽氣麁，好勇万人敵。","仗劍出门去，三邊正艱厄。","怒目时一呼，万騎皆辟易。","殺人蓬麻轻，走马汗血滴。","醜虜何足清，天山坐寧謐。","不有封侯相，徒負幽幷客。"]', '诗', 'shi', '', NULL, '從軍行二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc641892-8566-4ab8-93f1-e17dacc6aa88', '塞上曲', '塞上曲', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["黠虜初南下，塵飛塞北境。","漢將懷不平，讐擾當遠屏。","金革臥不暖，起舞霜月冷。","點軍三十千，部伍嚴以整。","酣戰祈成功，于焉罷邊釁。"]', '["黠虜初南下，塵飞塞北境。","漢將懷不平，讐擾當远屏。","金革臥不暖，起舞霜月冷。","点軍三十千，部伍嚴以整。","酣戰祈成功，于焉罷邊釁。"]', '诗', 'shi', '', NULL, '塞上曲 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea740956-e3f3-44a4-8a42-b51847344bfd', '弋陽溪中望仙人城', '弋陽溪中望仙人城', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["何草乏靈姿，無山不孤絕。","我行雖云蹇，偶勝聊換節。","上界浮中流，光響洞明滅。","晚禽曝霜羽，寒魚依石髮。","自有無還心，隔波望松雪。"]', '["何草乏靈姿，無山不孤絕。","我行雖云蹇，偶勝聊換節。","上界浮中流，光响洞明滅。","晚禽曝霜羽，寒鱼依石髮。","自有無還心，隔波望松雪。"]', '诗', 'shi', '', NULL, '弋陽溪中望仙人城 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f0de7a-1782-4161-a5f6-1ced4edb4cb2', '嚴公釣臺作', '嚴公釣台作', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["靈芝產遐方，威鳳家重宵。","嚴生何耿潔，託志肩夷巢。","漢后雖則貴，子陵不知高。","糠粃當世道，長揖夔龍朝。","掃門彼何人，升降不同朝。","捨舟遂長往，山谷多清飆。"]', '["靈芝產遐方，威鳳家重宵。","嚴生何耿潔，託志肩夷巢。","漢后雖則貴，子陵不知高。","糠粃當世道，长揖夔龙朝。","掃门彼何人，升降不同朝。","捨舟遂长往，山谷多清飆。"]', '诗', 'shi', '', NULL, '嚴公釣臺作 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169eb18c-5a15-4927-bd2a-96a622460b7e', '蕭寺偃松', '蕭寺偃松', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["淒淒百卉病，亭亭雙松逈。","直上古寺深，橫拂秋殿冷。","輕響入龜目，片陰栖鶴頂。","山中多好樹，可憐無比並。"]', '["淒淒百卉病，亭亭雙松逈。","直上古寺深，橫拂秋殿冷。","轻响入龟目，片陰栖鹤頂。","山中多好樹，可怜無比並。"]', '诗', 'shi', '', NULL, '蕭寺偃松 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5256a1a-2a7b-480c-a475-f42f705f7341', '獨遊青龍寺', '独游青龙寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["春風入香剎，暇日獨游衍。","曠然蓮花臺，作禮月光面。","乘茲第八識，出彼超二見。","擺落區中緣，無邊廣弘願。","長廊朝雨畢，古木時禽囀。","積翠曖遙原，雜英紛似霰。","鳳城騰日窟，龍首橫天堰。","蟻步避危階，蠅飛響深殿。","大通智勝佛，幾刦道場現。"]', '["春风入香剎，暇日独游衍。","曠然蓮花台，作禮月光面。","乘茲第八識，出彼超二见。","擺落區中緣，無邊廣弘願。","长廊朝雨畢，古木时禽囀。","積翠曖遙原，杂英紛似霰。","鳳城腾日窟，龙首橫天堰。","蟻步避危階，蠅飞响深殿。","大通智勝佛，幾刦道場現。"]', '诗', 'shi', '', NULL, '獨遊青龍寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d56217-7555-4a85-99fd-2ef265de9b8d', '初秋蓮塘歸', '初秋蓮塘归', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["秋光淨無跡，蓮消錦雲紅。","只有溪上山，還識揚舲翁。","如何白蘋花，幽渚笑涼風。"]', '["秋光淨無跡，蓮消錦云紅。","只有溪上山，還識揚舲翁。","如何白蘋花，幽渚笑涼风。"]', '诗', 'shi', '', NULL, '初秋蓮塘歸 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75b38bd-659f-4d46-9c7f-f4213be5f33f', '從江西至彭蠡入浙西淮南界道中寄齊相公', '從江西至彭蠡入浙西淮南界道中寄齊相公', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["大賢舊丞相，作鎮江山雄。","自鎮江山來，何人得如公。","處士待徐孺，仙人期葛洪。","一身控上遊，八郡趨下風。","比屋除畏溺，林塘曳煙虹。","生人罷虔劉，井稅均且充。","大府肅無事，歡然接悲翁。","心清百丈泉，目送孤飛鴻。","數年鄱陽掾，抱責栖微躬。","首陽及汨羅，無乃褊其衷。","楊朱幷阮籍，未免哀途窮。","四賢雖得仁，此怨何怱怱。","老氏齊寵辱，於陵一窮通。","本師留度門，平等冤親同。","能依二諦法，了達三輪空。","真境靡方所，出離內外中。","無邊盡未來，定惠雙修功。","蹇步慙寸進，餙裝隨轉蓬。","朝行楚水陰，夕宿吳洲東。","吳洲復白雲，楚水飄丹楓。","晚霞燒廻潮，千里光曈曈。","蓂開海上影，桂吐淮南叢。","何當翼明庭，草木生春融。"]', '["大賢旧丞相，作鎮江山雄。","自鎮江山来，何人得如公。","处士待徐孺，仙人期葛洪。","一身控上游，八郡趨下风。","比屋除畏溺，林塘曳煙虹。","生人罷虔劉，井稅均且充。","大府肅無事，歡然接悲翁。","心清百丈泉，目送孤飞鴻。","數年鄱陽掾，抱責栖微躬。","首陽及汨羅，無乃褊其衷。","楊朱幷阮籍，未免哀途窮。","四賢雖得仁，此怨何怱怱。","老氏齊寵辱，於陵一窮通。","本師留度门，平等冤親同。","能依二諦法，了達三輪空。","真境靡方所，出離內外中。","無邊尽未来，定惠雙修功。","蹇步慙寸進，餙裝隨轉蓬。","朝行楚水陰，夕宿吳洲东。","吳洲复白云，楚水飄丹楓。","晚霞燒廻潮，千里光曈曈。","蓂开海上影，桂吐淮南叢。","何當翼明庭，草木生春融。"]', '诗', 'shi', '', NULL, '從江西至彭蠡入浙西淮南界道中寄齊相公 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e58f1b4-21c8-4f73-a641-cc0366ab1efd', '寄上兵部韓侍郎奉呈李戶部盧刑部杜三侍郎', '寄上兵部韓侍郎奉呈李戶部盧刑部杜三侍郎', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["道路五千里，門闌三十年。","當時攜手人，今日無半全。","詠題官舍內，賦韻僧房前。","公登略彴橋，況榜龍{舟卬}船。","遠寺吐朱閣，春潮浮綠煙。","鵷鴻翔鄧林，沙鴇飛吳田。","諸子紛出祖，中宵久留連。","坐客三千人，皆稱主人賢。","國士分如此，家臣亦依然。","身在薜蘿中，頭刺文案邊。","故吏已重疊，門生從聯翩。","得罪爲何名，無階問皇天。","出門多岐路，命駕無由緣。","伏承諸侍郎，顧念猶迍邅。","聖代逢三宥，營魂空九遷。"]', '["道路五千里，门闌三十年。","當时携手人，今日無半全。","詠題官舍內，賦韻僧房前。","公登略彴橋，況榜龙{舟卬}船。","远寺吐朱閣，春潮浮綠煙。","鵷鴻翔鄧林，沙鴇飞吳田。","諸子紛出祖，中宵久留連。","坐客三千人，皆稱主人賢。","国士分如此，家臣亦依然。","身在薜蘿中，头刺文案邊。","故吏已重叠，门生從聯翩。","得罪爲何名，無階问皇天。","出门多岐路，命駕無由緣。","伏承諸侍郎，顧念猶迍邅。","聖代逢三宥，營魂空九遷。"]', '诗', 'shi', '', NULL, '寄上兵部韓侍郎奉呈李戶部盧刑部杜三侍郎 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fea7675-c16d-4354-8241-758c96ced6f7', '長安竇明府後亭', '长安竇明府後亭', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君爲長安令，我美長安政。","五日一朝天，南山對明鏡。","鳥飛青苔院，水木相輝映。","客至南雲鄉，絲桐展歌詠。","吏人何蕭蕭，終歲無喧競。","欲識明府賢，邑中多百姓。"]', '["君爲长安令，我美长安政。","五日一朝天，南山对明镜。","鸟飞青苔院，水木相輝映。","客至南云乡，絲桐展歌詠。","吏人何蕭蕭，終歲無喧競。","欲識明府賢，邑中多百姓。"]', '诗', 'shi', '', NULL, '長安竇明府後亭 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9195a1-6b5d-4054-b785-21350c64f373', '謝王郎中見贈琴鶴', '謝王郎中见贈琴鹤', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["此琴等焦尾，此鶴方胎生。","赴節何徘徊，理感物自幷。","獨立江海上，一彈天地清。","朱弦動瑤華，白羽飄玉京。","因想羨門輩，眇然四體輕。","子喬翔鄧林，王母遊層城。","忽如啓靈署，鸞鳳相和鳴。","何由玉女牀，去食琅玕英。"]', '["此琴等焦尾，此鹤方胎生。","赴節何徘徊，理感物自幷。","独立江海上，一彈天地清。","朱弦动瑤华，白羽飄玉京。","因想羨门輩，眇然四體轻。","子喬翔鄧林，王母游層城。","忽如啓靈署，鸾鳳相和鳴。","何由玉女牀，去食琅玕英。"]', '诗', 'shi', '', NULL, '謝王郎中見贈琴鶴 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('790414b6-6832-4006-a123-580c7950b198', '和翰林吳舍人兄弟西齋', '和翰林吳舍人兄弟西斋', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君家誠易知，易知復難同。","新裁尺一詔，早入明光宮。","西齋何其高，上與星漢通。","永懷洞庭石，春色相玲瓏。","久懷巴峽泉，夜落君絲桐。","信是怡神所，迢迢蔑華嵩。","鳥飛晴雲滅，疊嶂盤虛空。","君家誠易知，易知意難窮。"]', '["君家誠易知，易知复难同。","新裁尺一詔，早入明光宮。","西斋何其高，上與星漢通。","永懷洞庭石，春色相玲瓏。","久懷巴峽泉，夜落君絲桐。","信是怡神所，迢迢蔑华嵩。","鸟飞晴云滅，叠嶂盤虛空。","君家誠易知，易知意难窮。"]', '诗', 'shi', '', NULL, '和翰林吳舍人兄弟西齋 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d613d731-0abc-41a1-87dd-aecd74931800', '望初月簡于吏部', '望初月簡于吏部', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["泬寥中秋夜，坐見如鉤月。","始從西南升，又欲西南沒。","全移河上影，暫透林間缺。","縱待三五時，終爲千里別。"]', '["泬寥中秋夜，坐见如鉤月。","始從西南升，又欲西南沒。","全移河上影，暫透林间缺。","縱待三五时，終爲千里別。"]', '诗', 'shi', '', NULL, '望初月簡于吏部 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895967e5-676c-4238-a5a5-124e4260f76c', '上湖至破山贈文周蕭元植', '上湖至破山贈文周蕭元植', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["一別二十年，依依過故轍。","湖上非往態，夢想頻虛結。","二子伴我行，我行感徂節。","後人應不識，前事寒泉咽。","一別二十年，人堪幾回別。"]', '["一別二十年，依依過故轍。","湖上非往態，梦想頻虛結。","二子伴我行，我行感徂節。","後人應不識，前事寒泉咽。","一別二十年，人堪幾回別。"]', '诗', 'shi', '', NULL, '上湖至破山贈文周蕭元植 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29818c31-5982-4c9f-8f9a-a227a04ca579', '酬信州劉侍郎兄', '酬信州劉侍郎兄', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["劉兄本知命，屈伸不介懷。","南州管靈山，可惜曠土棲。","樵隱同一徑，竹樹薄西齋。","鳥陵嶂合杳，月配波徘徊。","薄宦修禮數，長景謝譚諧。","願爲南州民，輸稅事鉏犁。","胡爲走不止，風雨驚邅迴。"]', '["劉兄本知命，屈伸不介懷。","南州管靈山，可惜曠土棲。","樵隐同一徑，竹樹薄西斋。","鸟陵嶂合杳，月配波徘徊。","薄宦修禮數，长景謝譚諧。","願爲南州民，輸稅事鉏犁。","胡爲走不止，风雨驚邅迴。"]', '诗', 'shi', '', NULL, '酬信州劉侍郎兄 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c248881e-31d3-4a8a-aa4c-ef5591f27153', '奉酬劉侍郎', '奉酬劉侍郎', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["幾迴新秋影，壁滿蟾又缺。","鏡破似傾臺，輪斜同覆轍。","雖分上林桂，還照滄洲雪。","暫伴顦顇人，歸華耿不滅。"]', '["幾迴新秋影，壁满蟾又缺。","镜破似傾台，輪斜同覆轍。","雖分上林桂，還照滄洲雪。","暫伴顦顇人，归华耿不滅。"]', '诗', 'shi', '', NULL, '奉酬劉侍郎 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71edeeee-167f-4f20-8ed2-cb4571d54813', '酬本部韋左司', '酬本部韋左司', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["好鳥依佳樹，飛雨灑高城。","況與二三子，列坐分兩楹。","文雅一何盛，林塘含餘清。","府君未歸朝，遊子不待晴。","白雲帝城遠，滄江楓葉鳴。","却略欲一言，零淚和酒傾。","寸心久摧折，別離重骨驚。","安得凌風翰，肅肅賓天京。"]', '["好鸟依佳樹，飞雨灑高城。","況與二三子，列坐分兩楹。","文雅一何盛，林塘含餘清。","府君未归朝，游子不待晴。","白云帝城远，滄江楓葉鳴。","却略欲一言，零泪和酒傾。","寸心久摧折，別離重骨驚。","安得凌风翰，肅肅賓天京。"]', '诗', 'shi', '', NULL, '酬本部韋左司 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6534e63d-db2d-4c05-b47d-3a54352843b5', '酬房杭州', '酬房杭州', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["郡樓何其曠，亭亭廣而深。","故人牧餘杭，留我披胸衿。","滿篋閱新作，璧玉誕清音。","流水入洞天，窅豁欲淩臨。","闢險延北阜，薙道陟南岑。","朝從山寺還，醒醉動笑吟。","荷花十餘里，月色攢湖林。","父老惜使君，却欲速華簪。"]', '["郡楼何其曠，亭亭廣而深。","故人牧餘杭，留我披胸衿。","满篋閱新作，璧玉誕清音。","流水入洞天，窅豁欲淩臨。","闢險延北阜，薙道陟南岑。","朝從山寺還，醒醉动笑吟。","荷花十餘里，月色攢湖林。","父老惜使君，却欲速华簪。"]', '诗', 'shi', '', NULL, '酬房杭州 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15145fb4-20e1-44db-acf9-814a2d976452', '酬漳州張九使君', '酬漳州張九使君', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故人窮越徼，狂生起悲愁。","山海萬里別，草木十年秋。","鞭馬廣陵橋，出祖張漳州。","促膝墮簪珥，闢幌戛琳球。","短題自茲簡，華篇詎能酬。","無階承明庭，高步相追遊。","南方榮桂枝，淩冬捨溫裘。","猿唫郡齋中，龍靜檀欒流。","薜鹿莫徭洞，網魚盧亭洲。","心安處處安，處處思遐陬。"]', '["故人窮越徼，狂生起悲愁。","山海万里別，草木十年秋。","鞭马廣陵橋，出祖張漳州。","促膝墮簪珥，闢幌戛琳球。","短題自茲簡，华篇詎能酬。","無階承明庭，高步相追游。","南方榮桂枝，淩冬捨溫裘。","猿唫郡斋中，龙静檀欒流。","薜鹿莫徭洞，網鱼盧亭洲。","心安处处安，处处思遐陬。"]', '诗', 'shi', '', NULL, '酬漳州張九使君 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d57a82-baf7-4776-854e-b99e5319ae87', '在滁苦雨歸桃花崦傷親友略盡', '在滁苦雨归桃花崦傷親友略尽', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["廢棄忝殘生，後來亦先夭。","詩人感風雨，長夜何時曉。","去國宦情無，近鄉歸夢少。","庇身絕中授，甘靜忘外擾。","麗景變重陰，洞山空木表。","靈潮若可通，寄謝西飛鳥。"]', '["廢棄忝殘生，後来亦先夭。","诗人感风雨，长夜何时晓。","去国宦情無，近乡归梦少。","庇身絕中授，甘静忘外擾。","丽景变重陰，洞山空木表。","靈潮若可通，寄謝西飞鸟。"]', '诗', 'shi', '', NULL, '在滁苦雨歸桃花崦傷親友略盡 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507e9e38-02df-4eb1-a631-f001b909dcea', '苦雨', '苦雨', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["朝與佳人期，碧樹生紅蕚。","暮與佳人期，飛雨灑清閣。","佳人窅何許，中夜心寂寞。","試憶花正開，復驚葉初落。","行騎飛泉鹿，臥聽雙海鶴。","嘉願有所從，安得處其薄。"]', '["朝與佳人期，碧樹生紅蕚。","暮與佳人期，飞雨灑清閣。","佳人窅何許，中夜心寂寞。","試憶花正开，复驚葉初落。","行騎飞泉鹿，臥听雙海鹤。","嘉願有所從，安得处其薄。"]', '诗', 'shi', '', NULL, '苦雨 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38427d15-8d28-4ebb-b737-4d7a075f9b03', '贈別崔十三長官', '贈別崔十三长官', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["真玉燒不熱，寶劍拗不折。","欲別崔俠心，崔俠心如鐵。","復如金剛鎖，無有功不徹。","仍於直道中，行事不詆訐。","崔俠兩兄弟，垂範繼芳烈。","相識三十年，致書字不滅。","我來宣城郡，飲水仰清潔。","藹藹北阜松，峩峩南山雪。","顧生歸山去，知作幾年別。"]', '["真玉燒不熱，寶劍拗不折。","欲別崔俠心，崔俠心如鐵。","复如金剛鎖，無有功不徹。","仍於直道中，行事不詆訐。","崔俠兩兄弟，垂範繼芳烈。","相識三十年，致书字不滅。","我来宣城郡，饮水仰清潔。","藹藹北阜松，峩峩南山雪。","顧生归山去，知作幾年別。"]', '诗', 'shi', '', NULL, '贈別崔十三長官 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17e0ed9-da49-450a-9913-673d54476327', '哭從兄萇', '哭從兄萇', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["洞庭違鄂渚，嫋嫋秋風時。","何人不客遊，獨與帝子期。","黃鵠鎩飛翅，青雲歎沈姿。","身終一騎曹，高蓋者爲誰。","從駕至梁漢，金根復京師。","皇恩溢九垠，不記屠沽兒。","立身有高節，滿卷多好詩。","赫赫承明庭，羣公默無詞。","草木正搖落，哭兄鄱水湄。","共居雲陽里，轗軻多別離。","人生倏忽間，旅襯飄若遺。","稚子新學拜，枯楊生一枝。","人生倏忽間，精爽無不之。","舊國數千里，家人由未知。","人生倏忽間，安用才士爲。"]', '["洞庭違鄂渚，嫋嫋秋风时。","何人不客游，独與帝子期。","黄鵠鎩飞翅，青云歎沈姿。","身終一騎曹，高蓋者爲誰。","從駕至梁漢，金根复京師。","皇恩溢九垠，不記屠沽兒。","立身有高節，满卷多好诗。","赫赫承明庭，羣公默無词。","草木正搖落，哭兄鄱水湄。","共居云陽里，轗軻多別離。","人生倏忽间，旅襯飄若遺。","稚子新学拜，枯楊生一枝。","人生倏忽间，精爽無不之。","旧国數千里，家人由未知。","人生倏忽间，安用才士爲。"]', '诗', 'shi', '', NULL, '哭從兄萇 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0dd3eb4-28fd-495a-bf8e-eb8f65141e0a', '華山西岡遊贈隱玄叟', '华山西岡游贈隐玄叟', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["羣峰鬱初霽，潑黛若鬟沐。","失風鼓唅呀，搖撼千灌木。","木葉微墮黃，石泉淨停綠。","危磴蘿薜牽，逈步入幽谷。","我心寄青霞，世事慚蒼鹿。","遂令巢許輩，于焉謝塵俗。","想是悠悠雲，可契去留躅。"]', '["羣峰鬱初霽，潑黛若鬟沐。","失风鼓唅呀，搖撼千灌木。","木葉微墮黄，石泉淨停綠。","危磴蘿薜牽，逈步入幽谷。","我心寄青霞，世事慚蒼鹿。","遂令巢許輩，于焉謝塵俗。","想是悠悠云，可契去留躅。"]', '诗', 'shi', '', NULL, '華山西岡遊贈隱玄叟 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc52501e-3598-4ebf-bba8-7bf0c3a9a172', '歸陽蕭寺有丁行者能修無生忍擔水施僧況歸命稽首作詩', '归陽蕭寺有丁行者能修無生忍擔水施僧況归命稽首作诗', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["化佛示持帚，仲尼稱執鞭。","列生御風歸，飼豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，長綬趨遙泉。","開士行何苦，雙瓶胝兩肩。","蕭寺百餘僧，東廚正揚煙。","露足沙石裂，外形巾褐穿。","若其有此身，豈得安穩眠。","獨出違順境，不爲寒暑還。","大聖於其中，領我心之虔。","萬法常空滅，無生因忍全。","一國一釋迦，一燈分百千。","永願遺世知，現身彌勒前。","潛容偏虛空，靈響不可傳。","智慧舍利佛，神通自乾連。","阿若楚系簡帛陳如，迦葉迦旜延。","左右二菩薩，文殊幷普賢。","身披六銖衣，億刦爲大僊。","寶塔寶樓閣，重簷交梵天。","譬如一明珠，共贊光白圓。","天魔波[旬]等，降伏金剛堅。","野叉羅剎鬼，亦赦塵垢纏。","乃致金翅鳥，吞龍護洪淵。","一十一衆中，身意皆快然。","八河注大海，中有楞伽船。","佛法付國王，平等無頗偏。","天子事端拱，大臣行其權。","玉堂無蠅飛，五月冰凜筵。","盡力答明主，猶自招罪愆。","九族無白身，百花動嬋娟。","神聖惡如此，物華不能妍。","祿山一微胡，驅馬來自燕。","宛彼宮闕麗，如何犬羊羶。","苦哉千萬人，流血成丹川。","此輩之死後，鑊湯所熬煎。","業風吹其魂，猛火燒其煙。","獨有丁行者，無憂樹枝邊。","市頭盲老人，長者乞一錢。","韜照多密用，爲君吟此篇。"]', '["化佛示持帚，仲尼稱執鞭。","列生御风归，飼豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长綬趨遙泉。","开士行何苦，雙瓶胝兩肩。","蕭寺百餘僧，东廚正揚煙。","露足沙石裂，外形巾褐穿。","若其有此身，豈得安穩眠。","独出違順境，不爲寒暑還。","大聖於其中，領我心之虔。","万法常空滅，無生因忍全。","一国一釋迦，一灯分百千。","永願遺世知，現身彌勒前。","潛容偏虛空，靈响不可傳。","智慧舍利佛，神通自乾連。","阿若楚系簡帛陳如，迦葉迦旜延。","左右二菩薩，文殊幷普賢。","身披六銖衣，億刦爲大僊。","寶塔寶楼閣，重簷交梵天。","譬如一明珠，共贊光白圓。","天魔波[旬]等，降伏金剛堅。","野叉羅剎鬼，亦赦塵垢纏。","乃致金翅鸟，吞龙護洪淵。","一十一衆中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等無頗偏。","天子事端拱，大臣行其權。","玉堂無蠅飞，五月冰凜筵。","尽力答明主，猶自招罪愆。","九族無白身，百花动嬋娟。","神聖惡如此，物华不能妍。","祿山一微胡，驱马来自燕。","宛彼宮闕丽，如何犬羊羶。","苦哉千万人，流血成丹川。","此輩之死後，鑊湯所熬煎。","業风吹其魂，猛火燒其煙。","独有丁行者，無憂樹枝邊。","市头盲老人，长者乞一錢。","韜照多密用，爲君吟此篇。"]', '诗', 'shi', '', NULL, '歸陽蕭寺有丁行者能修無生忍擔水施僧況歸命稽首作詩 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea92a5e4-7f48-4141-b793-2572b5df86f0', '大茅嶺東新居憶亡子從真', '大茅嶺东新居憶亡子從真', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["谷鳥猶呼兒，山人夕霑襟。","懷哉隔生死，悵矣徒登臨。","東門憂不入，西河遇亦深。","古來失中道，偶向經中尋。","大象無停輪，倏忽成古今。","其夭非不幸，鍊形由太陰。","凡欲攀雲階，譬如火鑄金。","虛室留舊札，洞房掩閑琴。","泉源登方諸，上有空青林。","彷彿通寤寐，蕭寥邈微音。","軟草被汀洲，鮮雲略浮沈。","赬景宣疊麗，紺波響飄淋。","石窟含雲巢，迢迢耿南岑。","悲恨自茲斷，情塵詎能侵。","真靜一時變，作起唯從心。"]', '["谷鸟猶呼兒，山人夕霑襟。","懷哉隔生死，悵矣徒登臨。","东门憂不入，西河遇亦深。","古来失中道，偶向經中尋。","大象無停輪，倏忽成古今。","其夭非不幸，鍊形由太陰。","凡欲攀云階，譬如火鑄金。","虛室留旧札，洞房掩闲琴。","泉源登方諸，上有空青林。","彷彿通寤寐，蕭寥邈微音。","軟草被汀洲，鲜云略浮沈。","赬景宣叠丽，紺波响飄淋。","石窟含云巢，迢迢耿南岑。","悲恨自茲斷，情塵詎能侵。","真静一时变，作起唯從心。"]', '诗', 'shi', '', NULL, '大茅嶺東新居憶亡子從真 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fd5d58-7d49-4996-aaeb-3853a658fa67', '烏啼曲二首 一', '烏啼曲二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉房掣鎖聲翻葉，銀箭添泉遶霜堞。","畢逋撥刺月銜城，八九雛飛其母驚。","此是天上老鵶鳴，人間老鵶無此聲。","搖風雜佩耿華燭，夜聽羽人彈此曲。","東方曈曈赤日旭。"]', '["玉房掣鎖声翻葉，銀箭添泉遶霜堞。","畢逋撥刺月銜城，八九雛飞其母驚。","此是天上老鵶鳴，人间老鵶無此声。","搖风杂佩耿华燭，夜听羽人彈此曲。","东方曈曈赤日旭。"]', '诗', 'shi', '', NULL, '烏啼曲二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667e8be7-4629-4c05-8463-da20b021205a', '烏啼曲二首 二', '烏啼曲二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["月出江林西，江林寂寂城鵶啼。","昔人何處爲此曲，今人何處聽不足。","城寒月曉馳思深，江上青草爲誰綠。"]', '["月出江林西，江林寂寂城鵶啼。","昔人何处爲此曲，今人何处听不足。","城寒月晓驰思深，江上青草爲誰綠。"]', '诗', 'shi', '', NULL, '烏啼曲二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f193404-a54b-4d12-9806-99609b76beca', '幽居弄', '幽居弄', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["苔衣生，花露滴，月入西林蕩東壁。","扣商占角兩三聲，洞戶谿窗一冥寂。","獨去滄洲無四鄰，身嬰世網此何身。","關情命曲寄惆悵，久別山南山裏人。"]', '["苔衣生，花露滴，月入西林蕩东壁。","扣商占角兩三声，洞戶谿窗一冥寂。","独去滄洲無四鄰，身嬰世網此何身。","关情命曲寄惆悵，久別山南山裏人。"]', '诗', 'shi', '', NULL, '幽居弄 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6b6b38-8143-4f5c-af5a-d68264e12a8e', '公子行', '公子行', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["輕薄兒，面如玉，紫陌春風纏馬足。","雙𩍐懸金縷鶻飛，長衫刺雪生犀束。","綠槐夾道陰初成，珊瑚幾節敵流星。","紅肌拂拂酒光獰，當街背拉金吾行。","朝遊鼕鼕鼓聲發，暮遊鼕鼕鼓聲絕。","入門不肯自升堂，美人扶踏金階月。"]', '["轻薄兒，面如玉，紫陌春风纏马足。","雙𩍐懸金縷鶻飞，长衫刺雪生犀束。","綠槐夾道陰初成，珊瑚幾節敵流星。","紅肌拂拂酒光獰，當街背拉金吾行。","朝游鼕鼕鼓声發，暮游鼕鼕鼓声絕。","入门不肯自升堂，美人扶踏金階月。"]', '诗', 'shi', '', NULL, '公子行 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f980c17f-9772-4c08-a3be-bce750284ae1', '古離別', '古離別', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["西江上，風動麻姑嫁時浪。","西山爲水水爲塵，不是人間離別人。"]', '["西江上，风动麻姑嫁时浪。","西山爲水水爲塵，不是人间離別人。"]', '诗', 'shi', '', NULL, '古離別 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba479ed-b4a3-43d6-8487-e268da7913aa', '長安道', '长安道', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["長安道，人無衣，馬無草，何不歸來山中老。"]', '["长安道，人無衣，马無草，何不归来山中老。"]', '诗', 'shi', '', NULL, '長安道 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf536fe-b955-47a0-aa04-d5b039a829dc', '龍宮操', '龙宮操', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["龍宮月明光參差，精衛銜石東飛時。","鮫人織綃採藕絲，翻江倒海傾吳蜀。","漢女江妃杳相續，龍王宮中水不足。"]', '["龙宮月明光參差，精衛銜石东飞时。","鮫人织綃採藕絲，翻江倒海傾吳蜀。","漢女江妃杳相續，龙王宮中水不足。"]', '诗', 'shi', '', NULL, '龍宮操 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c438e6-a5a5-4c4c-9820-4ccad6bf6338', '梁廣畫花歌', '梁廣畫花歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["王母欲過劉徹家，飛瓊夜入雲軿車。","紫書分付與青鳥，却向人間求好花。","上元夫人最小女，頭面端正能言語。","手把梁生畫花看，凝嚬掩笑心相許。","心相許，爲白阿孃從嫁與。"]', '["王母欲過劉徹家，飞瓊夜入云軿车。","紫书分付與青鸟，却向人间求好花。","上元夫人最小女，头面端正能言語。","手把梁生畫花看，凝嚬掩笑心相許。","心相許，爲白阿孃從嫁與。"]', '诗', 'shi', '', NULL, '梁廣畫花歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b34ea02-c7d3-491f-af4f-a3166c6b6e22', '送別日晚歌', '送別日晚歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["日窅窅兮下山，望佳人兮不還。","花落兮屋上，草生兮堦間。","日日兮春風，芳菲兮欲歇。","老不可兮更少，君何爲兮輕別。"]', '["日窅窅兮下山，望佳人兮不還。","花落兮屋上，草生兮堦间。","日日兮春风，芳菲兮欲歇。","老不可兮更少，君何爲兮轻別。"]', '诗', 'shi', '', NULL, '送別日晚歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee096afe-357e-40fd-bc25-19361ea20a08', '行路難三首 一', '行路难三首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見擔雪塞井空用力，炊砂作飯豈堪食。","一生肝膽向人盡，相識不如不相識。","冬青樹上挂凌霄，歲晏花凋樹不凋。","凡物各自有根本，種禾終不生荳苗。","行路難，行路難，何處是平道。","中心無事當富貴，今日看君顏色好。"]', '["君不见擔雪塞井空用力，炊砂作飯豈堪食。","一生肝膽向人尽，相識不如不相識。","冬青樹上挂凌霄，歲晏花凋樹不凋。","凡物各自有根本，種禾終不生荳苗。","行路难，行路难，何处是平道。","中心無事當富貴，今日看君顏色好。"]', '诗', 'shi', '', NULL, '行路難三首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca48934-83a4-469e-aaec-495e4224aa82', '行路難三首 二', '行路难三首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見少年頭上如雲髮，少壯如雲老如雪。","豈知灌頂有醍醐，能使清涼頭不熱。","呂梁之水挂飛流，黿鼉蛟蜃不敢遊。","少年恃險若平地，獨倚長劍凌清秋。","行路難，行路難，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊占城草。"]', '["君不见少年头上如云髮，少壯如云老如雪。","豈知灌頂有醍醐，能使清涼头不熱。","呂梁之水挂飞流，黿鼉蛟蜃不敢游。","少年恃險若平地，独倚长劍凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊占城草。"]', '诗', 'shi', '', NULL, '行路難三首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d580d0a3-5dc1-429b-9273-3608f6194c5b', '行路難三首 三', '行路难三首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見古人燒水銀，變作北邙山上塵。","藕絲掛在虛空中，欲落不落愁殺人。","睢水英雄多血刃，建章宮闕成煨燼。","淮王身死桂樹折，徐福一去音書絕。","行路難，行路難，生死皆由天。","秦皇漢武遭不脫，汝獨何人學神仙。"]', '["君不见古人燒水銀，变作北邙山上塵。","藕絲掛在虛空中，欲落不落愁殺人。","睢水英雄多血刃，建章宮闕成煨燼。","淮王身死桂樹折，徐福一去音书絕。","行路难，行路难，生死皆由天。","秦皇漢武遭不脫，汝独何人学神仙。"]', '诗', 'shi', '', NULL, '行路難三首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a413aab8-b859-42a8-a490-d4c0ca2002a3', '悲歌 一', '悲歌 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["邊城路，今人犂田昔人墓。","岸上沙，昔日江水今人家。","今人昔人共長歎，四氣相催節廻換。","明月皎皎入華池，白雲離離渡霄漢。"]', '["邊城路，今人犂田昔人墓。","岸上沙，昔日江水今人家。","今人昔人共长歎，四氣相催節廻換。","明月皎皎入华池，白云離離渡霄漢。"]', '诗', 'shi', '', NULL, '悲歌 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1d94ae-6617-47c5-933b-202a7dfa48a4', '悲歌 二', '悲歌 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["我欲昇天天隔霄，我欲渡水水無橋。","我欲上山山路險，我欲汲井井泉遙。","越人翠被今何夕，獨立沙邊江草碧。","紫燕西飛欲寄書，白雲何處逢來客。"]', '["我欲昇天天隔霄，我欲渡水水無橋。","我欲上山山路險，我欲汲井井泉遙。","越人翠被今何夕，独立沙邊江草碧。","紫燕西飞欲寄书，白云何处逢来客。"]', '诗', 'shi', '', NULL, '悲歌 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79d9f65-cb2f-4ddb-a60e-3ef126825f09', '悲歌 三', '悲歌 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["新繫青絲百尺繩，心在君家轆轤上。","我心皎潔君不知，轆轤一轉一惆悵。"]', '["新繫青絲百尺繩，心在君家轆轤上。","我心皎潔君不知，轆轤一轉一惆悵。"]', '诗', 'shi', '', NULL, '悲歌 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('838cb3d4-9d9f-4365-ba74-bd375234b052', '悲歌 四', '悲歌 四', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["何處春風吹曉幕，江南淥水通朱閣。","美人二八面如花，泣向春風畏花落。"]', '["何处春风吹晓幕，江南淥水通朱閣。","美人二八面如花，泣向春风畏花落。"]', '诗', 'shi', '', NULL, '悲歌 四 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731a76c4-8cb7-4c78-afc2-a062339c5034', '悲歌 五', '悲歌 五', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["臨春風，聽春鳥，別時多，見時少。","愁人夜永不得眠，瑤井玉繩相對曉。"]', '["臨春风，听春鸟，別时多，见时少。","愁人夜永不得眠，瑤井玉繩相对晓。"]', '诗', 'shi', '', NULL, '悲歌 五 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487b1bf1-6f50-4f64-8e1d-2576534397fc', '悲歌 六', '悲歌 六', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["軒轅黃帝初得仙，鼎湖一去三千年。","周流三十六洞天，洞中日月星辰聯。","騎龍駕景遊八極，軒轅弓劍無人識，東海青童寄消息。"]', '["軒轅黄帝初得仙，鼎湖一去三千年。","周流三十六洞天，洞中日月星辰聯。","騎龙駕景游八極，軒轅弓劍無人識，东海青童寄消息。"]', '诗', 'shi', '', NULL, '悲歌 六 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a4d82d-65d0-447e-831c-353f52a38640', '春草謠', '春草謠', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["春草不解行，隨人上東城。","正月二月色綿綿，千里萬里傷人情。"]', '["春草不解行，隨人上东城。","正月二月色綿綿，千里万里傷人情。"]', '诗', 'shi', '', NULL, '春草謠 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a4e5b5-fbe1-44fd-a2b8-f88cfc6b9216', '苔蘚山歌', '苔蘚山歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["野人夜夢江南山，江南山深松桂閑。","野人覺後長歎息，帖蘚黏苔作山色。","閉門無事任盈虛，終日欹眠觀四如。","一如白雲飛出壁，二如飛雨巖前滴。","三如騰虎欲咆哮，四如嬾龍遭霹靂。","嶮峭嵌空潭洞寒，小兒兩手扶欄干。"]', '["野人夜梦江南山，江南山深松桂闲。","野人覺後长歎息，帖蘚黏苔作山色。","閉门無事任盈虛，終日欹眠观四如。","一如白云飞出壁，二如飞雨巖前滴。","三如腾虎欲咆哮，四如嬾龙遭霹靂。","嶮峭嵌空潭洞寒，小兒兩手扶欄干。"]', '诗', 'shi', '', NULL, '苔蘚山歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46f7ede-7f44-4b64-b079-f0d85f7c3550', '同裴觀察東湖望山歌', '同裴观察东湖望山歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["浴鮮積翠栖靈異，石洞花宮橫半空。","夜光潭上明星啟，風雨壇邊樹如洗。","水淹徐孺宅恆乾，繩墜洪崖井無底。","主人載酒東湖陰，遙望西山三四岑。"]', '["浴鲜積翠栖靈異，石洞花宮橫半空。","夜光潭上明星啟，风雨壇邊樹如洗。","水淹徐孺宅恆乾，繩墜洪崖井無底。","主人載酒东湖陰，遙望西山三四岑。"]', '诗', 'shi', '', NULL, '同裴觀察東湖望山歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec7c911-60f3-460c-9a95-7b8236486892', '八月五日歌', '八月五日歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["四月八日明星出，摩耶夫人降前佛。","八月五日佳氣新，昭成太后生聖人。","開元九年燕公說，奉詔聽置千秋節。","丹青廟裏貯姚宋，花蕚樓中宴岐薛。","清樂靈香幾處聞，鸞歌鳳吹動祥雲。","已於武庫見靈鳥，仍向晉山逢老君。","率土普天無不樂，河清海晏窮寥廓。","梨園第子傳法曲，張果先生進仙藥。","玉座淒涼遊帝京，悲翁迴首望承明。","雲韶九奏杳然遠，唯有五陵松柏聲。"]', '["四月八日明星出，摩耶夫人降前佛。","八月五日佳氣新，昭成太后生聖人。","开元九年燕公说，奉詔听置千秋節。","丹青廟裏貯姚宋，花蕚楼中宴岐薛。","清乐靈香幾处闻，鸾歌鳳吹动祥云。","已於武庫见靈鸟，仍向晉山逢老君。","率土普天無不乐，河清海晏窮寥廓。","梨园第子傳法曲，張果先生進仙藥。","玉座淒涼游帝京，悲翁迴首望承明。","云韶九奏杳然远，唯有五陵松柏声。"]', '诗', 'shi', '', NULL, '八月五日歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f646a1ae-7a3e-4cdb-96d4-8c2ab4fb899a', '露青竹杖歌', '露青竹杖歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鮮于仲通正當年，章仇兼瓊在蜀川。","約束蜀兒採馬鞭，蜀兒採鞭不敢眠。","橫截斜飛飛鳥邊，繩橋夜上層崖顛。","頭插白雲跨飛泉，採得馬鞭長且堅。","浮漚丁子珠聯聯，灰煮蠟楷光爛然。","章仇兼瓊持上天，上天雨露何其偏。","飛龍閑廄馬數千，朝飲吳江夕秣燕。","紅塵撲轡汗濕韉，師子麒麟聊比肩。","江面昆明洗刷牽，四蹄踏浪頭枿天。","蛟龍稽顙河伯虔，拓羯胡雛脚手鮮。","陳閎韓幹丹青妍，欲貌未貌眼欲穿。","金鞍玉勒錦連乾，騎入桃花楊柳煙。","十二樓中奏管絃，樓中美人奪神仙。","爭愛大家把此鞭，祿山入關關破年。","忽見揚州北邙前，秪有人還千一錢。","亭亭筆直無皴節，磨捋形相一條鐵。","市頭格是無人別，江海賤臣不拘絏。","垂窗掛影西窗缺，稚子覓衣挑仰穴。","家童拾薪幾拗折，玉潤猶沾玉壘雪。","碧鮮似染萇弘血，蜀帝城邊子規咽。","相如橋上文君絕，往年策馬降至尊。","七盤九折橫劍門，穆王八駿超崑崙。","安用冉冉孤生根，聖人不貴難得貨，金玉珊珊誰買恩。"]', '["鲜于仲通正當年，章仇兼瓊在蜀川。","約束蜀兒採马鞭，蜀兒採鞭不敢眠。","橫截斜飞飞鸟邊，繩橋夜上層崖顛。","头插白云跨飞泉，採得马鞭长且堅。","浮漚丁子珠聯聯，灰煮蠟楷光爛然。","章仇兼瓊持上天，上天雨露何其偏。","飞龙闲廄马數千，朝饮吳江夕秣燕。","紅塵撲轡汗濕韉，師子麒麟聊比肩。","江面昆明洗刷牽，四蹄踏浪头枿天。","蛟龙稽顙河伯虔，拓羯胡雛脚手鲜。","陳閎韓幹丹青妍，欲貌未貌眼欲穿。","金鞍玉勒錦連乾，騎入桃花楊柳煙。","十二楼中奏管絃，楼中美人奪神仙。","爭愛大家把此鞭，祿山入关关破年。","忽见揚州北邙前，秪有人還千一錢。","亭亭笔直無皴節，磨捋形相一條鐵。","市头格是無人別，江海賤臣不拘絏。","垂窗掛影西窗缺，稚子覓衣挑仰穴。","家童拾薪幾拗折，玉潤猶沾玉壘雪。","碧鲜似染萇弘血，蜀帝城邊子規咽。","相如橋上文君絕，往年策马降至尊。","七盤九折橫劍门，穆王八駿超崑崙。","安用冉冉孤生根，聖人不貴难得貨，金玉珊珊誰買恩。"]', '诗', 'shi', '', NULL, '露青竹杖歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6515ec6-ebf7-462b-968c-292bd85c3e80', '金璫玉珮歌', '金璫玉珮歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["贈君金璫太霄之玉珮，金鎖禹步之流珠。","五嶽真君之秘籙，九天丈人之寶書。","東井沐浴辰已畢，先進洞房上奔日。","借問君欲何處來，黃姑織女機邊出。"]', '["贈君金璫太霄之玉珮，金鎖禹步之流珠。","五嶽真君之秘籙，九天丈人之寶书。","东井沐浴辰已畢，先進洞房上奔日。","借问君欲何处来，黄姑织女機邊出。"]', '诗', 'shi', '', NULL, '金璫玉珮歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6cdf4b0-8738-431f-8868-7b55e4449a6a', '瑤草春', '瑤草春', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["瑤草春，杳容與，江南豔歌京西舞。","執心輕子都，信節冠秋胡。","議以腰支嫁，時論自有夫。","蟬鬢蛾眉明井底，燕裙趙袂縈轆轤。","李生聞之淚如綆，不忍回頭看此井。","月中桂樹落一枝，池上鵁鶄唳孤影。","露桃穠李自成谿，流水終天不向西。","翠帳綠窗寒寂寂，錦茵羅薦夜淒淒。","瑤草春，丹井遠，別後相思意深淺。"]', '["瑤草春，杳容與，江南豔歌京西舞。","執心轻子都，信節冠秋胡。","議以腰支嫁，时論自有夫。","蟬鬢蛾眉明井底，燕裙趙袂縈轆轤。","李生闻之泪如綆，不忍回头看此井。","月中桂樹落一枝，池上鵁鶄唳孤影。","露桃穠李自成谿，流水終天不向西。","翠帳綠窗寒寂寂，錦茵羅薦夜淒淒。","瑤草春，丹井远，別後相思意深淺。"]', '诗', 'shi', '', NULL, '瑤草春 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee466a7e-a7e8-4eda-a53f-1d7fdaaa5e62', '蕭鄲草書歌', '蕭鄲草书歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["蕭子草書人不及，洞庭葉落秋風急。","上林花開春露濕，花枝濛濛向水垂。","見君數行之灑落，石上之松松下鶴。","若把君書比仲將，不知誰在凌雲閣。"]', '["蕭子草书人不及，洞庭葉落秋风急。","上林花开春露濕，花枝濛濛向水垂。","见君數行之灑落，石上之松松下鹤。","若把君书比仲將，不知誰在凌云閣。"]', '诗', 'shi', '', NULL, '蕭鄲草書歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476dd07c-f924-451d-a721-cbc3957438ca', '范山人畫山水歌', '范山人畫山水歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["山崢嶸，水泓澄。","漫漫汗汗一筆耕，一草一木棲神明。","忽如空中有物，物中有聲。","復如遠道望鄉客，夢遶山川身不行。"]', '["山崢嶸，水泓澄。","漫漫汗汗一笔耕，一草一木棲神明。","忽如空中有物，物中有声。","复如远道望乡客，梦遶山川身不行。"]', '诗', 'shi', '', NULL, '范山人畫山水歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6582ae44-7ca2-4d8e-b3c4-434d3ad6a38a', '嵇山道芬上人畫山水歌', '嵇山道芬上人畫山水歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鏡中真僧白道芬，不服朱審李將軍。","淥汗平鋪洞庭水，筆頭點出蒼梧雲。","且看八月十五夜，月下看山盡如畫。"]', '["镜中真僧白道芬，不服朱審李將軍。","淥汗平鋪洞庭水，笔头点出蒼梧云。","且看八月十五夜，月下看山尽如畫。"]', '诗', 'shi', '', NULL, '嵇山道芬上人畫山水歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6045a96b-444d-4bc2-adb7-84baa1d21591', '杜秀才畫立走水牛歌', '杜秀才畫立走水牛歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["崑崙兒，騎白象，時時鎖著師子項。","奚奴跨馬不搭鞍，立走水牛驚漢官。","江村小兒好誇騁，脚踏牛頭上牛領。","淺草平田攃過時，大蟲著鈍幾落井。","杜生知我戀滄州，畫作一障張牀頭。","八十老婆拍手笑，妬他織女嫁牽牛。"]', '["崑崙兒，騎白象，时时鎖著師子項。","奚奴跨马不搭鞍，立走水牛驚漢官。","江村小兒好誇騁，脚踏牛头上牛領。","淺草平田攃過时，大蟲著鈍幾落井。","杜生知我戀滄州，畫作一障張牀头。","八十老婆拍手笑，妬他织女嫁牽牛。"]', '诗', 'shi', '', NULL, '杜秀才畫立走水牛歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce013b49-2360-4975-868d-51f326a07115', '梁司馬畫馬歌', '梁司马畫马歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["畫精神，畫筋骨，一團旋風瞥滅沒。","仰秣如上賀蘭山，低頭欲飲長城窟。","此馬昂然獨此羣，阿爺是龍飛入雲。","黃沙枯磧無寸草，一日行過千里道。","展處把筆欲描時，司馬一騧賽傾倒。"]', '["畫精神，畫筋骨，一團旋风瞥滅沒。","仰秣如上賀蘭山，低头欲饮长城窟。","此马昂然独此羣，阿爺是龙飞入云。","黄沙枯磧無寸草，一日行過千里道。","展处把笔欲描时，司马一騧賽傾倒。"]', '诗', 'shi', '', NULL, '梁司馬畫馬歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebd6191-3d23-4144-81f6-7fb50f261225', '丘小府小鼓歌', '丘小府小鼓歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["地盤山鷄猶可像，坎坎砰砰隨手長。","夜半高樓沈醉時，萬里踏橋亂山響。"]', '["地盤山鷄猶可像，坎坎砰砰隨手长。","夜半高楼沈醉时，万里踏橋亂山响。"]', '诗', 'shi', '', NULL, '丘小府小鼓歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d35a08f-2e94-4820-b998-df34d276838e', '宜城放琴客歌', '宜城放琴客歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["佳人玉立生此方，家住邯鄲不是倡。","頭髻䰀鬌手爪長，善撫琴瑟有文章。","新妍籠裙雲母光，朱絃綠水喧洞房。","忽聞斗酒初決絕，日暮浮雲古離別。","巴猿啾啾峽泉咽，淚落羅衣顏色暍。","不知誰家更張設，絲履牆偏釵股折。","南山闌干千丈雪，七十非人不暖熱。","人情厭薄古共然，相公心在持事堅。","上善若水任方圓，憶昨好之今棄捐。","服藥不如獨自眠，從他更嫁一少年。"]', '["佳人玉立生此方，家住邯鄲不是倡。","头髻䰀鬌手爪长，善撫琴瑟有文章。","新妍籠裙云母光，朱絃綠水喧洞房。","忽闻斗酒初決絕，日暮浮云古離別。","巴猿啾啾峽泉咽，泪落羅衣顏色暍。","不知誰家更張設，絲履牆偏釵股折。","南山闌干千丈雪，七十非人不暖熱。","人情厭薄古共然，相公心在持事堅。","上善若水任方圓，憶昨好之今棄捐。","服藥不如独自眠，從他更嫁一少年。"]', '诗', 'shi', '', NULL, '宜城放琴客歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df89d483-be68-42c9-aeae-dde37afb8667', '李供奉彈箜篌歌', '李供奉彈箜篌歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["國府樂手彈箜篌，赤黃條索金鎝頭。","早晨有敕鴛鴦殿，夜靜遂歌明月樓。","起坐可憐能抱撮，大指調絃中指撥。","腕頭花落舞製裂，手下鳥驚飛撥剌。","珊瑚席，一聲一聲鳴錫錫。","羅綺屏，一絃一絃如撼鈴。","急彈好，遲亦好，宜遠聽，宜近聽。","左手低，右手舉，易調移音天賜與。","大絃似秋雁，聯聯度隴關。","小絃似春燕，喃喃向人語。","手頭疾，腕頭軟，來來去去如風卷。","聲清泠泠鳴索索，垂珠碎玉空中落。","美女爭窺玳瑁簾，聖人卷上真珠箔。","大絃長，小絃短，小絃緊快大絃緩。","初調鏘鏘似鴛鴦水上弄新聲，入深似太清仙鶴遊秘館。","李供奉，儀容質，身才稍稍六尺一。","在外不曾輙敎人，內裏聲聲不遣出。","指剝葱，腕削玉，饒鹽饒醬五味足。","弄調人間不識名，彈盡天下崛奇曲。","胡曲漢曲聲皆好，彈着曲髓曲肝腦。","往往從空入戶來，瞥瞥隨風落春草。","草頭只覺風吹入，風來草即隨風立。","草亦不知風到來，風亦不知聲緩急。","爇玉燭，點銀燈，光照手，實可憎。","只照箜篌絃上手，不照箜篌聲裏能。","馳鳳闕，拜鸞殿，天子一日一迴見。","王侯將相立馬迎，巧聲一日一迴變。","實可重，不惜千金買一弄。","銀器胡瓶馬上馱，瑞錦輕羅滿車送。","此州好手非一國，一國東西盡南北。","除却天上化下來，若向人間實難得。"]', '["国府乐手彈箜篌，赤黄條索金鎝头。","早晨有敕鴛鴦殿，夜静遂歌明月楼。","起坐可怜能抱撮，大指調絃中指撥。","腕头花落舞製裂，手下鸟驚飞撥剌。","珊瑚席，一声一声鳴錫錫。","羅綺屏，一絃一絃如撼鈴。","急彈好，遲亦好，宜远听，宜近听。","左手低，右手舉，易調移音天賜與。","大絃似秋雁，聯聯度隴关。","小絃似春燕，喃喃向人語。","手头疾，腕头軟，来来去去如风卷。","声清泠泠鳴索索，垂珠碎玉空中落。","美女爭窺玳瑁簾，聖人卷上真珠箔。","大絃长，小絃短，小絃緊快大絃緩。","初調鏘鏘似鴛鴦水上弄新声，入深似太清仙鹤游秘館。","李供奉，儀容質，身才稍稍六尺一。","在外不曾輙敎人，內裏声声不遣出。","指剝葱，腕削玉，饒鹽饒醬五味足。","弄調人间不識名，彈尽天下崛奇曲。","胡曲漢曲声皆好，彈着曲髓曲肝腦。","往往從空入戶来，瞥瞥隨风落春草。","草头只覺风吹入，风来草即隨风立。","草亦不知风到来，风亦不知声緩急。","爇玉燭，点銀灯，光照手，實可憎。","只照箜篌絃上手，不照箜篌声裏能。","驰鳳闕，拜鸾殿，天子一日一迴见。","王侯將相立马迎，巧声一日一迴变。","實可重，不惜千金買一弄。","銀器胡瓶马上馱，瑞錦轻羅满车送。","此州好手非一国，一国东西尽南北。","除却天上化下来，若向人间實难得。"]', '诗', 'shi', '', NULL, '李供奉彈箜篌歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7ccc3d-418a-4e51-a5c5-5e22c163b042', '劉禪奴彈琵琶歌', '劉禪奴彈琵琶歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["樂府只傳橫吹好，琵琶寫出關山道。","羈雁出塞繞黃雲，邊馬仰天嘶白草。","明妃愁中漢使迴，蔡琰愁處胡笳哀。","鬼神知妙欲收響，陰風切切四面來。","李陵寄書別蘇武，自有生人無此苦。","當時若值霍驃姚，滅盡烏孫奪公主。"]', '["乐府只傳橫吹好，琵琶寫出关山道。","羈雁出塞繞黄云，邊马仰天嘶白草。","明妃愁中漢使迴，蔡琰愁处胡笳哀。","鬼神知妙欲收响，陰风切切四面来。","李陵寄书別蘇武，自有生人無此苦。","當时若值霍驃姚，滅尽烏孫奪公主。"]', '诗', 'shi', '', NULL, '劉禪奴彈琵琶歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad3aa19-2d64-4a45-b0bc-12522587addb', '李湖州孺人彈箏歌', '李湖州孺人彈箏歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["武帝昇天留法曲，淒清掩仰絃柱促。","上陽宮人怨青苔，此夜想夫憐碧玉。","思婦高樓刺壁窺，愁猿呌月鸚呼兒。","寸心十指有長短，妙入神處無人知。","獨把梁州凡幾拍，風沙對面胡秦隔。","聽中忘却前溪碧，醉後猶疑邊草白。"]', '["武帝昇天留法曲，淒清掩仰絃柱促。","上陽宮人怨青苔，此夜想夫怜碧玉。","思婦高楼刺壁窺，愁猿呌月鸚呼兒。","寸心十指有长短，妙入神处無人知。","独把梁州凡幾拍，风沙对面胡秦隔。","听中忘却前溪碧，醉後猶疑邊草白。"]', '诗', 'shi', '', NULL, '李湖州孺人彈箏歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac28499c-b62a-41e9-91cb-02da03af5253', '鄭女彈箏歌', '鄭女彈箏歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鄭女八歲能彈箏，春風吹落天上聲。","一聲雍門淚承睫，兩聲赤鯉露鬐鬣。","二聲白猿臂拓頰，鄭女出參丈人時。","落花惹斷遊空絲，高樓不掩許聲出，羞殺百舌黃鶯兒。"]', '["鄭女八歲能彈箏，春风吹落天上声。","一声雍门泪承睫，兩声赤鯉露鬐鬣。","二声白猿臂拓頰，鄭女出參丈人时。","落花惹斷游空絲，高楼不掩許声出，羞殺百舌黄鶯兒。"]', '诗', 'shi', '', NULL, '鄭女彈箏歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ed42af4-01fa-47fe-88cf-d33e0e8aa90d', '諒公洞庭孤橘歌', '諒公洞庭孤橘歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不種自生一株橘，誰敎渠向堦前出。","不羨江陵千木奴，下生白蟻子，上生青雀雛。","飛花簷蔔旃檀香，結實如綴摩尼珠。","洞庭橘樹籠煙碧，洞庭波月連沙白。","待取天公放恩赦，儂家定作湖中客。"]', '["不種自生一株橘，誰敎渠向堦前出。","不羨江陵千木奴，下生白蟻子，上生青雀雛。","飞花簷蔔旃檀香，結實如綴摩尼珠。","洞庭橘樹籠煙碧，洞庭波月連沙白。","待取天公放恩赦，儂家定作湖中客。"]', '诗', 'shi', '', NULL, '諒公洞庭孤橘歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff924b90-45ee-4a80-adf9-d5c1645b03bd', '送行歌', '送行歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["送行人，歌一曲，何者爲泥何者玉？年華已向秋草裏，春夢猶傳故山綠。"]', '["送行人，歌一曲，何者爲泥何者玉？年华已向秋草裏，春梦猶傳故山綠。"]', '诗', 'shi', '', NULL, '送行歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc1becd-3500-4ff9-aba2-6c2282dc1f16', '險竿歌', '險竿歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["宛陵女兒擘飛手，長竿橫空上下走。","已能輕險若平地，豈肯身爲一家婦。","宛陵將士天下雄，一下定却長稍弓。","翻身挂影恣騰蹋，反綰頭髻盤旋風。","盤旋風，撇飛鳥，驚猿遶，樹枝褭。","頭上打鼓不聞時，手蹉脚跌蜘蛛絲。","忽雷掣斷流星尾，矐睒劃破蚩尤旗。","若不隨仙作仙女，即應嫁賊生賊兒。","中丞方略通變化，外戶不扃從女嫁。"]', '["宛陵女兒擘飞手，长竿橫空上下走。","已能轻險若平地，豈肯身爲一家婦。","宛陵將士天下雄，一下定却长稍弓。","翻身挂影恣腾蹋，反綰头髻盤旋风。","盤旋风，撇飞鸟，驚猿遶，樹枝褭。","头上打鼓不闻时，手蹉脚跌蜘蛛絲。","忽雷掣斷流星尾，矐睒劃破蚩尤旗。","若不隨仙作仙女，即應嫁賊生賊兒。","中丞方略通变化，外戶不扃從女嫁。"]', '诗', 'shi', '', NULL, '險竿歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af079ae-7cf1-4b44-b0c7-6731fc9b484d', '洛陽行送洛陽韋七明府', '洛陽行送洛陽韋七明府', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["始上龍門望洛川，洛陽桃李豔陽天。","最好當年二三月，上陽宮樹千花發。","疏家父子錯掛冠，梁鴻夫妻虛適越。"]', '["始上龙门望洛川，洛陽桃李豔陽天。","最好當年二三月，上陽宮樹千花發。","疏家父子錯掛冠，梁鴻夫妻虛適越。"]', '诗', 'shi', '', NULL, '洛陽行送洛陽韋七明府 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff6466d-aa4d-4978-bac7-247b638b675f', '黃鵠樓歌送獨孤助', '黄鵠楼歌送独孤助', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故人西去黃鵠樓，西江之水上天流，黃鵠杳杳江悠悠。","黃鵠徘徊故人別，離壺酒盡清絲絕。","綠嶼沒餘煙，白沙連曉月。"]', '["故人西去黄鵠楼，西江之水上天流，黄鵠杳杳江悠悠。","黄鵠徘徊故人別，離壺酒尽清絲絕。","綠嶼沒餘煙，白沙連晓月。"]', '诗', 'shi', '', NULL, '黃鵠樓歌送獨孤助 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2205cb99-73fb-4acc-976f-5f2eeb381baa', '廬山瀑布歌送李顧', '廬山瀑布歌送李顧', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["飄白霓，挂丹梯。","應從織女機邊落，不遣潯陽湖向西。","火雷劈山珠噴日，五老峰前九江溢。","九江悠悠萬古情，古人行盡今人行。","老人也欲上山去，上箇深山無姓名。"]', '["飄白霓，挂丹梯。","應從织女機邊落，不遣潯陽湖向西。","火雷劈山珠噴日，五老峰前九江溢。","九江悠悠万古情，古人行尽今人行。","老人也欲上山去，上箇深山無姓名。"]', '诗', 'shi', '', NULL, '廬山瀑布歌送李顧 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd896dd-b8bb-4fe0-aafd-c0058b1887a7', '朝上清歌', '朝上清歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["潔眼朝上清，綠景開紫霞。","皇皇紫微君，左右皆靈娥。","曼聲流睇，和清歌些。","至陽無諼，其樂多些。","旌蓋颯沓，簫鼓和些。","金鳳玉麟，鬱駢羅些。","反風名香，香氣遐些。","瓊田瑤草，壽無涯些。","君着玉衣，升玉車些。","欲降瓊宮，玉女家些。","其桃千年，始着花些。","蕭寥天清而滅雲，目瓊瓊兮情感。","珮隨香兮夜聞，肅肅兮愔愔。","啓天和兮洞靈心，和爲丹兮雲爲馬。","君乘之觴于瑤池之上兮，三光羅列而在下。"]', '["潔眼朝上清，綠景开紫霞。","皇皇紫微君，左右皆靈娥。","曼声流睇，和清歌些。","至陽無諼，其乐多些。","旌蓋颯沓，簫鼓和些。","金鳳玉麟，鬱駢羅些。","反风名香，香氣遐些。","瓊田瑤草，壽無涯些。","君着玉衣，升玉车些。","欲降瓊宮，玉女家些。","其桃千年，始着花些。","蕭寥天清而滅云，目瓊瓊兮情感。","珮隨香兮夜闻，肅肅兮愔愔。","啓天和兮洞靈心，和爲丹兮云爲马。","君乘之觴于瑤池之上兮，三光羅列而在下。"]', '诗', 'shi', '', NULL, '朝上清歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5a6e41-856a-4163-a050-ba97ce750635', '剡紙歌', '剡紙歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["雲門路上山陰雪，中有玉人持玉節。","宛委山裏禹餘糧，石中黃子黃金屑。","剡溪剡紙生剡藤，噴水搗後爲蕉葉。","欲寫金人金口經，寄與山陰山裏僧。","手把山中紫羅筆，思量點畫龍蛇出。","政是垂頭蹋翼時，不免向君求此物。"]', '["云门路上山陰雪，中有玉人持玉節。","宛委山裏禹餘糧，石中黄子黄金屑。","剡溪剡紙生剡藤，噴水捣後爲蕉葉。","欲寫金人金口經，寄與山陰山裏僧。","手把山中紫羅笔，思量点畫龙蛇出。","政是垂头蹋翼时，不免向君求此物。"]', '诗', 'shi', '', NULL, '剡紙歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8324e261-29c5-4995-ac3e-5b68ff76e411', '洛陽早春', '洛陽早春', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["何地避春愁，終年憶舊遊。","一家千里外，百舌五更頭。","客路偏逢雨，鄉山不入樓。","故園桃李月，伊水向東流。"]', '["何地避春愁，終年憶旧游。","一家千里外，百舌五更头。","客路偏逢雨，乡山不入楼。","故园桃李月，伊水向东流。"]', '诗', 'shi', '', NULL, '洛陽早春 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b558bc9-b3a5-4d04-96df-8ba26bc1f7dd', '步虛詞', '步虛词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["逈步遊三洞，清心禮七真。","飛符超羽翼，焚火醮星辰。","殘藥沾雞犬，靈香出鳳麟。","壺中無窄處，願得一容身。"]', '["逈步游三洞，清心禮七真。","飞符超羽翼，焚火醮星辰。","殘藥沾雞犬，靈香出鳳麟。","壺中無窄处，願得一容身。"]', '诗', 'shi', '', NULL, '步虛詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5f612b-efda-4052-8b01-f002c60dd1a6', '鄱陽大雲寺一公房', '鄱陽大云寺一公房', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["盡日陪遊處，斜陽竹院清。","定中觀有漏，言外證無生。","色界聊傳法，空門不用情。","欲知相去近，鐘鼓兩聞聲。"]', '["尽日陪游处，斜陽竹院清。","定中观有漏，言外證無生。","色界聊傳法，空门不用情。","欲知相去近，鐘鼓兩闻声。"]', '诗', 'shi', '', NULL, '鄱陽大雲寺一公房 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ead7ca2-00ff-4485-aa33-17ce5b155139', '送友失意南歸', '送友失意南归', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["衣揮京洛塵，完璞伴歸人。","故國青山徧，滄江白髮新。","鄰荒收酒幔，屋古布苔茵。","不用通名姓，漁樵共主賓。"]', '["衣揮京洛塵，完璞伴归人。","故国青山徧，滄江白髮新。","鄰荒收酒幔，屋古布苔茵。","不用通名姓，漁樵共主賓。"]', '诗', 'shi', '', NULL, '送友失意南歸 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a0d80d-580b-497d-a998-a3de540a96e5', '南歸', '南归', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["老病力難任，猶多鏡雪侵。","鱸魚消宦況，鷗鳥識歸心。","急雨江帆重，殘更驛樹深。","鄉關殊可望，漸漸入吳音。"]', '["老病力难任，猶多镜雪侵。","鱸鱼消宦況，鷗鸟識归心。","急雨江帆重，殘更驛樹深。","乡关殊可望，漸漸入吳音。"]', '诗', 'shi', '', NULL, '南歸 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5e79ce-17e3-44a2-9d9c-a5b3fe6e91b5', '閑居自述', '闲居自述', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["榮辱不關身，誰爲疎與親。","有山堪結屋，無地可容塵。","白髮偏添壽，黃花不笑貧。","一樽朝暮醉，陶令果何人。"]', '["榮辱不关身，誰爲疎與親。","有山堪結屋，無地可容塵。","白髮偏添壽，黄花不笑貧。","一樽朝暮醉，陶令果何人。"]', '诗', 'shi', '', NULL, '閑居自述 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f79f502-4ed9-4cc1-8e7b-f063efa714a0', '題歙山棲霞寺', '題歙山棲霞寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["明徵君舊宅，陳後主題詩。","跡在人亡處，山空月滿時。","寶瓶無破響，道樹有低枝。","已是傷離客，仍逢靳尚祠。"]', '["明徵君旧宅，陳後主題诗。","跡在人亡处，山空月满时。","寶瓶無破响，道樹有低枝。","已是傷離客，仍逢靳尚祠。"]', '诗', 'shi', '', NULL, '題歙山棲霞寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e61fa9-cd16-47ec-bd76-daeec6588b9a', '經廢寺', '經廢寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不知何世界，有處似南朝。","石路無人掃，松門被火燒。","斷幡猶挂剎，故板尚搘橋。","數卷殘經在，多年字欲銷。"]', '["不知何世界，有处似南朝。","石路無人掃，松门被火燒。","斷幡猶挂剎，故板尚搘橋。","數卷殘經在，多年字欲銷。"]', '诗', 'shi', '', NULL, '經廢寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('553cbee8-d141-4bc0-bd1f-ac6e536c307c', '送李道士', '送李道士', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["人境年虛擲，仙源日未斜。","羨君乘竹杖，辭我隱桃花。","鳥去寧知路，雲飛似憶家。","莫愁客鬢改，自有紫河車。"]', '["人境年虛擲，仙源日未斜。","羨君乘竹杖，辞我隐桃花。","鸟去寧知路，云飞似憶家。","莫愁客鬢改，自有紫河车。"]', '诗', 'shi', '', NULL, '送李道士 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee61b1f-420b-47cc-a342-8ee07e2431cd', '酬唐起居前後見寄二首 一', '酬唐起居前後见寄二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["愁人空望國，驚鳥不歸林。","莫話彈冠事，誰知結襪心。","霜凋樹吹斷，土蝕劍痕深。","欲作懷沙賦，明時恥自沈。"]', '["愁人空望国，驚鸟不归林。","莫話彈冠事，誰知結襪心。","霜凋樹吹斷，土蝕劍痕深。","欲作懷沙賦，明时恥自沈。"]', '诗', 'shi', '', NULL, '酬唐起居前後見寄二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1b461c-9625-4e7c-8da4-1874c7350f77', '酬唐起居前後見寄二首 二', '酬唐起居前後见寄二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["何處弔靈均，江邊一老人。","漢儀君已接，楚奏我空頻。","直道其如命，平生不負神。","自傷庚子日，[鵩]鳥上承塵。"]', '["何处弔靈均，江邊一老人。","漢儀君已接，楚奏我空頻。","直道其如命，平生不負神。","自傷庚子日，[鵩]鸟上承塵。"]', '诗', 'shi', '', NULL, '酬唐起居前後見寄二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559f34ec-f51c-4f98-bf67-6133cb2f64a6', '奉酬茅山贈賜幷簡綦毋正字', '奉酬茅山贈賜幷簡綦毋正字', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉帝居金闕，靈山幾處朝。","簡書猶有畏，神理詎能超。","鶴廟新家近，龍門舊國遙。","離懷結不斷，玉洞一吹簫。"]', '["玉帝居金闕，靈山幾处朝。","簡书猶有畏，神理詎能超。","鹤廟新家近，龙门旧国遙。","離懷結不斷，玉洞一吹簫。"]', '诗', 'shi', '', NULL, '奉酬茅山贈賜幷簡綦毋正字 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b247d865-f336-48cd-add3-e6dedf0f7739', '白蘋洲送客', '白蘋洲送客', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["莫信梅花發，由來謾報春。","不才充野客，扶病送朝臣。","闕下搖青珮，洲邊採白蘋。","臨流不痛飲，鷗鳥也欺人。"]', '["莫信梅花發，由来謾報春。","不才充野客，扶病送朝臣。","闕下搖青珮，洲邊採白蘋。","臨流不痛饮，鷗鸟也欺人。"]', '诗', 'shi', '', NULL, '白蘋洲送客 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8e4d534-83c4-407e-94c2-9f04d2fba5d0', '春鳥詞送元秀才入京', '春鸟词送元秀才入京', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["春來繡羽齊，暮向竹林栖。","禁苑銜花出，河橋隔樹啼。","尋聲知去遠，顧影念飛低。","別有無巢燕，猶窺幕上泥。"]', '["春来繡羽齊，暮向竹林栖。","禁苑銜花出，河橋隔樹啼。","尋声知去远，顧影念飞低。","別有無巢燕，猶窺幕上泥。"]', '诗', 'shi', '', NULL, '春鳥詞送元秀才入京 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143a6266-dd4e-4886-b45b-34c0f86c56b5', '別江南', '別江南', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["江城吹曉角，愁殺遠行人。","漢將猶防虜，吳官欲向秦。","布帆輕白浪，錦帶入紅塵。","將底求名宦，平生但任真。"]', '["江城吹晓角，愁殺远行人。","漢將猶防虜，吳官欲向秦。","布帆轻白浪，錦带入紅塵。","將底求名宦，平生但任真。"]', '诗', 'shi', '', NULL, '別江南 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3049ded-bdb2-4b61-a1c4-348994e5ce98', '空梁落燕泥', '空梁落燕泥', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["卷幕參差燕，常銜濁水泥。","爲黏珠履跡，未等畫梁齊。","舊點痕猶淺，新巢緝尚低。","不緣頻上落，那得此飛棲。"]', '["卷幕參差燕，常銜濁水泥。","爲黏珠履跡，未等畫梁齊。","旧点痕猶淺，新巢緝尚低。","不緣頻上落，那得此飞棲。"]', '诗', 'shi', '', NULL, '空梁落燕泥 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd52aa19-bfdc-4169-9aca-f3cccb0e993c', '上元夜憶長安', '上元夜憶长安', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["滄州老一年，老去憶秦川。","處處逢珠翠，家家聽管絃。","雲車龍闕下，火樹鳳樓前。","今夜滄州夜，滄州夜月圓。"]', '["滄州老一年，老去憶秦川。","处处逢珠翠，家家听管絃。","云车龙闕下，火樹鳳楼前。","今夜滄州夜，滄州夜月圓。"]', '诗', 'shi', '', NULL, '上元夜憶長安 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a717b666-8ab4-4505-bed2-5445f6c07ba3', '酬揚州白塔寺永上人', '酬揚州白塔寺永上人', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["塔上是何緣，香燈續細煙。","松枝當麈尾，柳絮替蠶綿。","浮草經行徧，空花義趣圓。","我來雖爲法，暫借一牀眠。"]', '["塔上是何緣，香灯續細煙。","松枝當麈尾，柳絮替蠶綿。","浮草經行徧，空花義趣圓。","我来雖爲法，暫借一牀眠。"]', '诗', 'shi', '', NULL, '酬揚州白塔寺永上人 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a96883-6408-4218-a9df-e077f72c16c5', '送韋秀才赴舉', '送韋秀才赴舉', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鄱陽中酒地，楚老獨醒年。","芳桂君應折，沈灰我不然。","洛橋浮逆水，關樹接非煙。","唯有殘生夢，猶能到日邊。"]', '["鄱陽中酒地，楚老独醒年。","芳桂君應折，沈灰我不然。","洛橋浮逆水，关樹接非煙。","唯有殘生梦，猶能到日邊。"]', '诗', 'shi', '', NULL, '送韋秀才赴舉 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7067d91-3467-4176-a227-444c90d9ce6d', '送使君', '送使君', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["天中洛陽道，海上使君歸。","拂霧趨金殿，焚香入璅闈。","山亭傾別酒，野服間朝衣。","他日思朱鷺，知從小苑飛。"]', '["天中洛陽道，海上使君归。","拂霧趨金殿，焚香入璅闈。","山亭傾別酒，野服间朝衣。","他日思朱鷺，知從小苑飞。"]', '诗', 'shi', '', NULL, '送使君 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9d8948-13f5-45a7-9a53-03f615c31f4b', '歷陽苦雨', '歷陽苦雨', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["襄城秋雨晦，楚客不歸心。","亥市風煙接，隋宮草路深。","離憂翻獨笑，用事感浮陰。","夜夜空堦響，唯餘蚯蚓吟。"]', '["襄城秋雨晦，楚客不归心。","亥市风煙接，隋宮草路深。","離憂翻独笑，用事感浮陰。","夜夜空堦响，唯餘蚯蚓吟。"]', '诗', 'shi', '', NULL, '歷陽苦雨 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f865e685-cc9b-4edc-b254-6326223ef92c', '傷大理謝少卿', '傷大理謝少卿', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["舊館絕逢迎，新詩何處呈。","空留封禪草，已作岱宗行。","柳蠹風吹析，堦崩雪遶平。","無因重來此，剩哭兩三聲。"]', '["旧館絕逢迎，新诗何处呈。","空留封禪草，已作岱宗行。","柳蠹风吹析，堦崩雪遶平。","無因重来此，剩哭兩三声。"]', '诗', 'shi', '', NULL, '傷大理謝少卿 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0866f21e-3339-4a9e-9084-ba36856743e6', '經徐侍郎墓作', '經徐侍郎墓作', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不知山吏部，墓作石橋東。","宅兆鄉關異，平生翰墨空。","夜泉無曉日，枯樹足悲風。","更想幽冥事，唯應有夢同。"]', '["不知山吏部，墓作石橋东。","宅兆乡关異，平生翰墨空。","夜泉無晓日，枯樹足悲风。","更想幽冥事，唯應有梦同。"]', '诗', 'shi', '', NULL, '經徐侍郎墓作 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e831b4-2a6a-437e-996c-1a2df9fbb761', '酅公合祔挽歌', '酅公合祔挽歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["草露前朝事，荆茅聖主封。","空傳餘竹帛，永絕舊歌鐘。","清鏡無雙影，窮泉有幾重。","笳簫最悲處，風入九原松。"]', '["草露前朝事，荆茅聖主封。","空傳餘竹帛，永絕旧歌鐘。","清镜無雙影，窮泉有幾重。","笳簫最悲处，风入九原松。"]', '诗', 'shi', '', NULL, '酅公合祔挽歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7a6df80-82b4-4185-ba56-134e852b20a3', '相國晉公挽歌二首 一', '相国晉公挽歌二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉節朝天罷，洪爐造化新。","中和方作聖，太素忽收神。","盛德橫千古，高標出四鄰。","欲知言不盡，處處有遺塵。"]', '["玉節朝天罷，洪爐造化新。","中和方作聖，太素忽收神。","盛德橫千古，高標出四鄰。","欲知言不尽，处处有遺塵。"]', '诗', 'shi', '', NULL, '相國晉公挽歌二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('646066df-3633-448c-aee8-b5d8eedace98', '相國晉公挽歌二首 二', '相国晉公挽歌二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["凝笳催曉奠，丹旐向青山。","夕照新塋近，秋風故吏還。","本朝光漢代，從此掃胡關。","今日天難問，浮雲滿世間。"]', '["凝笳催晓奠，丹旐向青山。","夕照新塋近，秋风故吏還。","本朝光漢代，從此掃胡关。","今日天难问，浮云满世间。"]', '诗', 'shi', '', NULL, '相國晉公挽歌二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5301061-dc9b-4a5b-b5ec-55cb5c2feb65', '晉公魏國夫人柳氏挽歌', '晉公魏国夫人柳氏挽歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["魚軒海上遙，鸞影月中銷。","雙劍來時合，孤桐去日凋。","夕陽迷隴隧，秋雨咽笳簫。","畫翣無留影，銘旌已度橋。"]', '["鱼軒海上遙，鸾影月中銷。","雙劍来时合，孤桐去日凋。","夕陽迷隴隧，秋雨咽笳簫。","畫翣無留影，銘旌已度橋。"]', '诗', 'shi', '', NULL, '晉公魏國夫人柳氏挽歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ab4e52-dd05-421d-aadf-df596f6af0fb', '義川公主挽詞', '義川公主挽词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["弄玉吹簫後，湘靈鼓瑟時。","月邊丹桂落，風底白楊悲。","雜珮分泉戶，餘香出繐帷。","夜臺飛鏡匣，偏共掩蛾眉。"]', '["弄玉吹簫後，湘靈鼓瑟时。","月邊丹桂落，风底白楊悲。","杂珮分泉戶，餘香出繐帷。","夜台飞镜匣，偏共掩蛾眉。"]', '诗', 'shi', '', NULL, '義川公主挽詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b98c6a-b5a2-4f87-b870-e72a11a73af6', '憶山中', '憶山中', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["春還不得還，家在最深山。","蕙圃泉澆濕，松窗月映閑。","薄田臨谷口，小職向人間。","去處但無事，重門深閉關。"]', '["春還不得還，家在最深山。","蕙圃泉澆濕，松窗月映闲。","薄田臨谷口，小職向人间。","去处但無事，重门深閉关。"]', '诗', 'shi', '', NULL, '憶山中 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912f6639-a774-4d02-8c17-07f6bc3b1d63', '送大理張卿', '送大理張卿', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["春色依依惜解攜，月卿今夜泊隋堤。","白沙洲上江籬長，綠樹村邊謝豹啼。","遷客比來無倚仗，故人相去隔雲泥。","越禽唯有南枝分，目送孤鴻飛向西。"]', '["春色依依惜解携，月卿今夜泊隋堤。","白沙洲上江籬长，綠樹村邊謝豹啼。","遷客比来無倚仗，故人相去隔云泥。","越禽唯有南枝分，目送孤鴻飞向西。"]', '诗', 'shi', '', NULL, '送大理張卿 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7732963-08cf-49ca-b903-6e954401ea56', '宿湖邊山寺', '宿湖邊山寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["羣峰過雨澗淙淙，松下扉扃白鶴雙。","香透經窗籠檜栢，雲生梵宇濕旛幢。","蒲團僧定風過席，葦岸漁歌月墮江。","誰悟此生同寂滅，老禪慧力得心降。"]', '["羣峰過雨澗淙淙，松下扉扃白鹤雙。","香透經窗籠檜栢，云生梵宇濕旛幢。","蒲團僧定风過席，葦岸漁歌月墮江。","誰悟此生同寂滅，老禪慧力得心降。"]', '诗', 'shi', '', NULL, '宿湖邊山寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a4211f-4bca-4693-b6a0-9c1e59eacffd', '湖南客中春望', '湖南客中春望', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鳴雁嘹嘹北向頻，淥波何處是通津。","風塵海內憐雙鬢，涕淚天涯慘一身。","故里音書應望絕，異鄉景物又更新。","便拋印綬從歸隱，吳渚香蓴漫吐春。"]', '["鳴雁嘹嘹北向頻，淥波何处是通津。","风塵海內怜雙鬢，涕泪天涯慘一身。","故里音书應望絕，異乡景物又更新。","便拋印綬從归隐，吳渚香蓴漫吐春。"]', '诗', 'shi', '', NULL, '湖南客中春望 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b813348-a5e1-4f1e-a814-6dfe8b8a09a9', '閑居懷舊', '闲居懷旧', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["日長鼓腹愛吾廬，洗竹澆花興有餘。","騷客空傳成相賦，晉人已負絕交書。","貧居謫所誰推轂，仕向侯門恥曳裾。","今日思來總皆罔，汗青功業又何如。"]', '["日长鼓腹愛吾廬，洗竹澆花兴有餘。","騷客空傳成相賦，晉人已負絕交书。","貧居謫所誰推轂，仕向侯门恥曳裾。","今日思来總皆罔，汗青功業又何如。"]', '诗', 'shi', '', NULL, '閑居懷舊 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85270f0-f1a5-49c5-b3be-21f62190dcda', '寄江南鶴林寺石冰上人', '寄江南鹤林寺石冰上人', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["山川重復出，心地闇相逢。","忽憶秋江月，如聞古寺鐘。","湖平南北岸，雲抱兩三峰。","定力超香象，真言攝毒龍。","風中何處鶴，石上幾年松。","爲報煙霞道，人間共不容。"]', '["山川重复出，心地闇相逢。","忽憶秋江月，如闻古寺鐘。","湖平南北岸，云抱兩三峰。","定力超香象，真言攝毒龙。","风中何处鹤，石上幾年松。","爲報煙霞道，人间共不容。"]', '诗', 'shi', '', NULL, '寄江南鶴林寺石冰上人 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc7bfd0-3b97-48a6-bdb9-eff5990d496f', '樂府', '乐府', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["暖谷春光至，宸遊近甸榮。","雲隨天仗轉，風入御簾輕。","翠蓋浮佳氣，朱樓倚太清。","朝臣冠劍退，宮女管絃迎。","細草承雕輦，繁花入幔城。","文房開聖藻，武衛宿天營。","玉醴隨觴至，銅壺逐漏行。","五星含土德，萬姓徹中聲。","親祀先崇典，躬推示勸耕。","國風新正樂，農器近消兵。","道德關河固，刑章日月明。","野人同鳥獸，率舞感昇平。"]', '["暖谷春光至，宸游近甸榮。","云隨天仗轉，风入御簾轻。","翠蓋浮佳氣，朱楼倚太清。","朝臣冠劍退，宮女管絃迎。","細草承雕輦，繁花入幔城。","文房开聖藻，武衛宿天營。","玉醴隨觴至，銅壺逐漏行。","五星含土德，万姓徹中声。","親祀先崇典，躬推示勸耕。","国风新正乐，農器近消兵。","道德关河固，刑章日月明。","野人同鸟獸，率舞感昇平。"]', '诗', 'shi', '', NULL, '樂府 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656c812a-f04c-4282-b01b-412200c4017e', '送從兄使新羅', '送從兄使新羅', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["六氣銅渾轉，三光玉律調。","河宮清奉賮，海嶽晏來朝。","地絕提封入，天平賜貢饒。","揚威輕破虜，柔服恥征遼。","曙色黃金闕，寒聲白鷺潮。","樓船非習戰，驄馬是嘉招。","帝女飛銜石，鮫人賣淚綃。","管寧雖不偶，徐市儻相邀。","獨島緣空翠，孤霞上泬寥。","蟾蜍同漢月，螮蝀異秦橋。","水豹橫吹浪，花鷹逈拂霄。","晨裝凌莽渺，夜泊記招搖。","幾路通員嶠，何山是沃焦。","颶風晴汨起，陰火暝潛燒。","鬢髮成新髻，人參長舊苗。","扶桑銜日近，析木帶津遙。","夢向愁中積，魂當別處銷。","臨川思結網，見彈欲求鴞。","共散羲和曆，誰差甲子朝。","滄波伏忠信，譯語辨謳謠。","疊鼓鯨鱗隱，陰帆鷁首飄。","南溟垂大翼，西海飲文鰩。","指景尋靈草，排雲聽洞簫。","封侯萬里外，未肯後班超。"]', '["六氣銅渾轉，三光玉律調。","河宮清奉賮，海嶽晏来朝。","地絕提封入，天平賜貢饒。","揚威轻破虜，柔服恥征遼。","曙色黄金闕，寒声白鷺潮。","楼船非習戰，驄马是嘉招。","帝女飞銜石，鮫人賣泪綃。","管寧雖不偶，徐市儻相邀。","独島緣空翠，孤霞上泬寥。","蟾蜍同漢月，螮蝀異秦橋。","水豹橫吹浪，花鷹逈拂霄。","晨裝凌莽渺，夜泊記招搖。","幾路通員嶠，何山是沃焦。","颶风晴汨起，陰火暝潛燒。","鬢髮成新髻，人參长旧苗。","扶桑銜日近，析木带津遙。","梦向愁中積，魂當別处銷。","臨川思結網，见彈欲求鴞。","共散羲和曆，誰差甲子朝。","滄波伏忠信，譯語辨謳謠。","叠鼓鯨鱗隐，陰帆鷁首飄。","南溟垂大翼，西海饮文鰩。","指景尋靈草，排云听洞簫。","封侯万里外，未肯後班超。"]', '诗', 'shi', '', NULL, '送從兄使新羅 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aec2246-5d1e-4a0d-87f5-69d4ec66321f', '山居即事', '山居即事', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["下泊降茅仙，蕭閑隱洞天。","楊君閑上法，司命駐流年。","崦合桃花水，窗分柳谷煙。","抱孫堪種樹，倚杖問耘田。","世事休相擾，浮名任一邊。","由來謝安石，不解飲靈泉。"]', '["下泊降茅仙，蕭闲隐洞天。","楊君闲上法，司命駐流年。","崦合桃花水，窗分柳谷煙。","抱孫堪種樹，倚杖问耘田。","世事休相擾，浮名任一邊。","由来謝安石，不解饮靈泉。"]', '诗', 'shi', '', NULL, '山居即事 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69e3e27-af82-404b-9a10-7c1525da1176', '題盧道土房', '題盧道土房', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["秋砧響落木，共坐茅君家。","唯見兩童子，門外汲井花。","空壇靜白日，神鼎飛丹砂。","麈尾拂霜草，金鈴搖霽霞。","上章塵世隔，看弈桐陰斜。","稽首問仙要，黃精堪餌花。"]', '["秋砧响落木，共坐茅君家。","唯见兩童子，门外汲井花。","空壇静白日，神鼎飞丹砂。","麈尾拂霜草，金鈴搖霽霞。","上章塵世隔，看弈桐陰斜。","稽首问仙要，黄精堪餌花。"]', '诗', 'shi', '', NULL, '題盧道土房 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eaa8b3b-92d7-413b-ad72-8c9ac3bd4f80', '夢後吟', '梦後吟', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["醉中還有夢，身外已無心。","明鏡唯知老，青山何處深。"]', '["醉中還有梦，身外已無心。","明镜唯知老，青山何处深。"]', '诗', 'shi', '', NULL, '夢後吟 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f50cc0-405e-4928-b678-b798c6a1f918', '題靈山寺', '題靈山寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["覺地本隨身，靈山重結因。","如何戰鳥佛，不化捕魚人。"]', '["覺地本隨身，靈山重結因。","如何戰鸟佛，不化捕鱼人。"]', '诗', 'shi', '', NULL, '題靈山寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3162017-25c7-4031-9ad0-67d9815e79f8', '題元陽觀舊讀書房贈李範', '題元陽观旧读书房贈李範', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["此觀十年遊，此房千里宿。","還來舊窗下，更取君書讀。"]', '["此观十年游，此房千里宿。","還来旧窗下，更取君书读。"]', '诗', 'shi', '', NULL, '題元陽觀舊讀書房贈李範 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('241d7f69-6f6d-4e96-8912-e36cfde5b3c6', '永嘉', '永嘉', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["東甌傳舊俗，風日江邊好。","何處樂神聲，夷歌出煙島。"]', '["东甌傳旧俗，风日江邊好。","何处乐神声，夷歌出煙島。"]', '诗', 'shi', '', NULL, '永嘉 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f54472-64d2-4fcb-8683-645283ded31f', '青弋江', '青弋江', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["淒清回泊夜，淪波激石響。","村邊草市橋，月下罟師網。"]', '["淒清回泊夜，淪波激石响。","村邊草市橋，月下罟師網。"]', '诗', 'shi', '', NULL, '青弋江 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('440821cb-eda0-4881-8f6a-3d7708c6c939', '聽山鷓鴣', '听山鷓鴣', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["誰家無春酒，何處無春鳥。","夜宿桃花村，踏歌接天曉。"]', '["誰家無春酒，何处無春鸟。","夜宿桃花村，踏歌接天晓。"]', '诗', 'shi', '', NULL, '聽山鷓鴣 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ff9642-7681-4ab7-8cfc-347a97ca7609', '山逕柳', '山逕柳', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["宛轉若遊絲，淺深栽綠崦。","年年立春後，即被啼鶯占。"]', '["宛轉若游絲，淺深栽綠崦。","年年立春後，即被啼鶯占。"]', '诗', 'shi', '', NULL, '山逕柳 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db96758-49ae-4251-afa8-2ec0cf0eaf66', '石上藤', '石上藤', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["空山無鳥跡，何物如人意。","委曲結繩文，離披草書字。"]', '["空山無鸟跡，何物如人意。","委曲結繩文，離披草书字。"]', '诗', 'shi', '', NULL, '石上藤 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3b38ef-9c86-4971-8fe5-6234163dce8f', '薜荔庵', '薜荔庵', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["薜荔作禪庵，重疊庵邊樹。","空山徑欲絕，也有人知處。"]', '["薜荔作禪庵，重叠庵邊樹。","空山徑欲絕，也有人知处。"]', '诗', 'shi', '', NULL, '薜荔庵 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974d29ec-068c-4022-81f5-ebdf6d8c4bc8', '芙蓉榭', '芙蓉榭', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["風擺蓮衣乾，月背鳥巢寒。","文魚翻亂葉，翠羽上危欄。"]', '["风擺蓮衣乾，月背鸟巢寒。","文鱼翻亂葉，翠羽上危欄。"]', '诗', 'shi', '', NULL, '芙蓉榭 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e98e72c8-c907-48b3-b776-24e4509cef4d', '欹松漪', '欹松漪', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["湛湛碧漣漪，老松欹側臥。","悠揚綠蘿影，下拂波紋破。"]', '["湛湛碧漣漪，老松欹側臥。","悠揚綠蘿影，下拂波紋破。"]', '诗', 'shi', '', NULL, '欹松漪 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2279418a-3ec1-46f2-beae-accd316bdf70', '焙茶塢', '焙茶塢', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["新茶已上焙，舊架憂生醭。","旋旋續新烟，呼兒劈寒木。"]', '["新茶已上焙，旧架憂生醭。","旋旋續新烟，呼兒劈寒木。"]', '诗', 'shi', '', NULL, '焙茶塢 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd65cf5-17cc-4e5c-91b3-390c249f056f', '彈琴谷', '彈琴谷', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["谷中誰彈琴，琴響谷冥寂。","因君扣商調，草蟲驚暗壁。"]', '["谷中誰彈琴，琴响谷冥寂。","因君扣商調，草蟲驚暗壁。"]', '诗', 'shi', '', NULL, '彈琴谷 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f0865f-ffe5-4671-9af7-8bd0f36df8fc', '白鷺汀', '白鷺汀', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["靃靡汀草碧，淋森鷺毛白。","夜起沙月中，思量捕魚策。"]', '["靃靡汀草碧，淋森鷺毛白。","夜起沙月中，思量捕鱼策。"]', '诗', 'shi', '', NULL, '白鷺汀 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f9a129-2459-4f81-bb53-efff3e35b551', '千松嶺', '千松嶺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["終日吟天風，有時天籟止。","問渠何旨意，恐落凡人耳。"]', '["終日吟天风，有时天籟止。","问渠何旨意，恐落凡人耳。"]', '诗', 'shi', '', NULL, '千松嶺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d9f2b6-dfd3-4ee9-8e0e-cbd31c2829e0', '黃菊灣', '黄菊灣', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["時菊凝曉露，露華滴秋灣。","仙人釀酒熟，醉裏飛空山。"]', '["时菊凝晓露，露华滴秋灣。","仙人釀酒熟，醉裏飞空山。"]', '诗', 'shi', '', NULL, '黃菊灣 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfccdbbd-1901-4bcb-a4fa-ee2ade092dd6', '臨平湖', '臨平湖', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["采藕平湖上，藕泥封藕節。","船影入荷香，莫衝蓮柄折。"]', '["采藕平湖上，藕泥封藕節。","船影入荷香，莫衝蓮柄折。"]', '诗', 'shi', '', NULL, '臨平湖 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519750da-fa09-4e97-a520-42a78269efaf', '山春洞', '山春洞', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["引燭踏仙泥，時時亂乳燕。","不知何道士，手把靈書卷。"]', '["引燭踏仙泥，时时亂乳燕。","不知何道士，手把靈书卷。"]', '诗', 'shi', '', NULL, '山春洞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf76ed00-9869-4859-893e-e63418e21d3e', '石竇泉', '石竇泉', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["吹沙復噴石，曲折仍圓旋。","野客漱流時，杯黏落花片。"]', '["吹沙复噴石，曲折仍圓旋。","野客漱流时，杯黏落花片。"]', '诗', 'shi', '', NULL, '石竇泉 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f16896a-462b-4830-a159-b81ca3323bf1', '古仙壇', '古仙壇', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["遠山誰放燒，疑是壇邊醮。","仙人錯下山，拍手壇邊笑。"]', '["远山誰放燒，疑是壇邊醮。","仙人錯下山，拍手壇邊笑。"]', '诗', 'shi', '', NULL, '古仙壇 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308cac64-243c-4581-8e4a-3274bb13e10c', '題山頂寺', '題山頂寺', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["遙聞林下語，知是經行所。","日暮香風時，諸天散花雨。"]', '["遙闻林下語，知是經行所。","日暮香风时，諸天散花雨。"]', '诗', 'shi', '', NULL, '題山頂寺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e7fcf3a-7b42-4ce0-8c84-aba8902c6d50', '天寶題壁', '天寶題壁', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["五十餘年別，伶俜道不行。","却來書處在，惆悵似前生。"]', '["五十餘年別，伶俜道不行。","却来书处在，惆悵似前生。"]', '诗', 'shi', '', NULL, '天寶題壁 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b24aaa0c-a199-45dd-a584-37b6b2582933', '哭李別駕', '哭李別駕', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故人行跡滅，秋草向南悲。","不欲頻回步，孀妻正哭時。"]', '["故人行跡滅，秋草向南悲。","不欲頻回步，孀妻正哭时。"]', '诗', 'shi', '', NULL, '哭李別駕 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf395d16-5365-4b0f-91d0-adeadd0ffc7c', '春雨不聞百舌', '春雨不闻百舌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["百舌春來啞，愁人共待晴。","不關秋水事，飲恨亦無聲。"]', '["百舌春来啞，愁人共待晴。","不关秋水事，饮恨亦無声。"]', '诗', 'shi', '', NULL, '春雨不聞百舌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57801b63-5db7-44fa-af5b-09a496781815', '憶鄱陽舊遊', '憶鄱陽旧游', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["悠悠南國思，夜向江南泊。","楚客斷腸時，月明楓子落。"]', '["悠悠南国思，夜向江南泊。","楚客斷腸时，月明楓子落。"]', '诗', 'shi', '', NULL, '憶鄱陽舊遊 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501b9fd1-e492-49f4-a619-e121bb140b6f', '春懷', '春懷', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["園鶯啼已倦，樹樹隕香紅。","不是春相背，當由己自翁。"]', '["园鶯啼已倦，樹樹隕香紅。","不是春相背，當由己自翁。"]', '诗', 'shi', '', NULL, '春懷 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ec0b55-2f4e-4a6a-b5c1-90d7454d6000', '洛陽陌二首 一', '洛陽陌二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鶯聲滿御隄，隄柳拂絲齊。","風送名花落，香紅襯馬蹄。"]', '["鶯声满御隄，隄柳拂絲齊。","风送名花落，香紅襯马蹄。"]', '诗', 'shi', '', NULL, '洛陽陌二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e346158-a098-48cb-8486-8d7f14e0677e', '洛陽陌二首 二', '洛陽陌二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["珂珮逐鳴騶，王孫結伴遊。","金丸落飛鳥，乘興醉青樓。"]', '["珂珮逐鳴騶，王孫結伴游。","金丸落飞鸟，乘兴醉青楼。"]', '诗', 'shi', '', NULL, '洛陽陌二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3363f3-d276-4f9a-985e-37f2db392800', '寄淮上柳十三', '寄淮上柳十三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["葦蕭中闢戶，相映綠淮流。","莫訝春潮闊，鷗邊可泊舟。"]', '["葦蕭中闢戶，相映綠淮流。","莫訝春潮闊，鷗邊可泊舟。"]', '诗', 'shi', '', NULL, '寄淮上柳十三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914621ec-54c6-4368-b43a-4a5d39876a94', '送李泌', '送李泌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["昔別吳堤雨，春帆去較遲。","江波千里綠，囗囗囗囗囗。"]', '["昔別吳堤雨，春帆去較遲。","江波千里綠，囗囗囗囗囗。"]', '诗', 'shi', '', NULL, '送李泌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9aa2416-09f6-423b-a511-98bffbd15e0a', '山中夜宿', '山中夜宿', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["涼月掛層峰，蘿林落葉重。","掩關深畏虎，風起撼長松。"]', '["涼月掛層峰，蘿林落葉重。","掩关深畏虎，风起撼长松。"]', '诗', 'shi', '', NULL, '山中夜宿 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7b685b-e1a3-434e-9ddc-ecaa72b92591', '登樓', '登楼', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["高閣成長望，江流雁呌哀。","淒涼故吳事，麋鹿走荒臺。"]', '["高閣成长望，江流雁呌哀。","淒涼故吳事，麋鹿走荒台。"]', '诗', 'shi', '', NULL, '登樓 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683523a6-d986-4085-9145-9b15d612bd82', '江上', '江上', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["江清白鳥斜，蕩槳罥蘋花。","聽唱菱歌晚，迴塘月照沙。"]', '["江清白鸟斜，蕩槳罥蘋花。","听唱菱歌晚，迴塘月照沙。"]', '诗', 'shi', '', NULL, '江上 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967ad30d-c71b-4dd8-babf-61fb8022f3d9', '溪上', '溪上', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["採蓮溪上女，舟小怯搖風。","驚起鴛鴦宿，水雲撩亂紅。"]', '["採蓮溪上女，舟小怯搖风。","驚起鴛鴦宿，水云撩亂紅。"]', '诗', 'shi', '', NULL, '溪上 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da3a0129-eb3f-4e72-acf6-7c0d6ca402a9', '田家', '田家', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["帶水摘禾穗，夜擣具晨炊。","縣帖取社長，嗔怪見官遲。"]', '["带水摘禾穗，夜擣具晨炊。","縣帖取社长，嗔怪见官遲。"]', '诗', 'shi', '', NULL, '田家 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d171c992-eedc-4dda-9f9d-4b4088ff29df', '宿山中僧', '宿山中僧', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不爇香爐煙，蒲團坐如鐵。","嘗想同夜禪，風墮松頂雪。"]', '["不爇香爐煙，蒲團坐如鐵。","嘗想同夜禪，风墮松頂雪。"]', '诗', 'shi', '', NULL, '宿山中僧 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('304a41de-8c12-45a4-8c82-e5b1885e90d3', '梅灣', '梅灣', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["白石盤盤磴，清香樹樹梅。","山深不吟賞，[辜]負委蒼苔。"]', '["白石盤盤磴，清香樹樹梅。","山深不吟賞，[辜]負委蒼苔。"]', '诗', 'shi', '', NULL, '梅灣 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef28160-09b6-4f5e-9592-d6d4b9a3a797', '思歸', '思归', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不能經綸大經，甘作草莽閑臣。","青[瑣]應須長別，白雲漫與相親。"]', '["不能經綸大經，甘作草莽闲臣。","青[瑣]應須长別，白云漫與相親。"]', '诗', 'shi', '', NULL, '思歸 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64bd69e4-ef0a-4190-b60f-e33856617f88', '歸山作', '归山作', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["心事數莖白髮，生涯一片青山。","空林有雪相待，古道無人獨還。"]', '["心事數莖白髮，生涯一片青山。","空林有雪相待，古道無人独還。"]', '诗', 'shi', '', NULL, '歸山作 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684e16f6-839b-4600-b680-996ac541ced0', '過山農家', '過山農家', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["板橋人渡泉聲，茆簷日午雞鳴。","莫嗔焙茶煙暗，却喜曬穀天晴。"]', '["板橋人渡泉声，茆簷日午雞鳴。","莫嗔焙茶煙暗，却喜曬穀天晴。"]', '诗', 'shi', '', NULL, '過山農家 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3118709c-e27c-4f00-ac3e-1fd2cf0dda53', '代佳人贈別', '代佳人贈別', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["萬里行人欲渡溪，千行珠淚滴爲泥。","已成殘夢隨君去，猶有驚烏半夜啼。"]', '["万里行人欲渡溪，千行珠泪滴爲泥。","已成殘梦隨君去，猶有驚烏半夜啼。"]', '诗', 'shi', '', NULL, '代佳人贈別 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad10840a-e59a-4a43-801e-2b622abe2290', '憶故園', '憶故园', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["惆悵多山人復稀，杜鵑啼處淚霑衣。","故園此去千餘里，春夢猶能夜夜歸。"]', '["惆悵多山人复稀，杜鵑啼处泪霑衣。","故园此去千餘里，春梦猶能夜夜归。"]', '诗', 'shi', '', NULL, '憶故園 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a18f10-005c-4200-ba56-70b7e35adea4', '題葉道士山房', '題葉道士山房', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["水邊垂柳赤欄橋，洞裏仙人碧玉簫。","近得麻姑音信否，潯陽江上不通潮。"]', '["水邊垂柳赤欄橋，洞裏仙人碧玉簫。","近得麻姑音信否，潯陽江上不通潮。"]', '诗', 'shi', '', NULL, '題葉道士山房 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcea24d-248f-494b-8c94-99eae104160d', '送李秀才入京', '送李秀才入京', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["五湖秋葉滿行船，八月靈槎欲上天。","君向長安余適越，獨登秦望望秦川。"]', '["五湖秋葉满行船，八月靈槎欲上天。","君向长安余適越，独登秦望望秦川。"]', '诗', 'shi', '', NULL, '送李秀才入京 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7b7b24-a1d7-4256-9f30-7e745c4caeb5', '越中席上看弄老人', '越中席上看弄老人', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不到山陰十二春，鏡中相見白頭新。","此生不復爲年少，今日從他弄老人。"]', '["不到山陰十二春，镜中相见白头新。","此生不复爲年少，今日從他弄老人。"]', '诗', 'shi', '', NULL, '越中席上看弄老人 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a6694c-e3be-4400-8477-aae52dd95da8', '聽劉安唱歌', '听劉安唱歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["子夜新聲何處傳，悲翁更憶太平年。","即今法曲無人唱，已逐霓裳飛上天。"]', '["子夜新声何处傳，悲翁更憶太平年。","即今法曲無人唱，已逐霓裳飞上天。"]', '诗', 'shi', '', NULL, '聽劉安唱歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9747c4d-c1e5-4d2c-8bce-10889bba41b4', '櫻桃曲', '櫻桃曲', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["百舌猶來上苑花，遊人獨自憶京華。","遙知寢廟嘗新後，敕賜櫻桃向幾家。"]', '["百舌猶来上苑花，游人独自憶京华。","遙知寢廟嘗新後，敕賜櫻桃向幾家。"]', '诗', 'shi', '', NULL, '櫻桃曲 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1acbe7fa-59b9-45be-8a64-fafc21bcf140', '山中', '山中', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["野人愛向山中宿，況在葛洪丹井西。","庭前有箇長松樹，夜半子規來上啼。"]', '["野人愛向山中宿，況在葛洪丹井西。","庭前有箇长松樹，夜半子規来上啼。"]', '诗', 'shi', '', NULL, '山中 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa45c93-0eca-4b64-b800-f0d6722ec3a0', '贈朱放', '贈朱放', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["野客歸時無四鄰，黔婁別久案常貧。","漁樵舊路不堪入，何處空山猶有人。"]', '["野客归时無四鄰，黔婁別久案常貧。","漁樵旧路不堪入，何处空山猶有人。"]', '诗', 'shi', '', NULL, '贈朱放 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66312123-6671-49e5-a4ed-790959f4157e', '江村亂後', '江村亂後', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["江村日暮尋遺老，江水東流橫浩浩。","竹裏閑窗不見人，門前舊路生青草。"]', '["江村日暮尋遺老，江水东流橫浩浩。","竹裏闲窗不见人，门前旧路生青草。"]', '诗', 'shi', '', NULL, '江村亂後 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15dcb3cf-f2c9-4448-9a65-24a31619a142', '望簡寂觀', '望簡寂观', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["青嶂青溪直復斜，白雞白犬到人家。","仙人住在最高處，向晚春泉流白花。"]', '["青嶂青溪直复斜，白雞白犬到人家。","仙人住在最高处，向晚春泉流白花。"]', '诗', 'shi', '', NULL, '望簡寂觀 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b0b4e67-a813-428e-9938-88083f5cda7a', '五兩歌送張夏', '五兩歌送張夏', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["竿頭五兩風褭褭，水上雲帆逐飛鳥。","送君初出揚州時，靄靄曈曈江溢曉。"]', '["竿头五兩风褭褭，水上云帆逐飞鸟。","送君初出揚州时，靄靄曈曈江溢晓。"]', '诗', 'shi', '', NULL, '五兩歌送張夏 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a444eb74-e3d9-47b8-abce-2b847a91e708', '臨海所居三首 一', '臨海所居三首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["此是昔年征戰處，曾經永日絕人行。","千家寂寂對流水，唯有汀洲春草生。"]', '["此是昔年征戰处，曾經永日絕人行。","千家寂寂对流水，唯有汀洲春草生。"]', '诗', 'shi', '', NULL, '臨海所居三首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8109695-edde-4e9e-826a-eb98ff50bc49', '臨海所居三首 二', '臨海所居三首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["此去臨溪不是遙，樓中望見赤城標。","不知疊嶂重霞裏，更有何人度石橋。"]', '["此去臨溪不是遙，楼中望见赤城標。","不知叠嶂重霞裏，更有何人度石橋。"]', '诗', 'shi', '', NULL, '臨海所居三首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f78a46d-939f-4a36-ae0e-c8b1ea54d683', '臨海所居三首 三', '臨海所居三首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["家在雙峰蘭若邊，一聲秋磬發孤煙。","山連極浦鳥飛盡，月上青林人未眠。"]', '["家在雙峰蘭若邊，一声秋磬發孤煙。","山連極浦鸟飞尽，月上青林人未眠。"]', '诗', 'shi', '', NULL, '臨海所居三首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8035a2d8-6e7f-4045-93f3-e689eb83f6c8', '聽角思歸', '听角思归', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故園黃葉滿青苔，夢後城頭曉角哀。","此夜斷腸人不見，起行殘日影徘徊。"]', '["故园黄葉满青苔，梦後城头晓角哀。","此夜斷腸人不见，起行殘日影徘徊。"]', '诗', 'shi', '', NULL, '聽角思歸 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b86f9b3-708e-4939-b35a-5292571f9406', '酬柳相公', '酬柳相公', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["天下如今已太平，相公何事喚狂生。","箇身恰似籠中鶴，東望滄溟呌數聲。"]', '["天下如今已太平，相公何事喚狂生。","箇身恰似籠中鹤，东望滄溟呌數声。"]', '诗', 'shi', '', NULL, '酬柳相公 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a116bb6f-30ad-48b4-ac26-e759aa68c4aa', '題明霞臺', '題明霞台', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["野人本自不求名，欲向山中過一生。","莫嫌憔悴無知己，別有煙霞似弟兄。"]', '["野人本自不求名，欲向山中過一生。","莫嫌憔悴無知己，別有煙霞似弟兄。"]', '诗', 'shi', '', NULL, '題明霞臺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1cfb449-4657-4634-9823-3eb97333f4fa', '哭絢法師', '哭絢法師', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["楚客停橈欲問誰，白沙江草麴塵絲。","生公手種殿前樹，唯有花開鶗鴂悲。"]', '["楚客停橈欲问誰，白沙江草麴塵絲。","生公手種殿前樹，唯有花开鶗鴂悲。"]', '诗', 'shi', '', NULL, '哭絢法師 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e37fe7-24cf-41a3-aab4-66398019be30', '送柳宜城葬', '送柳宜城葬', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鳴笳已逐春風咽，匹馬猶依舊路嘶。","遙望柳家門外樹，恐聞黃鳥向人啼。"]', '["鳴笳已逐春风咽，匹马猶依旧路嘶。","遙望柳家门外樹，恐闻黄鸟向人啼。"]', '诗', 'shi', '', NULL, '送柳宜城葬 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298ebbb2-b6d6-4254-a074-1b5b65ffcfe8', '宮詞五首 一', '宮词五首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["禁柳煙中聞曉烏，風吹玉漏盡銅壺。","內官先向蓬萊殿，金合開香瀉御鑪。"]', '["禁柳煙中闻晓烏，风吹玉漏尽銅壺。","內官先向蓬萊殿，金合开香瀉御鑪。"]', '诗', 'shi', '', NULL, '宮詞五首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9f9e4d-aa34-496e-89cf-cfef61efa89d', '宮詞五首 二', '宮词五首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉樓天半起笙歌，風送宮嬪笑語和。","月殿影開聞夜漏，水精簾卷近銀河。"]', '["玉楼天半起笙歌，风送宮嬪笑語和。","月殿影开闻夜漏，水精簾卷近銀河。"]', '诗', 'shi', '', NULL, '宮詞五首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3498d3d4-04ed-4195-86e4-6cdaf4288a5b', '宮詞五首 三', '宮词五首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉階容衛宿千官，風獵青旂曉仗寒。","侍女先來薦瓊蘂，露漿新下九霄盤。"]', '["玉階容衛宿千官，风獵青旂晓仗寒。","侍女先来薦瓊蘂，露漿新下九霄盤。"]', '诗', 'shi', '', NULL, '宮詞五首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a533a0-196f-47cf-ad55-33711b796415', '宮詞五首 四', '宮词五首 四', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["九重天樂降神仙，步舞分行踏錦筵。","嘈囋一聲鐘鼓歇，萬人樓下拾金錢。"]', '["九重天乐降神仙，步舞分行踏錦筵。","嘈囋一声鐘鼓歇，万人楼下拾金錢。"]', '诗', 'shi', '', NULL, '宮詞五首 四 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cb803f-b016-450c-a5b3-70d95155b0ef', '宮詞五首 五', '宮词五首 五', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["金吾持戟護新簷，天樂聲傳萬姓瞻。","樓上美人相倚看，紅妝透出水精簾。"]', '["金吾持戟護新簷，天乐声傳万姓瞻。","楼上美人相倚看，紅妝透出水精簾。"]', '诗', 'shi', '', NULL, '宮詞五首 五 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96d878f-bb81-4d27-a814-c89692c7f34b', '尋桃花嶺潘三姑臺', '尋桃花嶺潘三姑台', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["桃花嶺上覺天低，人上青山馬隔溪。","行到三姑學仙處，還有劉阮二郎迷。"]', '["桃花嶺上覺天低，人上青山马隔溪。","行到三姑学仙处，還有劉阮二郎迷。"]', '诗', 'shi', '', NULL, '尋桃花嶺潘三姑臺 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7592bdb-3362-44e0-ac0d-0462b6355554', '夜中望仙觀', '夜中望仙观', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["日暮銜花飛鳥還，月明溪上見青山。","遙知玉女窗前樹，不是仙人不得攀。"]', '["日暮銜花飞鸟還，月明溪上见青山。","遙知玉女窗前樹，不是仙人不得攀。"]', '诗', 'shi', '', NULL, '夜中望仙觀 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50edf1b-c48c-490f-adbf-847c232e9b05', '送李侍御往吳興', '送李侍御往吳兴', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["世間只有情難說，今夜應無不醉人。","若向洞庭山下過，暗知澆瀝聖姑神。"]', '["世间只有情难说，今夜應無不醉人。","若向洞庭山下過，暗知澆瀝聖姑神。"]', '诗', 'shi', '', NULL, '送李侍御往吳興 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b4dc84-3bab-4e4d-8477-23567ca52a23', '奉和韓晉公晦日呈諸判官', '奉和韓晉公晦日呈諸判官', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["江南無處不聞歌，晦日中軍樂更多。","不是風光催柳色，却緣威令動陽和。"]', '["江南無处不闻歌，晦日中軍乐更多。","不是风光催柳色，却緣威令动陽和。"]', '诗', 'shi', '', NULL, '奉和韓晉公晦日呈諸判官 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7ba4c1-33d6-45cc-a71b-854e42a2e9df', '子規', '子規', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["杜宇冤亡積有時，年年啼血動人悲。","若敎恨魄皆能化，何樹何山着子規。"]', '["杜宇冤亡積有时，年年啼血动人悲。","若敎恨魄皆能化，何樹何山着子規。"]', '诗', 'shi', '', NULL, '子規 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03734aa5-4f4e-4577-90ca-317ca63d77c6', '海鷗詠', '海鷗詠', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["萬里飛來爲客鳥，曾蒙丹鳳借枝柯。","一朝鳳去梧桐死，滿目鴟鳶奈爾何。"]', '["万里飞来爲客鸟，曾蒙丹鳳借枝柯。","一朝鳳去梧桐死，满目鴟鳶奈爾何。"]', '诗', 'shi', '', NULL, '海鷗詠 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21455ef-3df1-4c89-b02b-369890f2edf9', '贈韋清將軍', '贈韋清將軍', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["身執金吾主禁兵，腰間寶劍重橫行。","接輿亦是狂歌者，更就將軍乞一聲。"]', '["身執金吾主禁兵，腰间寶劍重橫行。","接輿亦是狂歌者，更就將軍乞一声。"]', '诗', 'shi', '', NULL, '贈韋清將軍 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082f73c5-c6bc-4256-841c-13fb732f11bb', '贈僧二首 一', '贈僧二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["家住義興東舍溪，溪邊莎草雨無泥。","上人一向心入定，春鳥年年空自啼。"]', '["家住義兴东舍溪，溪邊莎草雨無泥。","上人一向心入定，春鸟年年空自啼。"]', '诗', 'shi', '', NULL, '贈僧二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d7b6c7-7471-422c-8bdc-353b98ddf6ea', '贈僧二首 二', '贈僧二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["出頭皆是新年少，何處能容老病翁。","更把浮榮喻生滅，世間無事不虛空。"]', '["出头皆是新年少，何处能容老病翁。","更把浮榮喻生滅，世间無事不虛空。"]', '诗', 'shi', '', NULL, '贈僧二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068ebef7-dc84-4cbd-bb7e-77a9d4cebd4b', '登樓望水', '登楼望水', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鳥啼花發柳含煙，擲却風光憶少年。","更上高樓望江水，故鄉何處一歸船。"]', '["鸟啼花發柳含煙，擲却风光憶少年。","更上高楼望江水，故乡何处一归船。"]', '诗', 'shi', '', NULL, '登樓望水 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0957b5-dd32-4391-b11c-cef4e57019c3', '湖中', '湖中', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["青草湖邊日色低，黃茅嶂裏鷓鴣啼。","丈夫飄蕩今如此，一曲長歌楚水西。"]', '["青草湖邊日色低，黄茅嶂裏鷓鴣啼。","丈夫飄蕩今如此，一曲长歌楚水西。"]', '诗', 'shi', '', NULL, '湖中 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b64c656c-1346-4fce-9667-57d2472ab4f2', '歲日作', '歲日作', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["不覺老將春共至，更悲攜手幾人全。","還丹寂寞羞明鏡，手把屠蘇讓少年。"]', '["不覺老將春共至，更悲携手幾人全。","還丹寂寞羞明镜，手把屠蘇讓少年。"]', '诗', 'shi', '', NULL, '歲日作 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b254dd-2016-446f-98cf-d55786e671b0', '山中贈客', '山中贈客', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["山中好處無人別，澗梅僞作山中雪。","野客相逢夜不眠，山中童子燒松節。"]', '["山中好处無人別，澗梅僞作山中雪。","野客相逢夜不眠，山中童子燒松節。"]', '诗', 'shi', '', NULL, '山中贈客 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a430fc14-8402-4e73-a6c6-b46041986d07', '王郎中妓席五詠 箜篌', '王郎中妓席五詠 箜篌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉作搔頭金步搖，高張苦調響連宵。","欲知寫盡相思夢，度水尋雲不用橋。"]', '["玉作搔头金步搖，高張苦調响連宵。","欲知寫尽相思梦，度水尋云不用橋。"]', '诗', 'shi', '', NULL, '王郎中妓席五詠 箜篌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0526a65-b0e0-47d4-b141-43443bc76606', '王郎中妓席五詠 舞', '王郎中妓席五詠 舞', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["汗浥新裝畫不成，絲催急節舞衣輕。","落花遶樹疑無影，回雪從風暗有情。"]', '["汗浥新裝畫不成，絲催急節舞衣轻。","落花遶樹疑無影，回雪從风暗有情。"]', '诗', 'shi', '', NULL, '王郎中妓席五詠 舞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa28008b-e95f-4b32-a869-12a16f34d987', '王郎中妓席五詠 歌', '王郎中妓席五詠 歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["柳拂青樓花滿衣，能歌宛轉世應稀。","空中幾處聞清響，欲遶行雲不遣飛。"]', '["柳拂青楼花满衣，能歌宛轉世應稀。","空中幾处闻清响，欲遶行云不遣飞。"]', '诗', 'shi', '', NULL, '王郎中妓席五詠 歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f5c7c4-3fe6-408c-8865-db6c31ab518b', '王郎中妓席五詠 箏', '王郎中妓席五詠 箏', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["秦聲楚調怨無窮，隴水胡笳咽復通。","莫遣黃鶯花裏囀，參差撩亂妬春風。"]', '["秦声楚調怨無窮，隴水胡笳咽复通。","莫遣黄鶯花裏囀，參差撩亂妬春风。"]', '诗', 'shi', '', NULL, '王郎中妓席五詠 箏 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f228b77d-1c21-478f-a6f1-59ed877adc14', '王郎中妓席五詠 笙', '王郎中妓席五詠 笙', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["欲寫人間離別心，須聽鳴鳳似龍吟。","江南曲盡歸何處，洞水山雲知淺深。"]', '["欲寫人间離別心，須听鳴鳳似龙吟。","江南曲尽归何处，洞水山云知淺深。"]', '诗', 'shi', '', NULL, '王郎中妓席五詠 笙 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50defe07-70d9-4bea-8dc8-f6258bbec03e', '送李山人還玉溪', '送李山人還玉溪', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["好鳥共鳴臨水樹，幽人獨欠買山錢。","若爲種得千竿竹，引取君家一眼泉。"]', '["好鸟共鳴臨水樹，幽人独欠買山錢。","若爲種得千竿竹，引取君家一眼泉。"]', '诗', 'shi', '', NULL, '送李山人還玉溪 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797eb1a3-4a26-4075-adb0-52b09464228b', '送少微上人還鹿門', '送少微上人還鹿门', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["少微不向吳中隱，爲箇生緣在鹿門。","行入漢江秋月色，襄陽耆舊幾人存。"]', '["少微不向吳中隐，爲箇生緣在鹿门。","行入漢江秋月色，襄陽耆旧幾人存。"]', '诗', 'shi', '', NULL, '送少微上人還鹿門 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a44af03-7327-40d4-88c0-f09fb6bbd5db', '宿昭應', '宿昭應', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["武帝祈靈太乙壇，新豐樹色繞千官。","那知今夜長生殿，獨閉山門月影寒。"]', '["武帝祈靈太乙壇，新豐樹色繞千官。","那知今夜长生殿，独閉山门月影寒。"]', '诗', 'shi', '', NULL, '宿昭應 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05dcdf54-0d4d-4d22-a2c8-916b38ba00e4', '題琅邪上方', '題琅邪上方', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["東晉王家在此溪，南朝樹色隔窗低。","碑沈字滅昔人遠，谷鳥猶向寒花啼。"]', '["东晉王家在此溪，南朝樹色隔窗低。","碑沈字滅昔人远，谷鸟猶向寒花啼。"]', '诗', 'shi', '', NULL, '題琅邪上方 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b75367f-b4bb-48da-a7fa-6d98d3d95322', '安仁港口望仙人城', '安仁港口望仙人城', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["樓臺采翠遠分明，聞說仙家在此城。","欲上仙城無路上，水邊花裏有人聲。"]', '["楼台采翠远分明，闻说仙家在此城。","欲上仙城無路上，水邊花裏有人声。"]', '诗', 'shi', '', NULL, '安仁港口望仙人城 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22936d54-909d-468d-bbb0-c5268bbdf0d6', '寄祕書包監', '寄祕书包監', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["一別長安路幾千，遙知舊日主人憐。","賈生只是三年謫，獨自無才已四年。"]', '["一別长安路幾千，遙知旧日主人怜。","賈生只是三年謫，独自無才已四年。"]', '诗', 'shi', '', NULL, '寄祕書包監 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf75254e-a399-47c0-b188-79c3b0be396b', '小孤山', '小孤山', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["古廟楓林江水邊，寒鴉接飯雁橫天。","大孤山遠小孤出，月照洞庭歸客船。"]', '["古廟楓林江水邊，寒鴉接飯雁橫天。","大孤山远小孤出，月照洞庭归客船。"]', '诗', 'shi', '', NULL, '小孤山 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d46a51d-3295-440e-88f0-1a2985aae729', '送李秀才遊嵩山', '送李秀才游嵩山', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["嵩山石壁挂飛流，無限神仙在上頭。","采得新詩題石壁，老人惆悵不同遊。"]', '["嵩山石壁挂飞流，無限神仙在上头。","采得新诗題石壁，老人惆悵不同游。"]', '诗', 'shi', '', NULL, '送李秀才遊嵩山 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9559b3b8-a288-47a0-9494-2be54f934ab5', '從剡溪至赤城', '從剡溪至赤城', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["靈溪宿處接靈山，窈映高樓向月閑。","夜半鶴聲殘夢裏，猶疑琴曲洞房閒。"]', '["靈溪宿处接靈山，窈映高楼向月闲。","夜半鹤声殘梦裏，猶疑琴曲洞房閒。"]', '诗', 'shi', '', NULL, '從剡溪至赤城 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c4e93c-38d0-4247-a7cc-b19c6ee77743', '葉上題詩從苑中流出', '葉上題诗從苑中流出', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["花落深宮鶯亦悲，上陽宮女斷腸時。","君恩不閉東流水，葉上題詩寄與誰。"]', '["花落深宮鶯亦悲，上陽宮女斷腸时。","君恩不閉东流水，葉上題诗寄與誰。"]', '诗', 'shi', '', NULL, '葉上題詩從苑中流出 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74cd7154-770a-41c4-b55d-1e27ac1ba628', '崦裏桃花', '崦裏桃花', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["崦裏桃花逢女冠，林間杏葉落仙壇。","老人方授上清籙，夜聽步虛山月寒。"]', '["崦裏桃花逢女冠，林间杏葉落仙壇。","老人方授上清籙，夜听步虛山月寒。"]', '诗', 'shi', '', NULL, '崦裏桃花 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3186f0a-f6a1-4d01-81a2-f3533de1826d', '聽子規', '听子規', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["棲霞山中子規鳥，口邊血出啼不了。","山僧後夜初出定，聞似不聞山月曉。"]', '["棲霞山中子規鸟，口邊血出啼不了。","山僧後夜初出定，闻似不闻山月晓。"]', '诗', 'shi', '', NULL, '聽子規 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7343f60d-c51e-44a0-9b6d-30fb63783ab0', '竹枝曲', '竹枝曲', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["帝子蒼梧不復歸，洞庭葉下荆雲飛。","巴人夜唱竹枝後，腸斷曉猿聲漸稀。"]', '["帝子蒼梧不复归，洞庭葉下荆云飞。","巴人夜唱竹枝後，腸斷晓猿声漸稀。"]', '诗', 'shi', '', NULL, '竹枝曲 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee152d89-4839-4572-b606-46d8c3a1d744', '尋僧二首 一', '尋僧二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["方丈玲瓏花竹閑，已將心印出人閒。","家家門外長安道，何處相逢是寶山。"]', '["方丈玲瓏花竹闲，已將心印出人閒。","家家门外长安道，何处相逢是寶山。"]', '诗', 'shi', '', NULL, '尋僧二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e310a1e-e27f-4316-854a-0a0543fa9e85', '尋僧二首 二', '尋僧二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["彌天釋子本高情，往往山中獨自行。","莫怪狂人游楚國，蓮花只在淤泥生。"]', '["彌天釋子本高情，往往山中独自行。","莫怪狂人游楚国，蓮花只在淤泥生。"]', '诗', 'shi', '', NULL, '尋僧二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02430665-d8b1-4830-8b51-744091ebcc22', '桃花曲', '桃花曲', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["魏帝宮人舞鳳樓，隋家天子泛龍舟。","君王夜醉春眠晏，不覺桃花逐水流。"]', '["魏帝宮人舞鳳楼，隋家天子泛龙舟。","君王夜醉春眠晏，不覺桃花逐水流。"]', '诗', 'shi', '', NULL, '桃花曲 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e40685-01eb-443a-a7e7-e6d99f61bed8', '贈遠', '贈远', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["暫出河邊思遠道，却來窗下聽新鶯。","故人一別幾時見，春草還從舊處生。"]', '["暫出河邊思远道，却来窗下听新鶯。","故人一別幾时见，春草還從旧处生。"]', '诗', 'shi', '', NULL, '贈遠 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ede8d1-4ba1-4b59-9021-bddf471b00e4', '早春思歸有唱竹枝歌者坐中下淚', '早春思归有唱竹枝歌者坐中下泪', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["渺渺春生楚水波，楚人齊唱竹枝歌。","與君皆是思歸客，拭淚看花奈老何。"]', '["渺渺春生楚水波，楚人齊唱竹枝歌。","與君皆是思归客，拭泪看花奈老何。"]', '诗', 'shi', '', NULL, '早春思歸有唱竹枝歌者坐中下淚 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9bbd52c-6e49-44de-94c2-6b2ca60c265c', '送郭秀才', '送郭秀才', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故人曾任丹徒令，買得青山擬獨耕。","不作草堂招遠客，却將垂柳借啼鶯。"]', '["故人曾任丹徒令，買得青山擬独耕。","不作草堂招远客，却將垂柳借啼鶯。"]', '诗', 'shi', '', NULL, '送郭秀才 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5372fb27-5a56-4669-85c2-1c418a0f2330', '宮詞', '宮词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["長樂宮連上苑春，玉樓金殿豔歌新。","君門一入無由出，唯有宮鶯得見人。"]', '["长乐宮連上苑春，玉楼金殿豔歌新。","君门一入無由出，唯有宮鶯得见人。"]', '诗', 'shi', '', NULL, '宮詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78640ca3-a8de-4f88-bdf6-543291b41a66', '悼稚', '悼稚', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["稚子比來騎竹馬，猶疑只在屋東西。","莫言道者無悲事，曾聽巴猿向月啼。"]', '["稚子比来騎竹马，猶疑只在屋东西。","莫言道者無悲事，曾听巴猿向月啼。"]', '诗', 'shi', '', NULL, '悼稚 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0fa394-0bb8-419b-8dd8-1e027ec081a3', '山僧蘭若', '山僧蘭若', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["絕頂茅庵老此生，寒雲孤木伴經行。","世人那得知幽徑，遙向青峰禮磬聲。"]', '["絕頂茅庵老此生，寒云孤木伴經行。","世人那得知幽徑，遙向青峰禮磬声。"]', '诗', 'shi', '', NULL, '山僧蘭若 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b0116c-2801-4d4c-a723-8ca10f1c4f92', '句', '句', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["崦合桃花水，窗鳴柳谷泉。","頹垣化爲陂，陸地堪乘舟。","汀洲渺渺江籬短，疑是疑非兩斷腸。","巫峽朝雲暮不歸，洞庭春水晴空滿。","龍吟四澤欲興雨，鳳引九雛警宿烏。","新婦磯邊月明，女兒浦口潮平。"]', '["崦合桃花水，窗鳴柳谷泉。","頹垣化爲陂，陸地堪乘舟。","汀洲渺渺江籬短，疑是疑非兩斷腸。","巫峽朝云暮不归，洞庭春水晴空满。","龙吟四澤欲兴雨，鳳引九雛警宿烏。","新婦磯邊月明，女兒浦口潮平。"]', '诗', 'shi', '', NULL, '句 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e61bd73-2066-410f-88f8-ec41840eeee7', '發南康夜泊灨石中', '發南康夜泊灨石中', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["倦客乘歸舟，春溪杳將暮。","羣林結暝色，孤泊有佳趣。","夜山轉長江，赤月吐深樹。","颯颯松上吹，泛泛花間露。","險石俯潭渦，跳湍礙沿泝。","豈唯垂堂戒，兼以臨深懼。","稍出回雁峰，明登斬蛟柱。","連雲向重山，杳未見鍾路。"]', '["倦客乘归舟，春溪杳將暮。","羣林結暝色，孤泊有佳趣。","夜山轉长江，赤月吐深樹。","颯颯松上吹，泛泛花间露。","險石俯潭渦，跳湍礙沿泝。","豈唯垂堂戒，兼以臨深懼。","稍出回雁峰，明登斬蛟柱。","連云向重山，杳未见鍾路。"]', '诗', 'shi', '', NULL, '發南康夜泊灨石中 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209afb70-f536-43bb-ae56-c7570238e31b', '過王山人舊居', '過王山人旧居', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["故宅春山中，來逢夕陽入。","汲少井味變，開稀戶樞澀。","樹朽鳥不栖，階閑雲自濕。","先生何處去，惆悵空獨立。"]', '["故宅春山中，来逢夕陽入。","汲少井味变，开稀戶樞澀。","樹朽鸟不栖，階闲云自濕。","先生何处去，惆悵空独立。"]', '诗', 'shi', '', NULL, '過王山人舊居 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8822c39-6342-4a93-beac-06eaad45d8f4', '晚次昭應', '晚次昭應', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["落日向林路，東風吹麥隴。","藤草蔓古渠，牛羊下荒冢。","驪宮戶久閉，溫谷泉長湧。","爲問全盛時，何人最榮寵。"]', '["落日向林路，东风吹麦隴。","藤草蔓古渠，牛羊下荒冢。","驪宮戶久閉，溫谷泉长湧。","爲问全盛时，何人最榮寵。"]', '诗', 'shi', '', NULL, '晚次昭應 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90307e8-fc70-4353-a2d4-cf008322dde7', '聽早蟬歌', '听早蟬歌', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["蟬鳴兮夕曛，聲和兮夏雲。","白日兮將短，秋意兮已滿。","乍悲鳴兮欲長，猶嘶澀兮多斷。","風蕭蕭兮轉清，韻嘒嘒兮初成。","依婆娑之古樹，思遼落之荒城。","閑院支頤，深林倚策。","猶惆悵而無語，鬢星星而已白。"]', '["蟬鳴兮夕曛，声和兮夏云。","白日兮將短，秋意兮已满。","乍悲鳴兮欲长，猶嘶澀兮多斷。","风蕭蕭兮轉清，韻嘒嘒兮初成。","依婆娑之古樹，思遼落之荒城。","闲院支頤，深林倚策。","猶惆悵而無語，鬢星星而已白。"]', '诗', 'shi', '', NULL, '聽早蟬歌 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db18954-20bd-4410-b595-49d8f32b8d5e', '蘆花動', '蘆花动', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["連素穗，翻秋氣，細節疎莖任長吹。","共作月中聲，孤舟發鄉思。"]', '["連素穗，翻秋氣，細節疎莖任长吹。","共作月中声，孤舟發乡思。"]', '诗', 'shi', '', NULL, '蘆花動 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6820c44-408f-46be-938f-dc372e44eb17', '賦得寒蛩', '賦得寒蛩', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["爾誰造，鳴何早，趯趯連聲徧階草。","復與夜雨和，遊人聽堪老。"]', '["爾誰造，鳴何早，趯趯連声徧階草。","复與夜雨和，游人听堪老。"]', '诗', 'shi', '', NULL, '賦得寒蛩 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10cccfc-93f2-45be-808c-7b327d8a5807', '宣城逢張二南史', '宣城逢張二南史', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["全家宛陵客，文雅世難逢。","寄食年將老，干時計未從。","秋來句曲水，雨後敬亭峯。","西北長安遠，登臨恨幾重。"]', '["全家宛陵客，文雅世难逢。","寄食年將老，干时計未從。","秋来句曲水，雨後敬亭峯。","西北长安远，登臨恨幾重。"]', '诗', 'shi', '', NULL, '宣城逢張二南史 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b9d6dd-2c1a-4cfe-a0e5-bc43e0b7f585', '題童子寺', '題童子寺', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["半偈留何處，全身棄此中。","雨餘沙塔壞，月滿雪山空。","聳剎臨回磴，朱樓間碧叢。","朝朝日將暮，長對晉陽宮。"]', '["半偈留何处，全身棄此中。","雨餘沙塔壞，月满雪山空。","聳剎臨回磴，朱楼间碧叢。","朝朝日將暮，长对晉陽宮。"]', '诗', 'shi', '', NULL, '題童子寺 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac28964-b002-4665-a07d-3c04899ec754', '夏日寄東溪隱者', '夏日寄东溪隐者', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["日華浮野水，草色合遙空。","處處山依舊，年年事不同。","閑田孤壘外，暑雨片雲中。","惆悵多塵累，無由訪釣翁。"]', '["日华浮野水，草色合遙空。","处处山依旧，年年事不同。","闲田孤壘外，暑雨片云中。","惆悵多塵累，無由訪釣翁。"]', '诗', 'shi', '', NULL, '夏日寄東溪隱者 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102f802b-bc9f-4d5b-becf-9484e98317eb', '之江淮留別京親故', '之江淮留別京親故', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["長雲迷一雁，漸遠向南聲。","已帶千霜鬢，初爲萬里行。","繁蟲滿夜草，連雨暗秋城。","前路諸侯貴，何人重客卿。"]', '["长云迷一雁，漸远向南声。","已带千霜鬢，初爲万里行。","繁蟲满夜草，連雨暗秋城。","前路諸侯貴，何人重客卿。"]', '诗', 'shi', '', NULL, '之江淮留別京親故 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d07749c-1d5d-4233-94f1-2780ee059be6', '太原送許侍御出幕歸東都', '太原送許侍御出幕归东都', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["昔隨劉越石，今日獨歸時。","汾水風煙冷，幷州花木遲。","荒庭增別夢，野雨失行期。","莫向山陽過，隣人夜笛悲。"]', '["昔隨劉越石，今日独归时。","汾水风煙冷，幷州花木遲。","荒庭增別梦，野雨失行期。","莫向山陽過，隣人夜笛悲。"]', '诗', 'shi', '', NULL, '太原送許侍御出幕歸東都 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff8feec-b805-46d8-ade9-9cf59570b91f', '華州客舍奉和崔端公春城曉望', '华州客舍奉和崔端公春城晓望', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["不語看芳徑，悲春嬾獨行。","向人微月在，報雨早霞生。","貧病催年齒，風塵掩姓名。","賴逢驄馬客，郢曲緩羇情。"]', '["不語看芳徑，悲春嬾独行。","向人微月在，報雨早霞生。","貧病催年齒，风塵掩姓名。","賴逢驄马客，郢曲緩羇情。"]', '诗', 'shi', '', NULL, '華州客舍奉和崔端公春城曉望 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fdd485a-d24c-40b3-846c-8f4ebf79dcc4', '題清蘿翁雙泉', '題清蘿翁雙泉', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["側弁向清漪，門中夕照移。","異源生暗石，疊響落秋池。","葉擁沙痕沒，流回草蔓隨。","泠泠無限意，不獨遠公知。"]', '["側弁向清漪，门中夕照移。","異源生暗石，叠响落秋池。","葉擁沙痕沒，流回草蔓隨。","泠泠無限意，不独远公知。"]', '诗', 'shi', '', NULL, '題清蘿翁雙泉 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32d79ae-1339-4a75-b9cd-fb3e2dc37d5d', '酬李文', '酬李文', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["落照長楊苑，秋天渭水濱。","初飛萬木葉，又長一年人。","貧病仍爲客，艱虞更問津。","多慙惠然意，今日肯相親。"]', '["落照长楊苑，秋天渭水濱。","初飞万木葉，又长一年人。","貧病仍爲客，艱虞更问津。","多慙惠然意，今日肯相親。"]', '诗', 'shi', '', NULL, '酬李文 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43953a9-cc58-4d6f-b3a4-4382e30c2f70', '贈嚴維', '贈嚴維', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["許詢清論重，寂寞住山陰。","野路接寒寺，閑門當古林。","海田秋熟早，湖水夜漁深。","世上窮通理，誰人奈此心。"]', '["許詢清論重，寂寞住山陰。","野路接寒寺，闲门當古林。","海田秋熟早，湖水夜漁深。","世上窮通理，誰人奈此心。"]', '诗', 'shi', '', NULL, '贈嚴維 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ceed844-05e4-493f-a345-b26e9230b080', '春日題苗發竹亭', '春日題苗發竹亭', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["春亭及策上，郎吏謝玄暉。","閑詠疎篁近，高眠遠岫微。","偏宜留野客，暫得解朝衣。","猶憶東溪裏，雷雲掩故扉。"]', '["春亭及策上，郎吏謝玄暉。","闲詠疎篁近，高眠远岫微。","偏宜留野客，暫得解朝衣。","猶憶东溪裏，雷云掩故扉。"]', '诗', 'shi', '', NULL, '春日題苗發竹亭 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9dcb041-8bd0-4676-9c21-e8668bd4d033', '題孝子陵', '題孝子陵', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["荒墳秋陌上，霜露正霏霏。","松柏自成拱，苫廬長不歸。","浮埃積蓬鬢，流血在麻衣。","何必曾參傳，千年至行稀。"]', '["荒墳秋陌上，霜露正霏霏。","松柏自成拱，苫廬长不归。","浮埃積蓬鬢，流血在麻衣。","何必曾參傳，千年至行稀。"]', '诗', 'shi', '', NULL, '題孝子陵 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e7cec1-f391-4b59-a09e-7815b6675fff', '題莊上人房', '題莊上人房', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["不語焚香坐，心知道已成。","流年衰此世，定力見他生。","暮雪餘春冷，寒燈續晝明。","尋常五侯至，敢望下階迎。"]', '["不語焚香坐，心知道已成。","流年衰此世，定力见他生。","暮雪餘春冷，寒灯續晝明。","尋常五侯至，敢望下階迎。"]', '诗', 'shi', '', NULL, '題莊上人房 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45047fc8-5ad9-4690-ba4b-7569476147b1', '宋中', '宋中', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["日暮黃雲合，年深白骨稀。","舊村喬木在，秋草遠人歸。","廢井莓苔厚，荒田路徑微。","唯餘近山色，相對似依依。"]', '["日暮黄云合，年深白骨稀。","旧村喬木在，秋草远人归。","廢井莓苔厚，荒田路徑微。","唯餘近山色，相对似依依。"]', '诗', 'shi', '', NULL, '宋中 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cdf127d-5b6d-4007-abf8-06b9c7519951', '秋夜思歸', '秋夜思归', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["來時猶暑服，今已露漫漫。","多雨逢初霽，深秋生夜寒。","投人心似切，爲客事皆難。","何處無留滯，誰能暫問看。"]', '["来时猶暑服，今已露漫漫。","多雨逢初霽，深秋生夜寒。","投人心似切，爲客事皆难。","何处無留滯，誰能暫问看。"]', '诗', 'shi', '', NULL, '秋夜思歸 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e7bd38-4c1f-44bc-a488-c1fd8ac4b9fa', '送李端', '送李端', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["世上許劉楨，洋洋風雅聲。","客來空改歲，歸去未成名。","遠近天初暮，關河雪半晴。","空懷諫書在，回首戀承明。"]', '["世上許劉楨，洋洋风雅声。","客来空改歲，归去未成名。","远近天初暮，关河雪半晴。","空懷諫书在，回首戀承明。"]', '诗', 'shi', '', NULL, '送李端 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30927692-01e2-485b-9429-752ad939be03', '送崔明府赴青城', '送崔明府赴青城', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["清冬賓御出，蜀道翠微間。","遠霧開羣壑，初陽照近關。","霜潭浮紫菜，雪棧繞青山。","當似遺民去，柴桑政自閑。"]', '["清冬賓御出，蜀道翠微间。","远霧开羣壑，初陽照近关。","霜潭浮紫菜，雪棧繞青山。","當似遺民去，柴桑政自闲。"]', '诗', 'shi', '', NULL, '送崔明府赴青城 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c48ce10-3a5a-429d-9bda-9f9969467ce5', '送王將軍出塞', '送王將軍出塞', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["漢家邊事重，竇憲出臨戎。","絕漠秋山在，陽關舊路通。","列營依茂草，吹角向高風。","更就燕然石，行看奏虜功。"]', '["漢家邊事重，竇憲出臨戎。","絕漠秋山在，陽关旧路通。","列營依茂草，吹角向高风。","更就燕然石，行看奏虜功。"]', '诗', 'shi', '', NULL, '送王將軍出塞 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37654f5b-fbaf-4436-96e5-3c35fd80c9ba', '雨中留別', '雨中留別', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["東西無定客，風雨未休時。","憫默此中別，飄零何處期。","青山違舊隱，白髮入新詩。","歲歲迷津路，生涯漸可悲。"]', '["东西無定客，风雨未休时。","憫默此中別，飄零何处期。","青山違旧隐，白髮入新诗。","歲歲迷津路，生涯漸可悲。"]', '诗', 'shi', '', NULL, '雨中留別 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b244fa50-b7bf-4901-b030-464f18c1c455', '送楊將軍', '送楊將軍', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["一身良將後，萬里討烏孫。","落日邊陲靜，秋風鼓角喧。","遠山當磧路，茂草向營門。","生死酬恩寵，功名豈敢論。"]', '["一身良將後，万里討烏孫。","落日邊陲静，秋风鼓角喧。","远山當磧路，茂草向營门。","生死酬恩寵，功名豈敢論。"]', '诗', 'shi', '', NULL, '送楊將軍 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecbd9ad4-caee-4838-bbdf-0dee571d4a62', '送夏侯審遊蜀', '送夏侯審游蜀', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["暮峰和玉壘，回望不通秦。","更問蜀城路，但逢巴語人。","石林鶯囀曉，板屋月明春。","若訪嚴夫子，無嫌卜肆貧。"]', '["暮峰和玉壘，回望不通秦。","更问蜀城路，但逢巴語人。","石林鶯囀晓，板屋月明春。","若訪嚴夫子，無嫌卜肆貧。"]', '诗', 'shi', '', NULL, '送夏侯審遊蜀 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f79063-78b0-4a87-a9cd-c196a9496474', '送張侍御赴郴州別駕', '送張侍御赴郴州別駕', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["佐郡人難料，分襟日復斜。","一帆隨遠水，百口過長沙。","明月江邊夜，平陵夢裏家。","王孫對芳草，愁思杳無涯。"]', '["佐郡人难料，分襟日复斜。","一帆隨远水，百口過长沙。","明月江邊夜，平陵梦裏家。","王孫对芳草，愁思杳無涯。"]', '诗', 'shi', '', NULL, '送張侍御赴郴州別駕 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d60923-6a4b-4d83-a8a4-357971ac8a9e', '送苗贇赴陽翟丞', '送苗贇赴陽翟丞', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["夕陽秋草上，去馬弟兄看。","年少初辭闕，時危遠效官。","山行獨夜雨，旅宿二陵寒。","詩興生何處，嵩陽羽客壇。"]', '["夕陽秋草上，去马弟兄看。","年少初辞闕，时危远效官。","山行独夜雨，旅宿二陵寒。","诗兴生何处，嵩陽羽客壇。"]', '诗', 'shi', '', NULL, '送苗贇赴陽翟丞 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f27426c-86f1-41bf-ab9f-91830376df53', '送絳州郭參軍', '送絳州郭參軍', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠事諸侯出，青山古晉城。","連行麴水閣，獨入議中兵。","夜雨新田濕，春風曙角鳴。","人傳府公政，記室有參卿。"]', '["远事諸侯出，青山古晉城。","連行麴水閣，独入議中兵。","夜雨新田濕，春风曙角鳴。","人傳府公政，記室有參卿。"]', '诗', 'shi', '', NULL, '送絳州郭參軍 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612964e5-7287-489d-b2c2-5a5d40f3a7c4', '常州留別', '常州留別', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["萬里南天外，求書禹穴間。","往來成白首，旦暮見青山。","夜浦涼雲過，秋塘好月閑。","殷勤陽羨桂，別此幾時攀。"]', '["万里南天外，求书禹穴间。","往来成白首，旦暮见青山。","夜浦涼云過，秋塘好月闲。","殷勤陽羨桂，別此幾时攀。"]', '诗', 'shi', '', NULL, '常州留別 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44bc39df-233c-4668-87af-6ad92c897c17', '關山月', '关山月', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["月明邊徼靜，戍客望鄉時。","塞古柳衰盡，關寒榆發遲。","蒼蒼萬里道，戚戚十年北。","今夜青樓上，還應照所思。"]', '["月明邊徼静，戍客望乡时。","塞古柳衰尽，关寒榆發遲。","蒼蒼万里道，戚戚十年北。","今夜青楼上，還應照所思。"]', '诗', 'shi', '', NULL, '關山月 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142a8072-b662-48d1-90b3-a11f6609c0db', '代宋州將淮上乞師', '代宋州將淮上乞師', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["脣齒幸相依，危亡故遠歸。","身輕百戰出，家在數重圍。","上將堅深壘，殘兵鬬落暉。","常聞鐵劒利，早晚借餘威。"]', '["脣齒幸相依，危亡故远归。","身轻百戰出，家在數重圍。","上將堅深壘，殘兵鬬落暉。","常闻鐵劒利，早晚借餘威。"]', '诗', 'shi', '', NULL, '代宋州將淮上乞師 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f675f38-47ce-4119-b846-d11723e25e95', '秋晚臥疾寄司空拾遺曙盧少府綸', '秋晚臥疾寄司空拾遺曙盧少府綸', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["寒几坐空堂，疎髯似積霜。","老醫迷舊疾，朽藥誤新方。","晚果紅低樹，秋苔綠徧牆。","慙非蔣生徑，不敢望求羊。"]', '["寒几坐空堂，疎髯似積霜。","老醫迷旧疾，朽藥誤新方。","晚果紅低樹，秋苔綠徧牆。","慙非蔣生徑，不敢望求羊。"]', '诗', 'shi', '', NULL, '秋晚臥疾寄司空拾遺曙盧少府綸 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7834bc02-d434-470f-8874-1f45a60707bc', '贈海明上人', '贈海明上人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["來自西天竺，持經奉紫微。","年深梵語變，行苦俗流歸。","月上安禪久，苔生出院稀。","梁間有馴鴿，不去復何依。"]', '["来自西天竺，持經奉紫微。","年深梵語变，行苦俗流归。","月上安禪久，苔生出院稀。","梁间有馴鴿，不去复何依。"]', '诗', 'shi', '', NULL, '贈海明上人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdb947b-0c38-4be1-9b49-8c16e7ac46b8', '津亭有懷', '津亭有懷', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["津亭一望鄉，淮海晚茫茫。","草沒棲洲鷺，天連暎浦檣。","徃來通楚越，旦暮易漁商。","惆悵緘書畢，何人向洛陽。"]', '["津亭一望乡，淮海晚茫茫。","草沒棲洲鷺，天連暎浦檣。","徃来通楚越，旦暮易漁商。","惆悵緘书畢，何人向洛陽。"]', '诗', 'shi', '', NULL, '津亭有懷 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cea0fa-4c7b-456a-ae5d-574d1dc8a878', '晚投江澤浦即事呈柳兵曹泥', '晚投江澤浦即事呈柳兵曹泥', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["落日過重霞，輕烟上遠沙。","移舟衝荇蔓，轉浦入蘆花。","斷岸迂來客，連波漾去槎。","故鄉何處在，更道向天涯。"]', '["落日過重霞，轻烟上远沙。","移舟衝荇蔓，轉浦入蘆花。","斷岸迂来客，連波漾去槎。","故乡何处在，更道向天涯。"]', '诗', 'shi', '', NULL, '晚投江澤浦即事呈柳兵曹泥 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2936dc0e-efe5-40c0-a2f3-1ecd8d4653c0', '東郊別業', '东郊別業', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["東臯占薄田，耕種過餘年。","護藥栽山刺，澆蔬引竹泉。","晚雷期稔歲，重霧報晴天。","若問幽人意，思齊沮溺賢。"]', '["东臯占薄田，耕種過餘年。","護藥栽山刺，澆蔬引竹泉。","晚雷期稔歲，重霧報晴天。","若问幽人意，思齊沮溺賢。"]', '诗', 'shi', '', NULL, '東郊別業 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784480cb-7b1f-456d-bcd9-94ddad87a1b2', '早朝', '早朝', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["鐘鼓餘聲裏，千官向紫微。","冒寒人語少，乘月燭來稀。","清漏聞馳道，輕霞暎瑣闈。","猶看嘶馬處，未啟掖垣扉。"]', '["鐘鼓餘声裏，千官向紫微。","冒寒人語少，乘月燭来稀。","清漏闻驰道，轻霞暎瑣闈。","猶看嘶马处，未啟掖垣扉。"]', '诗', 'shi', '', NULL, '早朝 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e954b172-6d23-4fac-afc4-98da31e1ca14', '屏居盩厔', '屏居盩厔', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["百年心不料，一卷日相知。","乘興偏難改，憂家是強爲。","縣城寒寂寞，峰樹遠參差。","自笑無謀者，秪應道在斯。"]', '["百年心不料，一卷日相知。","乘兴偏难改，憂家是強爲。","縣城寒寂寞，峰樹远參差。","自笑無謀者，秪應道在斯。"]', '诗', 'shi', '', NULL, '屏居盩厔 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc07822-6fcc-44f0-836f-956c0ad2d4e8', '進秋隼', '進秋隼', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["豈悟因羅者，迎霜獻紫微。","夕陽分素臆，秋色上花衣。","舉翅雲天近，回眸燕雀稀。","應隨明主意，百中有光輝。"]', '["豈悟因羅者，迎霜獻紫微。","夕陽分素臆，秋色上花衣。","舉翅云天近，回眸燕雀稀。","應隨明主意，百中有光輝。"]', '诗', 'shi', '', NULL, '進秋隼 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22793c70-a745-46af-836a-fbb2a4318638', '詠宣州筆', '詠宣州笔', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["寒竹慙虛受，纖毫任幾重。","影端緣守直，心勁懶藏鋒。","落紙驚風起，搖空見露濃。","丹青與文事，捨此復何從。"]', '["寒竹慙虛受，纖毫任幾重。","影端緣守直，心勁懶藏鋒。","落紙驚风起，搖空见露濃。","丹青與文事，捨此复何從。"]', '诗', 'shi', '', NULL, '詠宣州筆 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b20294e5-9995-40a2-bd83-242ccd62a87d', '春日洪州即事', '春日洪州即事', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["鍾陵春日好，春水滿南塘。","竹宇分朱閣，桐花間綠楊。","蹉跎看鬢色，留滯惜年芳。","欲問羇愁發，秦關道路長。"]', '["鍾陵春日好，春水满南塘。","竹宇分朱閣，桐花间綠楊。","蹉跎看鬢色，留滯惜年芳。","欲问羇愁發，秦关道路长。"]', '诗', 'shi', '', NULL, '春日洪州即事 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e743a29-04ae-416e-a014-6da19281a515', '雪後宿王純池州草堂', '雪後宿王純池州草堂', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["宿君湖上宅，琴韻靜參差。","夜雪入秋浦，孤城連貴池。","流年看共老，銜酒發中悲。","良會應難再，晨雞自有期。"]', '["宿君湖上宅，琴韻静參差。","夜雪入秋浦，孤城連貴池。","流年看共老，銜酒發中悲。","良會應难再，晨雞自有期。"]', '诗', 'shi', '', NULL, '雪後宿王純池州草堂 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05b6908-5d87-4a15-b58b-54fd0c59c00e', '旅次漢故畤', '旅次漢故畤', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["我行過漢畤，寥落見孤城。","邑里經多難，兒童識五兵。","廣川桑遍綠，叢薄雉連鳴。","惆悵蕭關道，終軍願請纓。"]', '["我行過漢畤，寥落见孤城。","邑里經多难，兒童識五兵。","廣川桑遍綠，叢薄雉連鳴。","惆悵蕭关道，終軍願請纓。"]', '诗', 'shi', '', NULL, '旅次漢故畤 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe55c4a-6e98-4270-812d-df1aa1ae48a6', '過三郊驛却寄楊評事時此子郭令公欲有表薦', '過三郊驛却寄楊評事时此子郭令公欲有表薦', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["冉冉青衫客，悠悠白髮人。","亂山孤驛暮，長路百花新。","終歲行他縣，全家望此身。","更思君去就，早晚問平津。"]', '["冉冉青衫客，悠悠白髮人。","亂山孤驛暮，长路百花新。","終歲行他縣，全家望此身。","更思君去就，早晚问平津。"]', '诗', 'shi', '', NULL, '過三郊驛却寄楊評事時此子郭令公欲有表薦 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0f2bae-efe8-4bfc-a965-da116da2532e', '隴西行', '隴西行', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["雪下陽關路，人稀隴戍頭。","封狐猶未翦，邊將豈無羞。","白草三冬色，黃雲萬里愁。","因思李都尉，畢竟不封侯。"]', '["雪下陽关路，人稀隴戍头。","封狐猶未翦，邊將豈無羞。","白草三冬色，黄云万里愁。","因思李都尉，畢竟不封侯。"]', '诗', 'shi', '', NULL, '隴西行 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed801ef7-4f6e-4595-9b6d-b8a67a286472', '巴陵逢洛陽鄰舍', '巴陵逢洛陽鄰舍', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["因君知北事，流浪已忘機。","客久多人識，年高衆病歸。","連雲湖色遠，度雪雁聲稀。","又說家林盡，悽傷淚滿衣。"]', '["因君知北事，流浪已忘機。","客久多人識，年高衆病归。","連云湖色远，度雪雁声稀。","又说家林尽，悽傷泪满衣。"]', '诗', 'shi', '', NULL, '巴陵逢洛陽鄰舍 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c71c0a-9c78-4539-a075-4232fd83fc52', '哭張融', '哭張融', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["早歲能文客，中年與世違。","有家孀婦少，無子弔人稀。","繐帳塵空暗，銘旌雨不飛。","依然舊鄉路，寂寞幾回歸。"]', '["早歲能文客，中年與世違。","有家孀婦少，無子弔人稀。","繐帳塵空暗，銘旌雨不飞。","依然旧乡路，寂寞幾回归。"]', '诗', 'shi', '', NULL, '哭張融 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f24b27-421f-4b6a-97a2-46af94aa53f5', '送友貶嶺南', '送友貶嶺南', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["暮年從遠謫，落日別交親。","湖上北飛雁，天涯南去人。","夢成湘浦夜，淚盡桂陽春。","歲月茫茫意，何時雨露新。"]', '["暮年從远謫，落日別交親。","湖上北飞雁，天涯南去人。","梦成湘浦夜，泪尽桂陽春。","歲月茫茫意，何时雨露新。"]', '诗', 'shi', '', NULL, '送友貶嶺南 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89799bab-6157-4af8-a292-46807a9ed427', '春日即事二首 一', '春日即事二首 一', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["詩書成志業，嬾慢致蹉跎。","聖代丹霄遠，明時白髮多。","淺謀堪自笑，窮巷憶誰過。","寂寞前山暮，歸人樵採歌。"]', '["诗书成志業，嬾慢致蹉跎。","聖代丹霄远，明时白髮多。","淺謀堪自笑，窮巷憶誰過。","寂寞前山暮，归人樵採歌。"]', '诗', 'shi', '', NULL, '春日即事二首 一 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac39c6f-d1cf-4035-bed4-261b94e653d2', '春日即事二首 二', '春日即事二首 二', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["數畝東臯宅，青春獨屏居。","家貧僮僕慢，官罷友朋疎。","強飲沽來酒，羞看讀了書。","閑花開滿地，惆悵復何如。"]', '["數畝东臯宅，青春独屏居。","家貧僮僕慢，官罷友朋疎。","強饮沽来酒，羞看读了书。","闲花开满地，惆悵复何如。"]', '诗', 'shi', '', NULL, '春日即事二首 二 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19062de-ff75-4ab3-b6cc-453f45c32102', '贈田家翁', '贈田家翁', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["老人迎客處，籬落稻畦間。","蠶屋朝寒閉，田家晝雨閑。","門閭新薙草，蹊徑舊諳山。","自道誰相及，邀予試徃還。"]', '["老人迎客处，籬落稻畦间。","蠶屋朝寒閉，田家晝雨闲。","门閭新薙草，蹊徑旧諳山。","自道誰相及，邀予試徃還。"]', '诗', 'shi', '', NULL, '贈田家翁 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b7bb4f-ee25-40ad-b76c-40ec2539f6e4', '贈韋山人', '贈韋山人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["失意成逋客，終年獨掩扉。","無機狎鷗慣，多病見人稀。","流水知行藥，孤雲伴採薇。","空齋莫閑笑，心事與時違。"]', '["失意成逋客，終年独掩扉。","無機狎鷗慣，多病见人稀。","流水知行藥，孤云伴採薇。","空斋莫闲笑，心事與时違。"]', '诗', 'shi', '', NULL, '贈韋山人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23233a8a-a13d-4319-86e7-b16d3dc0727c', '濬公院懷舊', '濬公院懷旧', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠公傳敎畢，身沒向他方。","弔客來何見，門人閉影堂。","紗燈臨古砌，塵札在空牀。","寂寞疎鐘後，秋天有夕陽。"]', '["远公傳敎畢，身沒向他方。","弔客来何见，门人閉影堂。","紗灯臨古砌，塵札在空牀。","寂寞疎鐘後，秋天有夕陽。"]', '诗', 'shi', '', NULL, '濬公院懷舊 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be118ff0-566d-466d-ac07-0de6e6493419', '雨中宿義興寺', '雨中宿義兴寺', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遙夜宿東林，蟲聲階草深。","高風初落葉，多雨未歸心。","家國身猶負，星霜鬢已侵。","滄洲縱不去，何處有知音。"]', '["遙夜宿东林，蟲声階草深。","高风初落葉，多雨未归心。","家国身猶負，星霜鬢已侵。","滄洲縱不去，何处有知音。"]', '诗', 'shi', '', NULL, '雨中宿義興寺 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5025e96d-6151-4537-96ac-4535c1a2880f', '送王祕書歸江東', '送王祕书归江东', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["迴首望知音，逶迤桑柘林。","人歸海郡遠，路入雨天深。","萬木經秋葉，孤舟向暮心。","唯餘江畔草，應見白頭吟。"]', '["迴首望知音，逶迤桑柘林。","人归海郡远，路入雨天深。","万木經秋葉，孤舟向暮心。","唯餘江畔草，應见白头吟。"]', '诗', 'shi', '', NULL, '送王祕書歸江東 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc94daf6-9218-4db3-aae6-00c170182d44', '渭上送李蔵器移家東都', '渭上送李蔵器移家东都', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["求名雖有據，學稼又無田。","故國三千里，新春五十年。","移家還作客，避地莫知賢。","洛浦今何處，風帆去渺然。"]', '["求名雖有據，学稼又無田。","故国三千里，新春五十年。","移家還作客，避地莫知賢。","洛浦今何处，风帆去渺然。"]', '诗', 'shi', '', NULL, '渭上送李蔵器移家東都 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91e2fce-3d9c-42fa-9692-39d502521789', '春尋柳先生', '春尋柳先生', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["言是商山老，塵心莫問年。","白髯垂策短，烏帽據梧偏。","酒熟飛巴雨，丹成見海田。","疎雲披遠水，景動石牀前。"]', '["言是商山老，塵心莫问年。","白髯垂策短，烏帽據梧偏。","酒熟飞巴雨，丹成见海田。","疎云披远水，景动石牀前。"]', '诗', 'shi', '', NULL, '春尋柳先生 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473617e8-f2d2-4f2a-a26d-df696f3c9890', '題藏公院', '題藏公院', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["古院林公住，疎篁近井桃。","俗年人見少，禪地自知高。","藥草誠多喻，滄溟在一毫。","仍悲次宗輩，塵事日爲勞。"]', '["古院林公住，疎篁近井桃。","俗年人见少，禪地自知高。","藥草誠多喻，滄溟在一毫。","仍悲次宗輩，塵事日爲勞。"]', '诗', 'shi', '', NULL, '題藏公院 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae4faa3-42b2-4a4f-8d19-c99aa13cb3af', '夏夜西亭即事寄錢員外', '夏夜西亭即事寄錢員外', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["高亭賓客散，暑夜醉相和。","細汗迎衣集，微涼待扇過。","風還池色定，月晚樹陰多。","遙想隨行者，珊珊動曉珂。"]', '["高亭賓客散，暑夜醉相和。","細汗迎衣集，微涼待扇過。","风還池色定，月晚樹陰多。","遙想隨行者，珊珊动晓珂。"]', '诗', 'shi', '', NULL, '夏夜西亭即事寄錢員外 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a6200cd-e631-44bb-8e03-3c16e29c675d', '與清江上人及諸公宿李八昆季宅', '與清江上人及諸公宿李八昆季宅', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["湯公多外友，洛社自相依。","遠客還登會，秋懷欲忘歸。","驚風林果少，驟雨砌蟲稀。","更過三張價，東遊愧陸機。"]', '["湯公多外友，洛社自相依。","远客還登會，秋懷欲忘归。","驚风林果少，驟雨砌蟲稀。","更過三張價，东游愧陸機。"]', '诗', 'shi', '', NULL, '與清江上人及諸公宿李八昆季宅 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af55f487-b2a8-4e2c-a3ab-406cd7a450fb', '春日即事', '春日即事', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["鄰里朝光徧，披衣夜醉醒。","庖廚非舊火，林木發新青。","接果移天性，疎泉逐地形。","清明來幾日，戴勝已堪聽。"]', '["鄰里朝光徧，披衣夜醉醒。","庖廚非旧火，林木發新青。","接果移天性，疎泉逐地形。","清明来幾日，戴勝已堪听。"]', '诗', 'shi', '', NULL, '春日即事 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b465cf8-9dac-4e2f-b97c-f294c49bd64e', '秋夜會宿李永宅憶江南舊遊', '秋夜會宿李永宅憶江南旧游', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["偶宿俱南客，相看喜盡歸。","湖山話不極，歲月念空違。","子夜高梧冷，秋陰遠漏微。","那無此良會，惜在謝家稀。"]', '["偶宿俱南客，相看喜尽归。","湖山話不極，歲月念空違。","子夜高梧冷，秋陰远漏微。","那無此良會，惜在謝家稀。"]', '诗', 'shi', '', NULL, '秋夜會宿李永宅憶江南舊遊 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5710ddc-eaa3-4e16-9851-208d23381af0', '冬夜尋李永因書事贈之', '冬夜尋李永因书事贈之', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["棲遑偏降志，疵賤倍修身。","近覺多衰鬢，深知獨故人。","天垂五夜月，霜覆九衢塵。","不待逢沮溺，而今惡問津。"]', '["棲遑偏降志，疵賤倍修身。","近覺多衰鬢，深知独故人。","天垂五夜月，霜覆九衢塵。","不待逢沮溺，而今惡问津。"]', '诗', 'shi', '', NULL, '冬夜尋李永因書事贈之 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aac5703-ad15-4da8-84fb-ff0e68557569', '立春日宴高陵任明府宅', '立春日宴高陵任明府宅', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["春灰今變候，密雪又霏霏。","坐客同心滿，流年此會稀。","風成空處亂，素積夜來飛。","且共銜盃酒，陶潛不得歸。"]', '["春灰今变候，密雪又霏霏。","坐客同心满，流年此會稀。","风成空处亂，素積夜来飞。","且共銜盃酒，陶潛不得归。"]', '诗', 'shi', '', NULL, '立春日宴高陵任明府宅 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a2d26a-25e8-40ae-bb5d-796daf603296', '春日遊慈恩寺寄暢當', '春日游慈恩寺寄暢當', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["浮世今何事，空門此諦真。","死生俱是夢，哀樂詎關身。","遠草光連水，春篁色離塵。","當從庚中庶，詩客更何人。"]', '["浮世今何事，空门此諦真。","死生俱是梦，哀乐詎关身。","远草光連水，春篁色離塵。","當從庚中庶，诗客更何人。"]', '诗', 'shi', '', NULL, '春日遊慈恩寺寄暢當 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67af46ed-1859-45b9-b93b-294175a5ed33', '晚秋過蘇少府', '晚秋過蘇少府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["九江迷去住，羣吏且因依。","高木秋垂露，寒城暮掩扉。","隨雲心自遠，看草伴應稀。","肯信同年友，相望青瑣闈。"]', '["九江迷去住，羣吏且因依。","高木秋垂露，寒城暮掩扉。","隨云心自远，看草伴應稀。","肯信同年友，相望青瑣闈。"]', '诗', 'shi', '', NULL, '晚秋過蘇少府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133c8880-40d0-4ac2-94ab-4152c840112b', '登鸛雀樓', '登鸛雀楼', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["久客心常醉，高樓日漸低。","黃河經海內，華嶽鎮關西。","去遠千帆小，來遲獨鳥迷。","終年不得意，空覺負東溪。"]', '["久客心常醉，高楼日漸低。","黄河經海內，华嶽鎮关西。","去远千帆小，来遲独鸟迷。","終年不得意，空覺負东溪。"]', '诗', 'shi', '', NULL, '登鸛雀樓 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8d3630-c13b-4436-8027-2458dfd49e85', '賦得沙上雁', '賦得沙上雁', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["衡陽多道里，弱羽復哀音。","還塞知何日，驚弦亂此心。","夜陰前侶遠，秋冷後湖深。","獨立汀洲意，寧知霜霰侵。"]', '["衡陽多道里，弱羽复哀音。","還塞知何日，驚弦亂此心。","夜陰前侶远，秋冷後湖深。","独立汀洲意，寧知霜霰侵。"]', '诗', 'shi', '', NULL, '賦得沙上雁 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55e8b51-c2db-4614-b294-13b24db753b9', '夜尋盧處士', '夜尋盧处士', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["月高雞犬靜，門掩向寒塘。","夜竹深茅宇，秋庭冷石牀。","住山年已遠，服藥壽偏長。","虛棄如吾者，逢君益自傷。"]', '["月高雞犬静，门掩向寒塘。","夜竹深茅宇，秋庭冷石牀。","住山年已远，服藥壽偏长。","虛棄如吾者，逢君益自傷。"]', '诗', 'shi', '', NULL, '夜尋盧處士 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40698af6-d701-4be1-b0c5-d2acfece61b8', '邠州留別', '邠州留別', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["終歲山川路，生涯總幾何。","艱難爲客慣，貧賤受恩多。","暮角寒山色，秋風遠水波。","無人見惆悵，垂鞚入煙蘿。"]', '["終歲山川路，生涯總幾何。","艱难爲客慣，貧賤受恩多。","暮角寒山色，秋风远水波。","無人见惆悵，垂鞚入煙蘿。"]', '诗', 'shi', '', NULL, '邠州留別 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13893404-3ea9-493b-af94-5ae0d21e557a', '贈張將軍', '贈張將軍', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["寥落軍城暮，重門返照間。","鼓鼙經雨暗，士馬過秋閑。","慣守臨邊郡，曾營近海山。","關西舊業在，夜夜夢中還。"]', '["寥落軍城暮，重门返照间。","鼓鼙經雨暗，士马過秋闲。","慣守臨邊郡，曾營近海山。","关西旧業在，夜夜梦中還。"]', '诗', 'shi', '', NULL, '贈張將軍 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761cde00-c315-40a8-81b0-8c4938ba1dc1', '贈隱公', '贈隐公', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["世間無近遠，定裏徧曾過。","東海經長在，南朝寺最多。","暮年聊化俗，初地即摧魔。","今日忘塵慮，看心義若何。"]', '["世间無近远，定裏徧曾過。","东海經长在，南朝寺最多。","暮年聊化俗，初地即摧魔。","今日忘塵慮，看心義若何。"]', '诗', 'shi', '', NULL, '贈隱公 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf347e4-c81e-4e5a-b5ae-033f271efc98', '贈別安邑韓少府', '贈別安邑韓少府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["子真能自在，江海意何如。","門掩疎塵吏，心閑閱道書。","古城寒欲雪，遠客暮無車。","杳杳思前路，誰堪千里餘。"]', '["子真能自在，江海意何如。","门掩疎塵吏，心闲閱道书。","古城寒欲雪，远客暮無车。","杳杳思前路，誰堪千里餘。"]', '诗', 'shi', '', NULL, '贈別安邑韓少府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae9d2fd-157e-4c85-9816-e8ff6cf6c112', '送胡校書秩滿歸河中', '送胡校书秩满归河中', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["古樹汾陰道，悠悠東去長。","位卑仍解印，身老又還鄉。","河水平秋岸，關門向夕陽。","音書須數附，莫學晉嵇康。"]', '["古樹汾陰道，悠悠东去长。","位卑仍解印，身老又還乡。","河水平秋岸，关门向夕陽。","音书須數附，莫学晉嵇康。"]', '诗', 'shi', '', NULL, '送胡校書秩滿歸河中 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a67496c-9ed1-4be4-b7f3-2d2aca1afed5', '送河中張胄曹往太原計會迴', '送河中張胄曹往太原計會迴', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["北風長至遠，四牡向幽幷。","衰木新田路，寒蕪故絳城。","遙聽邊上信，遠計朔南程。","料變當臨事，遙知外國情。"]', '["北风长至远，四牡向幽幷。","衰木新田路，寒蕪故絳城。","遙听邊上信，远計朔南程。","料变當臨事，遙知外国情。"]', '诗', 'shi', '', NULL, '送河中張胄曹往太原計會迴 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0563bfad-8105-464d-93e5-e219665ee641', '送郭正字歸郢上', '送郭正字归郢上', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["濟江篇已出，書府俸猶貧。","積雪商山道，全家楚塞人。","大堤逢落日，廣漢望通津。","却別漁潭下，驚鷗那可親。"]', '["濟江篇已出，书府俸猶貧。","積雪商山道，全家楚塞人。","大堤逢落日，廣漢望通津。","却別漁潭下，驚鷗那可親。"]', '诗', 'shi', '', NULL, '送郭正字歸郢上 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52011da-df42-4f09-a561-8ecff7f4068b', '題李孝廉書房', '題李孝廉书房', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["野情專易外，一室向青山。","業就三編絕，心通萬事閑。","鶯稀春木上，草徧暮堦間。","莫道歸繻在，來時棄故關。"]', '["野情專易外，一室向青山。","業就三編絕，心通万事闲。","鶯稀春木上，草徧暮堦间。","莫道归繻在，来时棄故关。"]', '诗', 'shi', '', NULL, '題李孝廉書房 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e622da-1691-44d0-a29f-6cba13842ce1', '酬暢當', '酬暢當', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["同遊漆沮後，已是十年餘。","幾度曾相夢，何時定得書。","月高城影盡，霜重柳條疎。","且對尊中酒，千般想未如。"]', '["同游漆沮後，已是十年餘。","幾度曾相梦，何时定得书。","月高城影尽，霜重柳條疎。","且对尊中酒，千般想未如。"]', '诗', 'shi', '', NULL, '酬暢當 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb47ff3-5956-4f1e-bd84-523447c91425', '留別解縣韓明府', '留別解縣韓明府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["閑人州縣厭，賤士友朋譏。","朔雪逢初下，秦關獨暮歸。","寒茅下原淺，殘雪過風微。","一路何相慰，唯君能政稀。"]', '["闲人州縣厭，賤士友朋譏。","朔雪逢初下，秦关独暮归。","寒茅下原淺，殘雪過风微。","一路何相慰，唯君能政稀。"]', '诗', 'shi', '', NULL, '留別解縣韓明府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f67506-3cbd-4655-9a40-fc8ce7222f9e', '遊鍾山紫芝觀', '游鍾山紫芝观', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["繫舟仙宅下，清磬落春風。","雨數芝田長，雲開石路重。","古房清磴接，深殿紫烟濃。","鶴駕何時去，遊人自不逢。"]', '["繫舟仙宅下，清磬落春风。","雨數芝田长，云开石路重。","古房清磴接，深殿紫烟濃。","鹤駕何时去，游人自不逢。"]', '诗', 'shi', '', NULL, '遊鍾山紫芝觀 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8544c4dd-7019-4a69-9bc6-7676c21863cb', '晚秋宿裴員外寺院', '晚秋宿裴員外寺院', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["仲言多麗藻，晚水獨芙蓉。","梁苑仍秋過，仁祠又夜逢。","回林通暗竹，去雨帶寒鐘。","願向空門裏，修持比晝龍。"]', '["仲言多丽藻，晚水独芙蓉。","梁苑仍秋過，仁祠又夜逢。","回林通暗竹，去雨带寒鐘。","願向空门裏，修持比晝龙。"]', '诗', 'shi', '', NULL, '晚秋宿裴員外寺院 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee196c3-b71a-4743-9033-fcc203f71005', '秋夜喜盧司直嚴少府訪宿', '秋夜喜盧司直嚴少府訪宿', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["寂寂閉層城，悠悠此夜情。","早涼過鬢髮，秋思入柴荆。","嚴子多高趣，盧公有盛名。","還如杜陵下，暫拂蔣元卿。"]', '["寂寂閉層城，悠悠此夜情。","早涼過鬢髮，秋思入柴荆。","嚴子多高趣，盧公有盛名。","還如杜陵下，暫拂蔣元卿。"]', '诗', 'shi', '', NULL, '秋夜喜盧司直嚴少府訪宿 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ccdc1f-1902-488b-b7de-d773ec7bb56c', '下邽客舍喜叔孫主簿鄭少府見過', '下邽客舍喜叔孫主簿鄭少府见過', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["良宵復杪秋，把酒說羇遊。","落木東西別，寒萍遠近流。","蕭條旅館月，寂歷曙更籌。","不是仇梅至，何人問百憂。"]', '["良宵复杪秋，把酒说羇游。","落木东西別，寒萍远近流。","蕭條旅館月，寂歷曙更籌。","不是仇梅至，何人问百憂。"]', '诗', 'shi', '', NULL, '下邽客舍喜叔孫主簿鄭少府見過 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d8b98d-6b4a-4eb0-b915-988296f67cd3', '盩厔客舍', '盩厔客舍', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["寥寂荒壘下，客舍雨微微。","門見苔生滿，心慙吏到稀。","籬花看未發，海燕欲先歸。","無限堪惆悵，誰家復搗衣。"]', '["寥寂荒壘下，客舍雨微微。","门见苔生满，心慙吏到稀。","籬花看未發，海燕欲先归。","無限堪惆悵，誰家复捣衣。"]', '诗', 'shi', '', NULL, '盩厔客舍 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94209809-403f-4bb0-9fef-04b603bed685', '宿韋員外宅', '宿韋員外宅', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["傳經韋相後，賜筆漢家郎。","幽閣諸生會，寒宵幾刻長。","座中燈泛酒，簷外月如霜。","人事多飄忽，邀歡詎可忘。"]', '["傳經韋相後，賜笔漢家郎。","幽閣諸生會，寒宵幾刻长。","座中灯泛酒，簷外月如霜。","人事多飄忽，邀歡詎可忘。"]', '诗', 'shi', '', NULL, '宿韋員外宅 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b8408c-490a-4ea1-a458-f3249bb7ddaf', '登沃州山', '登沃州山', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["沃州初望海，攜手盡時髦。","小暑開鵬翼，新蓂長鷺濤。","月如芳草遠，身比夕陽高。","羊祜傷風景，誰云異我曹。"]', '["沃州初望海，携手尽时髦。","小暑开鵬翼，新蓂长鷺濤。","月如芳草远，身比夕陽高。","羊祜傷风景，誰云異我曹。"]', '诗', 'shi', '', NULL, '登沃州山 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79ebb031-490c-44b2-b892-b779ace88f3a', '宿岐山姜明府廳', '宿岐山姜明府廳', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["暝色休羣動，秋齋遠客情。","細風和雨氣，寒竹度簾聲。","日覺蹉跎近，天敎嬾慢成。","誰能謁卿相，朝夕筭浮榮。"]', '["暝色休羣动，秋斋远客情。","細风和雨氣，寒竹度簾声。","日覺蹉跎近，天敎嬾慢成。","誰能謁卿相，朝夕筭浮榮。"]', '诗', 'shi', '', NULL, '宿岐山姜明府廳 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d4f851-0627-49b5-b0b7-fdb4aefc4429', '上巳日', '上巳日', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["共來修禊事，內顧一悲翁。","玉鬢風塵下，花林絲管中。","故山離水石，舊侶失鵷鴻。","不及遊魚樂，裴回蓮葉東。"]', '["共来修禊事，內顧一悲翁。","玉鬢风塵下，花林絲管中。","故山離水石，旧侶失鵷鴻。","不及游鱼乐，裴回蓮葉东。"]', '诗', 'shi', '', NULL, '上巳日 耿湋 shi');
